// 🆕 Phase ৫ — getState()-সিঙ্কড write-through Map। subscribeWithSelector দিয়ে
// products/customers/invoices array বদলালেই (set() বা patch() যেভাবেই বদলাক না
// কেন) নতুন Map রিবিল্ড হয়ে store-এ ফিরে বসে। এটা render-cycle-এর বাইরে, তাই
// useAppStore.getState().productsById.get(id) সবসময়-ফ্রেশ (getState() ঠিক এই
// গ্যারান্টির জন্যই আগে ব্যবহার হতো, .find() দিয়ে) — কিন্তু এখন O(1)।
// ⚠️ eternal rule অনুযায়ী নোট: এই তিনটা subscribe শুধুমাত্র নিজ নিজ selector
// (products/customers/invoices) বদলালেই ফায়ার করে (subscribeWithSelector-এর
// কাজই এটা), productsById/customersById/invoicesById নিজে সেট করাটা নতুন করে
// products/customers/invoices বদলায় না — তাই ইনফিনিট লুপের ঝুঁকি নেই।
useAppStore.subscribe(
  (s) => s.products,
  (products) => { useAppStore.getState().set("productsById", new Map(products.map(p => [String(p.id), p]))); },
  { fireImmediately: true }
);
useAppStore.subscribe(
  (s) => s.customers,
  (customers) => { useAppStore.getState().set("customersById", new Map(customers.map(c => [String(c.id), c]))); },
  { fireImmediately: true }
);
useAppStore.subscribe(
  (s) => s.invoices,
  (invoices) => { useAppStore.getState().set("invoicesById", new Map(invoices.map(i => [String(i.id), i]))); },
  { fireImmediately: true }
);

// ── Fix 5: ErrorBoundary — প্রতিটি tab crash isolate করে ──────────────────────
class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null, info: null };
  }
  static getDerivedStateFromError(error) {
    return { hasError: true, error };
  }
  componentDidCatch(error, info) {
    console.error("[ErrorBoundary] Tab crash caught:", error, info?.componentStack || "");
    this.setState({ info });
    logErrorToCentral("app:crash", error, { componentStack: (info?.componentStack || "").slice(0, 500) });
  }
  render() {
    if (this.state.hasError) {
      const T = this.props.T || {};
      const bg   = T.card  || "#111827";
      const text = T.text  || "#f1f5f9";
      const sub  = T.sub   || "#94a3b8";
      return (
        <div style={{ padding: 32, textAlign: "center", color: text, background: bg, borderRadius: 16, margin: 16 }}>
          <div style={{ fontSize: 44, marginBottom: 12 }}>⚠️</div>
          <div style={{ fontWeight: 800, fontSize: 17, marginBottom: 8 }}>
            এই পেজে একটি সমস্যা হয়েছে
          </div>
          <div style={{ fontSize: 12, color: sub, marginBottom: 12, wordBreak: "break-word", maxWidth: 320, margin: "0 auto 12px" }}>
            {this.state.error?.message || "অজানা ত্রুটি"}
          </div>
          {this.state.error?.stack && (
            <div style={{
              fontSize: 10, color: sub, opacity: 0.8, textAlign: "left", maxWidth: 360,
              margin: "0 auto 12px", maxHeight: 160, overflow: "auto", background: "#00000033",
              borderRadius: 8, padding: 8, fontFamily: "monospace", whiteSpace: "pre-wrap", wordBreak: "break-all"
            }}>
              {this.state.error.stack}
              {this.state.info?.componentStack ? "\n---component stack---\n" + this.state.info.componentStack : ""}
            </div>
          )}
          <button
            style={{ background: "#0ea5e9", color: "#fff", border: "none", borderRadius: 10, padding: "11px 24px", fontWeight: 700, fontSize: 14, cursor: "pointer" }}
            onClick={() => this.setState({ hasError: false, error: null, info: null })}
          >
            🔄 পুনরায় চেষ্টা করুন
          </button>
        </div>
      );
    }
    return this.props.children;
  }
}

// ═══════════════════════════════════════════════════════════════════════════════
// 🇧🇩 GLOBAL BENGALI IME SYSTEM — Avro / Ridmik / Gboard সব keyboard smooth
// ═══════════════════════════════════════════════════════════════════════════════
//
// সমস্যার মূল কারণ:
//   Android WebView-এ বাংলা IME (Avro, Ridmik, Gboard Bengali) লেখার সময়
//   React-এর synthetic onChange বাধা দেয়। কারণ:
//   1. React controlled input (value=) IME composition এর মাঝে DOM reset করে
//   2. compositionend Android-এ reliably fire হয় না (বিশেষত Ridmik-এ)
//   3. React 18-এর batching আরো delay তৈরি করে
//
// সমাধান (Tally Hisab approach):
//   • Global MutationObserver + input event interceptor
//   • সব input/textarea-এ automatically attach হয়
//   • React synthetic event bypass করে native DOM event ব্যবহার করে
//   • IME composition চলাকালীন React update suppress করে
//   • composition শেষে একবারই React state update করে
//
// ─── useBanglaInput hook (component-level) ────────────────────────────────────
function useBanglaInput(value, onChange) {
  const setRef = useCallback((el) => {
    if (!el || el._sbmBengali) return;
    el._sbmBengali = true;
    el.value = value ?? "";
    // setter শুধু compositionend + blur + non-composing input এ
    // typing চলাকালীন onChange নেই → re-render নেই → DOM reset নেই
    el.addEventListener("compositionend", () => { onChange(el.value); }, { passive: true });
    el.addEventListener("blur", () => { onChange(el.value); }, { passive: true });
    el.addEventListener("input", (e) => { if (!e.isComposing) onChange(el.value); }, { passive: true });
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  return { ref: setRef, defaultValue: value, onChange: () => {} };
}

// ─── useSmartSearch — World-class search: fuzzy, debounce, Bengali IME-safe ──
// Features: debounce 120ms | Bengali composition-safe | fuzzy match | highlight
function useSmartSearch(onSearch, delay = 120) {
  const timerRef = useRef(null);
  // onSearch সবসময় latest version ধরে রাখো — stale closure সমস্যা দূর করে
  const onSearchRef = useRef(onSearch);
  useEffect(() => { onSearchRef.current = onSearch; }, [onSearch]);

  const setRef = useCallback((el) => {
    if (!el || el._sbmSearch) return;
    el._sbmSearch = true;
    const schedule = (val) => {
      clearTimeout(timerRef.current);
      timerRef.current = setTimeout(() => onSearchRef.current(val), delay);
    };
    // Android WebView-এ compositionstart/end reliably fire হয় না।
    // autocomplete suggestion bar থাকলে সব typing composing state-এ থাকে।
    // তাই composingRef বাদ দিয়ে সরাসরি input event-এ search করো।
    // compositionend-এও করো যাতে Bengali word commit হলে সাথে সাথে search হয়।
    el.addEventListener("compositionend", (e) => { schedule(e.target.value); }, { passive: true });
    el.addEventListener("input", (e) => { schedule(e.target.value); }, { passive: true });
    el.addEventListener("keydown", (e) => { if (e.key === "Escape") { el.value = ""; onSearchRef.current(""); } }, { passive: true });
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => () => { clearTimeout(timerRef.current); }, []);
  return { ref: setRef, defaultValue: "", onChange: () => {} };
}

// alias for backward compat
const useBanglaSearch = useSmartSearch;

// ─── parseBatchNum — বাংলা ও ইংরেজি সংখ্যা দুটোই handle করে ─────────────────
// "ব্যাচ-1" → 1, "ব্যাচ-১" → 1, "batch-2" → 2, "ব্যাচ-0" → 0
function parseBatchNum(batchStr) {
  if (!batchStr) return 0;
  const bnMap = { "০":0,"১":1,"২":2,"৩":3,"৪":4,"৫":5,"৬":6,"৭":7,"৮":8,"৯":9 };
  // বাংলা সংখ্যা → ইংরেজি
  const normalized = batchStr.replace(/[০-৯]/g, d => bnMap[d] ?? d);
  const num = parseInt(normalized.replace(/[^0-9]/g, ""), 10);
  return isNaN(num) ? 0 : num;
}

// ─── bnMonthYear — "YYYY-MM-01" → "মার্চ, ২০২৭" (রিভিউ লিস্ট ও ব্যাচ-এডিটে পুনঃব্যবহার) ──
const BN_MONTH_NAMES = ["জানুয়ারি","ফেব্রুয়ারি","মার্চ","এপ্রিল","মে","জুন","জুলাই","আগস্ট","সেপ্টেম্বর","অক্টোবর","নভেম্বর","ডিসেম্বর"];
function bnMonthYear(dateStr) {
  if (!dateStr || !/^\d{4}-\d{2}/.test(dateStr)) return "";
  const y = dateStr.slice(0, 4);
  const m = parseInt(dateStr.slice(5, 7), 10);
  return (m >= 1 && m <= 12) ? `${BN_MONTH_NAMES[m - 1]}, ${y}` : "";
}

// calcNextBatch, isBatchExpired — এখন src/logic.js থেকে import করা (উপরে দেখুন)।

// getSortedActiveBatches, getActiveBatch, getSellableStock — এখন src/logic.js থেকে import করা।

// ─── computeStockDeductionFIFO — একটা পণ্য থেকে qty বাদ দিলে নতুন stock/batches
// কী হবে তা বিশুদ্ধভাবে (pure function, কোনো state/side-effect নেই) হিসেব করে।
// 🔴 এন্টারপ্রাইজ-লেভেল ফিক্স (স্টক race condition): আগে এই FIFO deduction
// logic শুধু sale-completion কোডের ভেতরে (local `products` state থেকে) সরাসরি
// লেখা ছিল, আর ফলাফল সরাসরি `setProducts` দিয়ে স্থানীয়ভাবে বসিয়ে সেটাই
// generic diff-push দিয়ে Firestore-এ (absolute value হিসেবে) পাঠানো হতো।
// দুই ডিভাইস একই পণ্য প্রায় একই সময়ে বিক্রি করলে দুজনেই নিজের নিজের stale
// লোকাল stock থেকে হিসেব করত — শেষে যেটা Firestore-এ পৌঁছাত সেটাই জিতত, আরেকটার
// deduction সম্পূর্ণ হারিয়ে যেত (overselling ঝুঁকি) — ঠিক customer.balance-এ
// যে বাগ ছিল (এখন transactionUpdateBalance() দিয়ে ফিক্স করা) তারই প্যারালাল
// কেস। এই ফাংশনটাকে আলাদা করে বের করা হলো যাতে এটা:
//   ১. sale-এর সময় optimistic local UI আপডেটে ব্যবহার করা যায় (আগের মতোই), এবং
//   ২. FSS.transactionUpdateStock()-এর ভেতরে সার্ভারের বর্তমান (up-to-date)
//      product ডকুমেন্টে প্রয়োগ করে atomically লেখা যায় (নিচে দেখুন)।
function computeStockDeductionFIFO(product, qty) {
  if (!product || product.productType === "service") {
    return { newStock: product?.stock ?? 0, updatedBatches: product?.batches || [], batchNo: "", costPrice: product?.costPrice ?? 0, expiryDate: "", batchBreakdown: [] };
  }
  const newStock = Math.max(0, (product.stock || 0) - qty);
  let remaining = qty;
  const sortedBatches = getSortedActiveBatches(product);
  let batchNo = "", costPrice = product.costPrice ?? 0, expiryDate = "";
  // 🔴 ফিক্স (রুট কজ — একাধিক ব্যাচ থেকে একসাথে বিক্রি হলে ভয়েডে সব এক ব্যাচে
  // মিশে যাওয়া): আগে এখানে শুধু sortedBatches[0]-এর batchNo/expiryDate রাখা
  // হতো — বিক্রির qty একাধিক ব্যাচ থেকে কাটা হলেও (যেমন ব্যাচ-A থেকে ৩ +
  // ব্যাচ-B থেকে ৩) সেই বিভাজনের তথ্য কোথাও সংরক্ষণ হতো না, তাই ভয়েড করার
  // সময় সবকিছু একটা মাত্র ব্যাচ/এক্সপায়ারিতে ফেরত যেত। এখন প্রতিটা ব্যাচ থেকে
  // কত কাটা হলো তার সম্পূর্ণ breakdown আলাদাভাবে রাখা হচ্ছে, যাতে caller
  // (createInvoice) এটা ইনভয়েস আইটেমে সেভ করতে পারে আর voidInvoice() পরে
  // প্রতিটা ব্যাচ আলাদাভাবে ঠিক তার নিজের qty/expiryDate সহ ফেরত দিতে পারে।
  const batchBreakdown = [];
  if (sortedBatches.length > 0) {
    let calcRem = qty, totalC = 0, totalQ = 0;
    sortedBatches.forEach(b => {
      if (calcRem <= 0) return;
      const d = Math.min(calcRem, b.qty || 0);
      totalC += d * (b.costPrice ?? product.costPrice ?? 0);
      totalQ += d;
      calcRem -= d;
      if (d > 0) {
        batchBreakdown.push({
          batchNo: b.batchNo || "",
          qty: d,
          costPrice: b.costPrice ?? product.costPrice ?? 0,
          expiryDate: b.expiryDate || b.expiry || "",
        });
      }
    });
    costPrice = totalQ > 0 ? totalC / totalQ : (product.costPrice ?? 0);
    batchNo = sortedBatches[0].batchNo || "";
    // 🔴 ফিক্স (রুট কজ — ভয়েড করা ইনভয়েসে এক্সপায়ারি ডেট না থাকা, আসল কারণ):
    // আগে expiryDate এখানে ফেরত দেওয়া হতোই না — caller পরে `updatedBatches`
    // (নিচে) থেকে ব্যাচ খুঁজে expiry বের করার চেষ্টা করত, কিন্তু বিক্রিত ব্যাচের
    // পুরো qty শেষ হয়ে গেলে (সাধারণ ঘটনা — একটা ব্যাচ থেকেই পুরো বিক্রি হলে)
    // সেই ব্যাচ নিচের `.filter(b => b.qty > 0)`-এ বাদ পড়ে যেত, তাই কখনোই খুঁজে
    // পাওয়া যেত না। এখন deduction গণনার এই মুহূর্তেই (ব্যাচ এখনো হাতে থাকা
    // অবস্থায়) মূল বিক্রিত ব্যাচের expiryDate সরাসরি সংরক্ষণ করা হচ্ছে।
    expiryDate = sortedBatches[0].expiryDate || sortedBatches[0].expiry || "";
  } else {
    // 🔴 ফিক্স (রুট কজ — batch-tracking ছাড়া legacy পণ্যে ভয়েডে এক্সপায়ারি হারানো):
    // এই পণ্যের কোনো ট্র্যাক করা batches[] নেই (getSortedActiveBatches তাই []
    // দিয়েছে) — কিন্তু getSellableStock()-এর legacy branch-এর মতোই, পণ্যের
    // নিজের top-level expiryDate থাকতে পারে। আগে এই branch-এ expiryDate সবসময়
    // "" থেকে যেত, তাই বিক্রির মুহূর্তেই এক্সপায়ারি হারিয়ে যেত আর ভয়েড করার
    // সময় ফেরত দেওয়ার মতো কোনো তথ্যই থাকত না। এখন top-level expiryDate থেকে
    // fallback করা হচ্ছে।
    costPrice = product.costPrice ?? 0;
    expiryDate = product.expiryDate || "";
    if (qty > 0) batchBreakdown.push({ batchNo: "", qty, costPrice, expiryDate });
  }
  // 🔴 ফিক্স (ক্রিটিক্যাল — মেয়াদোত্তীর্ণ ব্যাচ নীরবে হারিয়ে যাওয়া): আগে এখানে
  // sortedBatches (= getSortedActiveBatches(product), যেটা মেয়াদোত্তীর্ণ ও
  // qty<=0 ব্যাচ বাদ দিয়ে ফিল্টার করে) থেকেই সরাসরি updatedBatches বানানো হতো,
  // আর caller (createInvoice) সেটা দিয়ে পণ্যের পুরো `batches[]` অ্যারে বদলে
  // দিত। ফলে যেকোনো পণ্যের একটা মেয়াদোত্তীর্ণ ব্যাচে এখনো ভৌত স্টক (qty>0)
  // থাকলেও — সেই পণ্যের *যেকোনো* সাধারণ বিক্রি হলেই (এমনকি সেই ব্যাচ থেকে না
  // কেটেও) সেটা নীরবে `batches[]` থেকে মুছে যেত (removeExpiredBatch()-এর
  // মাধ্যমে সরিয়ে কোনো stockMovement/monthExpiredValue লগ না রেখেই) — ফলে
  // দোকানদার তার শেলফে থাকা মেয়াদোত্তীর্ণ পণ্যের রেকর্ড হারাতেন এবং "এই মাসের
  // মেয়াদোত্তীর্ণ পণ্যের মূল্য" KPI-ও ঘটনাটা ধরতে পারত না। এখন পূর্ণ
  // product.batches অ্যারের ওপর ম্যাপ করা হচ্ছে — শুধু যেসব ব্যাচ থেকে সত্যিই
  // কাটা হয়েছে (sortedBatches-এ ছিল, একই object reference দিয়ে মেলানো) সেগুলোর
  // qty আপডেট হয় (এবং শূন্য হয়ে গেলে বাদ পড়ে, আগের আচরণের মতোই); বাকি সব
  // ব্যাচ (মেয়াদোত্তীর্ণ বা অন্য কোনো কারণে sortedBatches-এ বাদ পড়া) অপরিবর্তিত
  // থেকে যায়।
  const _deductedQtyByRef = new Map();
  sortedBatches.forEach(b => {
    if (remaining <= 0) return;
    const deduct = Math.min(remaining, b.qty || 0);
    remaining -= deduct;
    _deductedQtyByRef.set(b, (b.qty || 0) - deduct);
  });
  const updatedBatches = (product.batches || []).reduce((acc, b) => {
    if (_deductedQtyByRef.has(b)) {
      const newQty = _deductedQtyByRef.get(b);
      if (newQty > 0) acc.push({ ...b, qty: newQty }); // পুরোপুরি শেষ হয়ে গেলে বাদ (আগের আচরণের মতোই)
    } else {
      acc.push(b); // sortedBatches-এ ছিল না (মেয়াদোত্তীর্ণ ইত্যাদি) — অপরিবর্তিত
    }
    return acc;
  }, []);
  return { newStock, updatedBatches, batchNo, costPrice, expiryDate, batchBreakdown };
}

// ─── smartMatch — fuzzy/contains scorer for Bengali+English ───────────────────
// Returns: 2=exact start, 1=contains/fuzzy, 0=no match
// ─── levenshteinDistance — দুটো স্ট্রিং কতটা কাছাকাছি (এডিট-ডিস্ট্যান্স) তা মাপা ───
// SupplierPicker-এ "did you mean" সাজেশনের জন্য ব্যবহৃত — normalizeSupplierKey
// শুধু Ltd./পাংচুয়েশন/স্পেস-জাতীয় নিয়মমাফিক ভিন্নতা ধরে, কিন্তু আসল বানান-ভুল
// (Boshundhora vs Bashundhara) ধরতে অক্ষরের পার্থক্য গোনা দরকার।
function levenshteinDistance(a, b) {
  a = a || ""; b = b || "";
  const m = a.length, n = b.length;
  if (m === 0) return n;
  if (n === 0) return m;
  let prev = Array.from({ length: n + 1 }, (_, j) => j);
  for (let i = 1; i <= m; i++) {
    const cur = [i];
    for (let j = 1; j <= n; j++) {
      cur[j] = a[i - 1] === b[j - 1]
        ? prev[j - 1]
        : 1 + Math.min(prev[j - 1], prev[j], cur[j - 1]);
    }
    prev = cur;
  }
  return prev[n];
}

// ─── smartMatch — সার্চ রেলিভেন্স স্কোরিং ───────────────────────────────────
// 🔴 রুট-কজ ফিক্স (১১ আগস্ট ২০২৬, "সার্চ একুরেট না" বাগ): আগে এই ফাংশন মাত্র ৪টা
// ধাপে স্কোর দিত (exact=3, startsWith=2, includes=1, fuzzy=0.5), আর
// "startsWith" ধাপে "Na" লিখলে "Napa Rapid" আর "Navana" (কোম্পানির নাম) দুটোই
// সমান স্কোর (2) পেত — কারণ প্রিফিক্স-ম্যাচ হলেই সমান নম্বর, প্রিফিক্সের পরের
// অক্ষরটা শব্দের শেষ (স্পেস/বিরতি) নাকি মাঝখানে (যেমন "Napa-xin") তার কোনো
// পার্থক্য করত না। ফলে "Napa" নামের পণ্য আর "Napaxin" নামের ভিন্ন পণ্য একই
// স্কোরে টাই করত, আর টাই হলে কোনো সেকেন্ডারি সর্ট না থাকায় মূল অ্যারের
// (যোগ করার) ক্রম অনুযায়ী এলোমেলোভাবে একটা আগে/পরে বসত — তাই একুরেট মনে
// হতো না। এখন প্রিফিক্স-ম্যাচকে দুই ভাগে ভাগ করা হলো: "word-boundary prefix"
// (যেমন "Napa " — পরের অক্ষর স্পেস/সংখ্যা/চিহ্ন) সবচেয়ে বেশি স্কোর পাবে,
// আর "mid-word prefix" (যেমন "Napa" থেকে "Napaxin") তার চেয়ে কম। এছাড়া
// "শব্দের মাঝে হুবহু-শব্দ ম্যাচ" (যেমন "Napa Rapid"-এ "rapid" খোঁজা) একটা
// আলাদা মধ্যম-স্কোর পায়, শুধু substring-ম্যাচের চেয়ে বেশি প্রাসঙ্গিক ধরে।
function smartMatch(text, query) {
  if (!query) return 1;
  if (!text) return 0;
  const t = text.toLowerCase();
  const q = query.toLowerCase().trim();
  if (!q) return 1;
  if (t === q) return 100;
  if (t.startsWith(q)) {
    const nextChar = t[q.length];
    const isWordBoundary = !nextChar || !/[a-z0-9]/i.test(nextChar);
    return isWordBoundary ? 90 : 70; // "Napa " → 90, "Napa"+"xin" → 70
  }
  const esc = q.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  if (new RegExp("(^|[^a-z0-9])" + esc, "i").test(t)) return 50; // শব্দের শুরুতে (মাঝপথে) ম্যাচ, যেমন "Tab. Napa"-তে "Napa"
  if (t.includes(q)) return 30; // যেকোনো জায়গায় substring
  // fuzzy: সিকোয়েন্সে সব ক্যারেক্টার পাওয়া গেলে
  let ti = 0, qi = 0;
  while (ti < t.length && qi < q.length) {
    if (t[ti] === q[qi]) qi++;
    ti++;
  }
  return qi === q.length ? 5 : 0;
}

// 🆕 পণ্য-সার্চের জন্য ওয়েটেড স্কোর — শুধু নাম, সিরিয়াল, বারকোড দিয়ে ম্যাচ করে।
// 🔴 (ইউজার-রিকোয়েস্ট) কোম্পানির নাম দিয়ে ম্যাচ করা বাদ দেওয়া হলো — এটা
// থাকলে ভিন্ন পণ্য শুধু একই কোম্পানির হওয়ার কারণে সার্চ ফলাফলে চলে আসত
// (যেমন "Na" লিখলে "Navana" কোম্পানির "Curafin" চলে আসত, যদিও পণ্যের নামে
// "Na" নেই)।
function productMatchScore(p, q) {
  return Math.max(
    smartMatch(p.name, q) * 1.0,
    smartMatch(p.serialStr, q) * 0.95,
    smartMatch(p.barcode || "", q) * 0.85,
  );
}

// 🆕 সমান স্কোরের মধ্যে ধারাবাহিক (deterministic) ক্রম দিতে সেকেন্ডারি
// টাই-ব্রেকার — ছোট/কাছের নাম আগে, তারপর বর্ণানুক্রমিক। এটা না থাকলে সমান
// স্কোরের আইটেমগুলো মূল অ্যারের ক্রম অনুযায়ী এলোমেলোভাবে বসত।
// 🆕 কাস্টমার-সার্চের জন্য ওয়েটেড স্কোর — নাম প্রথম প্রায়োরিটি, তারপর মোবাইল/সিরিয়াল
function customerMatchScore(c, q) {
  return Math.max(
    smartMatch(c.name || "", q) * 1.0,
    smartMatch(c.mobile || "", q) * 0.9,
    smartMatch(c.serialStr || "", q) * 0.85,
  );
}

function bySearchScore(a, b) {
  if (b._score !== a._score) return b._score - a._score;
  const an = (a.name || "").length, bn = (b.name || "").length;
  if (an !== bn) return an - bn;
  return (a.name || "").localeCompare(b.name || "");
}

// ─── HighlightText — query match এর অংশ highlight করে ──────────────────────
function HighlightText({ text, query, style, highlightColor = "#22c55e" }) {
  if (!query || !query.trim()) return <span style={style}>{text}</span>;
  const q = query.trim();
  const idx = text.toLowerCase().indexOf(q.toLowerCase());
  if (idx === -1) return <span style={style}>{text}</span>;
  return (
    <span style={style}>
      {text.slice(0, idx)}
      <span style={{ background: highlightColor + "44", color: highlightColor, fontWeight: 800, borderRadius: 3, padding: "0 1px" }}>
        {text.slice(idx, idx + q.length)}
      </span>
      {text.slice(idx + q.length)}
    </span>
  );
}

// 🔴 ফিক্স: সাপ্লায়ার নাম নরমালাইজেশন — "Square Pharmaceuticals Ltd." আর "Square
// Pharmaceuticals" এর মতো একই কোম্পানির সামান্য ভিন্ন বানান (Ltd./Limited/
// Pharmaceuticals/পাংচুয়েশন) আলাদা এন্ট্রি হিসেবে সাজেশনে দুইবার দেখাত। এই
// ফাংশন একটা "মূল নাম" (normalized key) বের করে — নিচে allSuppliers এই key
// দিয়ে ডিডুপ্লিকেট করে, তাই একই কোম্পানি এখন থেকে একবারই দেখাবে।
// (৩১ জুলাই ২০২৬: এখন src/logic.js থেকে import করা হয়, যাতে computeSupplierDueMap-ও
// ঠিক এই একই normalize-লজিক দিয়ে ভিন্ন বানানের সাপ্লায়ার একত্র করতে পারে।)

// ─── SupplierPicker — টাইপাহেড সার্চ-করে-বাছাই সাপ্লায়ার সিলেক্টর ───────────
// BD_PHARMA_COMPANIES (MEDICINE_DATASET থেকে ডিরাইভ করা, ২১১টি) এর মধ্যে ফাজি সার্চ (smartMatch),
// অথবা "নিজে লিখুন" কাস্টম মোড।
function SupplierPicker({ value, onChange, error, T, S, autoFocus, extraSuppliers = [], businessType = "pharmacy" }) {
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const { companies: BD_PHARMA_COMPANIES } = useMedicineDataset(businessType); // লেজি-লোড — এই পিকার খোলা হলেই ফেচ হয়
  // extraSuppliers = দোকানে আগে ম্যানুয়ালি লেখা কাস্টম সাপ্লায়ারের নাম (products/purchaseOrders থেকে) —
  // এগুলো তালিকায় যুক্ত হবে যাতে একবার লিখলে পরেরবার সাজেশনে দেখা যায় ("অটো-সেভ")
  // 🔴 ফিক্স: normalizeSupplierKey দিয়ে ডিডুপ্লিকেট — একই কোম্পানির একাধিক
  // ভ্যারিয়েন্ট (Ltd./পাংচুয়েশন ভিন্নতা) থাকলে একটাই canonical নাম রাখা হয়।
  // অগ্রাধিকার: (১) দোকানে আগে ব্যবহৃত নাম (extraSuppliers) ডেটাসেটের চেয়ে
  // প্রাধান্য পায় — কারণ সেটাই আপনার real ব্যবহার, (২) একই সোর্সের মধ্যে বেশি
  // সম্পূর্ণ (লম্বা) নামটা রাখা হয় (যেমন পূর্ণ "...Ltd." নাম)।
  const allSuppliers = useMemo(() => {
    const groups = new Map(); // normKey -> { name, fromExtra }
    const addName = (raw, fromExtra) => {
      const n = (raw || "").trim();
      if (!n) return;
      const key = normalizeSupplierKey(n) || n.toLowerCase();
      const existing = groups.get(key);
      if (!existing) {
        groups.set(key, { name: n, fromExtra });
      } else if (fromExtra && !existing.fromExtra) {
        groups.set(key, { name: n, fromExtra }); // দোকানের নিজের নামই canonical
      } else if (fromExtra === existing.fromExtra && n.length > existing.name.length) {
        groups.set(key, { name: n, fromExtra }); // বেশি সম্পূর্ণ নামটা রাখা
      }
    };
    extraSuppliers.forEach(s => addName(s, true));
    BD_PHARMA_COMPANIES.forEach(s => addName(s, false));
    return Array.from(groups.values()).map(g => g.name);
  }, [extraSuppliers, BD_PHARMA_COMPANIES]);
  const [customMode, setCustomMode] = useState(() => !!value && !allSuppliers.includes(value));

  const filtered = useMemo(() => {
    const q = query.trim();
    if (!q) return allSuppliers.slice(0, 30);
    return allSuppliers
      .map(c => ({ c, s: smartMatch(c, q) }))
      .filter(x => x.s > 0)
      .sort((a, b) => b.s - a.s || a.c.length - b.c.length || a.c.localeCompare(b.c))
      .slice(0, 30)
      .map(x => x.c);
  }, [query, allSuppliers]);

  // 🆕 ফিক্স (৩১ জুলাই ২০২৬ — সাপ্লায়ার টাইপো প্রতিরোধ, permanent/root-cause fix):
  // এতদিন "নিজে লিখুন" মোডে যেকোনো বানান সরাসরি সেভ হয়ে যেত, তাই নতুন টাইপো
  // (Boshundhora, Jolly camemical ইত্যাদির মতো) ভবিষ্যতেও তৈরি হতেই থাকত —
  // রিপোর্ট-লেয়ারের merge ফিক্স শুধু already-known ভ্যারিয়েন্ট ধরে, নতুন
  // ভুল বানান ধরতে পারে না। এখন টাইপ করার সময়ই এক্সিস্টিং তালিকার সাথে
  // এডিট-ডিস্ট্যান্স মিলিয়ে কাছাকাছি নাম থাকলে "এটা বলছেন?" সাজেশন দেখানো
  // হয় — ইউজার এক ট্যাপে এক্সিস্টিং (সঠিক) নামটা বেছে নিতে পারেন, ফলে নতুন
  // ডুপ্লিকেট/টাইপো তৈরিই হবে না, উৎসেই সমাধান হয়ে যাবে।
  const didYouMean = useMemo(() => {
    const typed = (value || "").trim();
    if (typed.length < 3) return null;
    const typedKey = normalizeSupplierKey(typed);
    if (!typedKey) return null;
    let best = null, bestDist = Infinity;
    allSuppliers.forEach(s => {
      const sKey = normalizeSupplierKey(s);
      if (sKey === typedKey) return; // হুবহু/নিয়মমাফিক মিল — টাইপো না
      const d = levenshteinDistance(typedKey, sKey);
      const threshold = typedKey.length <= 5 ? 1 : typedKey.length <= 9 ? 2 : 3;
      if (d <= threshold && d < bestDist) { bestDist = d; best = s; }
    });
    return best;
  }, [value, allSuppliers]);

  if (customMode) {
    return (
      <div>
        <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
          <input style={{ ...S.input, flex: 1, marginBottom: 0, border: error ? "1.5px solid #ef4444" : S.input.border }}
            placeholder="সাপ্লায়ারের নাম লিখুন"
            defaultValue={value || ""}
            ref={el => { if (el && !el._b) { el._b = true;
              // বাংলা IME কম্পোজিশনের সাথে কনফ্লিক্ট এড়াতে uncontrolled ইনপুট — controlled হলে প্রতি
              // কি-স্ট্রোকে React re-render কম্পোজিশন ভেঙে দিতে পারে, ফলে টাইপ করা নাম সেভ হতো না।
              el.addEventListener("input", () => onChange(el.value), { passive: true });
              el.addEventListener("compositionend", () => onChange(el.value), { passive: true });
              el.addEventListener("blur", () => onChange(el.value), { passive: true });
            } }}
            onChange={() => {}}
            autoFocus={autoFocus !== false} autoComplete="off" />
          <button type="button" onClick={() => { setCustomMode(false); onChange(""); }}
            style={{ background: "none", border: `1px solid ${T.border}`, color: T.sub, borderRadius: 8, padding: "10px 10px", cursor: "pointer", fontSize: 12, fontFamily: "inherit", flexShrink: 0 }}>↩ তালিকা</button>
        </div>
        {didYouMean && (
          <div onMouseDown={() => { onChange(didYouMean); setCustomMode(false); }}
            style={{ marginTop: 6, display: "flex", alignItems: "center", gap: 6, background: "#f59e0b15", border: "1px solid #f59e0b44", borderRadius: 8, padding: "6px 10px", cursor: "pointer" }}>
            <span style={{ fontSize: 12 }}>💡</span>
            <span style={{ fontSize: 11, color: "#fbbf24" }}>এটা বলছেন কি? <b>{didYouMean}</b> — চাপুন এটাই ব্যবহার করতে</span>
          </div>
        )}
      </div>
    );
  }

  return (
    <div style={{ position: "relative" }}>
      <input
        style={{ ...S.input, marginBottom: 0, paddingRight: 30, border: error ? "1.5px solid #ef4444" : S.input.border }}
        placeholder="🔍 সাপ্লায়ার খুঁজুন..."
        value={open ? query : (value || "")}
        onFocus={() => { setQuery(""); setOpen(true); }}
        onChange={e => { setQuery(e.target.value); setOpen(true); }}
        onBlur={() => setTimeout(() => setOpen(false), 250)}
        autoComplete="off" />
      {value && !open && (
        <button type="button" tabIndex={-1}
          onMouseDown={e => { e.preventDefault(); onChange(""); setQuery(""); }}
          style={{ position: "absolute", right: 8, top: "50%", transform: "translateY(-50%)", background: "none", border: "none", color: "#64748b", cursor: "pointer", fontSize: 14, padding: 4 }}>✕</button>
      )}
      {open && (
        <div style={{ position: "absolute", top: "100%", left: 0, right: 0, background: T.card, border: `1px solid ${T.border}`, borderRadius: 12, zIndex: 200, maxHeight: 240, overflowY: "auto", boxShadow: "0 8px 24px rgba(0,0,0,0.4)", marginTop: 4 }}>
          <div onMouseDown={() => { setCustomMode(true); setOpen(false); }}
            style={{ padding: "10px 14px", cursor: "pointer", color: "#a78bfa", fontWeight: 700, fontSize: 13, borderBottom: `1px solid ${T.border}` }}>
            ✏️ নিজে লিখুন...
          </div>
          {filtered.length === 0 && (
            <div style={{ padding: "10px 14px", color: T.sub, fontSize: 12 }}>কোনো মিল পাওয়া যায়নি — উপরে "নিজে লিখুন" চাপুন</div>
          )}
          {filtered.map(c => (
            <div key={c} onMouseDown={() => { onChange(c); setOpen(false); }}
              style={{ padding: "10px 14px", cursor: "pointer", borderBottom: `1px solid ${T.border}`, fontSize: 13, color: T.text }}>
              <HighlightText text={c} query={query} highlightColor="#a78bfa" />
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// ── আগে ম্যানুয়ালি এন্ট্রি করা সাপ্লায়ারের নাম বের করা (products.company/supplier + purchaseOrders.supplier থেকে) ──
// SupplierPicker-এ extraSuppliers হিসেবে দিলে কাস্টম নাম "অটো-সেভ" হয়ে পরের বার সাজেশনে দেখা যায়
const getKnownSuppliers = (products = [], purchaseOrders = []) => {
  const set = new Set();
  (products || []).forEach(p => { const n = (p.company || p.supplier || "").trim(); if (n) set.add(n); });
  (purchaseOrders || []).forEach(po => { const n = (po.supplier || po.company || "").trim(); if (n) set.add(n); });
  return Array.from(set);
};

// ── আগে "নিজে লিখুন" দিয়ে কাস্টম টাইপ করা ধরন/প্রিফিক্স (products.dosageForm থেকে) বের করা ──
// DOSAGE_FORM_CHIPS-এ চিপ হিসেবে দিলে কাস্টম প্রিফিক্স "অটো-সেভ" হয়ে পরের বার চিপ-লিস্টে দেখা যাবে,
// প্রতিবার নতুন করে টাইপ করতে হবে না। getKnownSuppliers-এর একই প্যাটার্ন।
const getKnownCustomDosageForms = (products = []) => {
  const set = new Set();
  (products || []).forEach(p => {
    const df = (p.dosageForm || "").trim();
    if (df && !DOSAGE_FORM_CHIPS.includes(df)) set.add(df);
  });
  return Array.from(set);
};

// computeSupplierDueMap — এখন src/logic.js থেকে import করা।

// ─── SearchBar — reusable smart search input component ───────────────────────
function SearchBar({ placeholder, value, onChange, onClear, color = "#22c55e", T, S, style, voiceColor, showCount, count, accentBorder, autoFocus }) {
  const [focused, setFocused] = React.useState(false);
  const inputRef = React.useRef(null);
  const { ref: smartRef } = useSmartSearch(onChange, 120); // দ্রুত রেসপন্স — মাত্র ২ অক্ষরেই ফলাফল আসে

  const setRef = React.useCallback((el) => {
    inputRef.current = el;
    smartRef(el);
    if (el && autoFocus) setTimeout(() => el.focus(), 100);
  }, [smartRef, autoFocus]);

  // থিম-নির্বিশেষে সবসময় স্পষ্ট দেখা যায় এমন বর্ডার/গ্লো
  const isLight = T?.bg === "#f8fafc";
  const borderColor = focused ? color : (accentBorder || color + "77");
  const shellBg = isLight
    ? `linear-gradient(135deg, ${color}17, #ffffffdd 65%)`
    : `linear-gradient(135deg, ${color}22, #00000038 65%)`;
  const glowShadow = focused
    ? `0 0 0 3px ${color}33, 0 4px 22px ${color}3d, inset 0 1px 0 rgba(255,255,255,0.08)`
    : `0 2px 12px rgba(0,0,0,0.18), inset 0 1px 0 rgba(255,255,255,0.06)`;

  return (
    <div style={{
      display: "flex", alignItems: "center", gap: 9,
      background: shellBg,
      border: `1.5px solid ${borderColor}`,
      borderRadius: 16,
      padding: "9px 12px",
      transition: "all 0.25s cubic-bezier(0.4,0,0.2,1)",
      boxShadow: glowShadow,
      backdropFilter: "blur(6px)", WebkitBackdropFilter: "blur(6px)",
      animation: "sbmShellIn 0.2s ease",
      ...style,
    }}>
      {/* Search icon চিপ — ফোকাস হলে হালকা পালস */}
      <div style={{
        width: 26, height: 26, borderRadius: 9, flexShrink: 0,
        display: "flex", alignItems: "center", justifyContent: "center",
        background: `linear-gradient(135deg, ${color}3d, ${color}1a)`,
        border: `1px solid ${color}55`,
        animation: focused ? "sbmIconPulse 1.3s ease-in-out infinite" : "none",
      }}>
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none"
          stroke={color} strokeWidth="2.5" strokeLinecap="round">
          <circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/>
        </svg>
      </div>

      <input
        ref={setRef}
        className="sbm-search-input"
        defaultValue={value}
        onChange={() => {}}
        placeholder={showCount && count !== undefined ? `${placeholder} (${count})` : placeholder}
        onFocus={() => setFocused(true)}
        onBlur={() => setFocused(false)}
        autoCorrect="off" autoCapitalize="off" spellCheck={false} autoComplete="off"
        inputMode="text"
        style={{
          flex: 1, background: "none", border: "none", outline: "none",
          color: T?.text || "#f1f5f9",
          fontSize: 13,
          fontFamily: "inherit",
          padding: 0,
          "::placeholder": { color: T?.sub || "#94a3b8" },
        }}
      />

      {/* Clear button — গাঢ় লাল, বড়, পপ-ইন অ্যানিমেশন */}
      {value && (
        <button
          onPointerDown={e => { e.preventDefault(); }}
          onClick={() => { if (inputRef.current) { inputRef.current.value = ""; inputRef.current.focus(); } onClear?.(); onChange(""); }}
          style={{
            background: "linear-gradient(135deg,#dc2626,#7f1d1d)",
            border: "1.5px solid rgba(255,255,255,0.25)",
            color: "#fff", cursor: "pointer", borderRadius: "50%",
            width: 29, height: 29, fontSize: 14, fontWeight: 900,
            display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0,
            boxShadow: "0 2px 10px rgba(153,27,27,0.6)",
            animation: "sbmClearPop 0.22s ease",
            transition: "transform 0.12s",
          }}>
          ✕
        </button>
      )}

      {/* Voice button slot */}
      {voiceColor && <VoiceSearchButton onResult={onChange} color={voiceColor} />}
    </div>
  );
}

// ─── Global Bengali Input Interceptor ────────────────────────────────────────
// Ridmik/Avro Android-এ compositionupdate fire হয় না।
// input event fire হয় isComposing=true সহ — React controlled input তখন
// DOM reset করে। Fix: React fiber থেকে onChange ধরে call করি, তারপর
// requestAnimationFrame-এ DOM value restore করি।
function installGlobalBengaliInterceptor() {
  if (window._sbmGlobalIME) return;
  window._sbmGlobalIME = true;

  function getReactOnChange(el) {
    const key = Object.keys(el).find(k => k.startsWith("__reactFiber") || k.startsWith("__reactInternalInstance"));
    if (!key) return null;
    let fiber = el[key];
    while (fiber) {
      const onChange = fiber.memoizedProps?.onChange;
      if (typeof onChange === "function") return onChange;
      fiber = fiber.return;
    }
    return null;
  }

  function getNativeSetter(el) {
    return Object.getOwnPropertyDescriptor(
      el.tagName === "TEXTAREA" ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype, "value"
    )?.set;
  }

  function patch(el) {
    if (el._sbmIME) return;
    if (!el.matches("input[type='text'], input:not([type]), textarea")) return;
    el._sbmIME = true;

    // Ridmik অভ্র phonetic mode: composition চলাকালীন pending text
    // WebView InputConnection দিয়ে সরাসরি render হয় — কিন্তু Android WebView
    // একটা bug আছে: compositionupdate-এ pending text DOM-এ থাকলেও
    // visually render হয় না যতক্ষণ না repaint trigger হয়।
    // Fix: compositionupdate-এ opacity flicker দিয়ে force repaint করো।
    el.addEventListener("compositionupdate", () => {
      // Force WebView repaint — opacity 1 থেকে 0.999 তারপর আবার 1
      // এটা GPU layer invalidate করে pending text visible করে
      el.style.opacity = "0.999";
      requestAnimationFrame(() => { el.style.opacity = ""; });
    }, { passive: true });
  }

  document.querySelectorAll("input, textarea").forEach(patch);
  new MutationObserver(ms => ms.forEach(m => m.addedNodes.forEach(n => {
    if (n.nodeType !== 1) return;
    if (n.matches?.("input, textarea")) patch(n);
    n.querySelectorAll?.("input, textarea").forEach(patch);
  }))).observe(document.body, { childList: true, subtree: true });
}

// ─── Global Auto-Capitalize (English first letter) ─────────────────────────
// সব input/textarea-তে ইংরেজি লেখার সময় প্রথম অক্ষর স্বয়ংক্রিয়ভাবে বড় হাতের
// (capital) হয়ে যাবে। বাংলা টাইপিং, সংখ্যা, এবং number/password টাইপ ইনপুট
// এর উপর কোনো প্রভাব পড়বে না।
function installGlobalAutoCapitalize() {
  if (window._sbmAutoCap) return () => {};
  window._sbmAutoCap = true;

  function getNativeSetter(el) {
    return Object.getOwnPropertyDescriptor(
      el.tagName === "TEXTAREA" ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype, "value"
    )?.set;
  }

  // React 16+ controlled input-এ programmatically value বদলালে React-এর
  // internal "_valueTracker" ও রিসেট করতে হয় — নাহলে React মনে করে value
  // বদলায়নি (তার নিজের cache অনুযায়ী "আগেই এই value ছিল"), ফলে পরের
  // synthetic event/re-render এ আগের (lowercase) value ফিরিয়ে আনে।
  function resetReactValueTracker(el) {
    try {
      const tracker = el._valueTracker;
      if (tracker) tracker.setValue("");
    } catch (_) {}
  }

  function eligible(el) {
    if (!el || (el.tagName !== "INPUT" && el.tagName !== "TEXTAREA")) return false;
    if (el.tagName === "INPUT") {
      const t = (el.type || "text").toLowerCase();
      // শুধু free-text টাইপের বক্সে কাজ করবে — number/password/date/email-pattern-sensitive বক্স বাদ
      if (!["text", "search", "tel", "url"].includes(t)) return false;
    }
    return true;
  }

  function applyCapitalize(el) {
    const val = el.value;
    if (!val) return;
    const first = val[0];
    if (first < "a" || first > "z") return; // ইংরেজি ছোট হাতের অক্ষর না হলে কিছু করার নেই
    const corrected = first.toUpperCase() + val.slice(1);
    if (corrected === val) return; // ইতিমধ্যে capital — কিছু করার দরকার নেই
    const pos = el.selectionStart, posEnd = el.selectionEnd;
    const setter = getNativeSetter(el);
    resetReactValueTracker(el);
    if (setter) setter.call(el, corrected); else el.value = corrected;
    try { el.setSelectionRange(pos, posEnd); } catch (_) {}
    // React-কে জানাতে সবসময় bubbling native "input" event dispatch করি —
    // fiber walk করে সরাসরি onChange কল করাটা অনির্ভরযোগ্য কারণ React
    // internal synthetic event object আশা করে যা আমরা বানাতে পারি না।
    el.dispatchEvent(new Event("input", { bubbles: true }));
  }

  // ── named handlers — cleanup-এর জন্য reference রাখা জরুরি ─────────────────
  const _capOnInput = (e) => {
    const el = e.target;
    if (!eligible(el)) return;
    if (e.isComposing) return; // composing চলাকালীন স্কিপ — অভ্র/রিদ্মিক/Gboard predictive ভাঙবে না
    applyCapitalize(el);
  };
  // Gboard/SwiftKey-এ ইংরেজি শব্দ টাইপের সময়ও autocorrect-এর জন্য composition span
  // চালু থাকে (isComposing=true থাকে পুরো শব্দ ধরে) — তাই উপরের "input" শোনা যথেষ্ট নয়,
  // composition শেষ হলে (word commit / স্পেস / blur) আবার চেক করতে হয়।
  const _capOnCompositionEnd = (e) => {
    const el = e.target;
    if (!eligible(el)) return;
    applyCapitalize(el);
  };
  // Fallback: ব্লার হওয়ার সময়ও একবার চেক — কোনো কীবোর্ডে compositionend ঠিকমতো না ফায়ার করলেও
  // শেষ মুহূর্তে প্রথম অক্ষর capital করে দেয়।
  const _capOnBlur = (e) => {
    const el = e.target;
    if (!eligible(el)) return;
    applyCapitalize(el);
  };

  document.addEventListener("input",          _capOnInput,          true);
  document.addEventListener("compositionend", _capOnCompositionEnd, true);
  document.addEventListener("blur",           _capOnBlur,           true);

  // ── cleanup: useEffect return-এ call করুন ────────────────────────────────
  return () => {
    window._sbmAutoCap = false;
    document.removeEventListener("input",          _capOnInput,          true);
    document.removeEventListener("compositionend", _capOnCompositionEnd, true);
    document.removeEventListener("blur",           _capOnBlur,           true);
  };
}

// ─── bnRef: Bengali IME-safe ref helper ──────────────────────────────────────
// setter শুধু compositionend + blur + non-composing input এ — typing এ re-render নেই
function bnRef(setter) {
  return (el) => {
    if (!el || el._sbmBengali) return;
    el._sbmBengali = true;
    el.addEventListener("compositionend", () => { setter(el.value); }, { passive: true });
    el.addEventListener("blur", () => { setter(el.value); }, { passive: true });
    el.addEventListener("input", (e) => { if (!e.isComposing) setter(el.value); }, { passive: true });
  };
}
