// ─── হেডার/নেভ টেক্সট অটো-কনট্রাস্ট — ব্যাকগ্রাউন্ড রঙ যেকোনো থিমেই হোক না কেন,
// WCAG relative-luminance হিসাব করে সবচেয়ে স্পষ্ট (সাদা বা গাঢ়) টেক্সট রঙ বেছে নেয়।
// প্রতিটা থিমে আলাদা করে headingColor বসানোর দরকার নেই — এটা রানটাইমে নিজে হিসাব করে।
function _hexToRgbTriplet(hex) {
  const h = (hex || "#000000").replace("#", "");
  const v = h.length === 3 ? h.split("").map(c => c + c).join("") : h;
  const num = parseInt(v, 16) || 0;
  return [(num >> 16) & 255, (num >> 8) & 255, num & 255];
}
function relativeLuminance(hex) {
  const [r, g, b] = _hexToRgbTriplet(hex).map(v => {
    const c = v / 255;
    return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
  });
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}
// bgHex-এর বিপরীতে সবচেয়ে বেশি কনট্রাস্ট থাকা টেক্সট রঙ রিটার্ন করে (সাদা বা গাঢ় স্লেট)
function getContrastText(bgHex, lightText = "#ffffff", darkText = "#0f1115") {
  return relativeLuminance(bgHex) > 0.42 ? darkText : lightText;
}

// ─── Dashboard ভিজ্যুয়াল টোকেন — dark থিমে Glassmorphism, light থিমে POS Bold ──────
// T.dark true হলে (Forest, Volcano, Aurora, Royal Gold ইত্যাদি) → ব্লার+গ্লো গ্লাস কার্ড।
// T.dark false হলে (Light, Rose Gold, Arctic, Mint ইত্যাদি) → কালারফুল সলিড গ্রেডিয়েন্ট কার্ড।
// সব কার্ডের রং থিমের নিজস্ব accent (T.accent) থেকে মোনোক্রোমেটিক ভ্যারিয়েন্ট হিসেবে আসে —
// hue অপরিবর্তিত রেখে শুধু lightness/saturation শিফট করে আলাদা আলাদা কার্ড বোঝানো হয়,
// ফলে প্রতিটা থিমে (Forest/Volcano/Arctic/Rose Gold ইত্যাদি) ড্যাশবোর্ড সেই থিমের নিজস্ব রঙেই দেখাবে।
function hexToHsl(hex) {
  const h = (hex || "#15803d").replace("#", "");
  const v = h.length === 3 ? h.split("").map(c => c + c).join("") : h;
  const num = parseInt(v, 16);
  let r = ((num >> 16) & 255) / 255, g = ((num >> 8) & 255) / 255, b = (num & 255) / 255;
  const max = Math.max(r, g, b), min = Math.min(r, g, b);
  let h2 = 0, s = 0, l = (max + min) / 2;
  if (max !== min) {
    const d = max - min;
    s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
    if (max === r) h2 = (g - b) / d + (g < b ? 6 : 0);
    else if (max === g) h2 = (b - r) / d + 2;
    else h2 = (r - g) / d + 4;
    h2 /= 6;
  }
  return { h: h2 * 360, s: s * 100, l: l * 100 };
}
function hslToHex(h, s, l) {
  s /= 100; l /= 100;
  const c = (1 - Math.abs(2 * l - 1)) * s;
  const x = c * (1 - Math.abs((h / 60) % 2 - 1));
  const m = l - c / 2;
  let r = 0, g = 0, b = 0;
  if (h < 60) { r = c; g = x; b = 0; }
  else if (h < 120) { r = x; g = c; b = 0; }
  else if (h < 180) { r = 0; g = c; b = x; }
  else if (h < 240) { r = 0; g = x; b = c; }
  else if (h < 300) { r = x; g = 0; b = c; }
  else { r = c; g = 0; b = x; }
  const toHex = (v) => Math.round((v + m) * 255).toString(16).padStart(2, "0");
  return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}
// থিমের accent hue ধরে রেখে lightness/saturation শিফট করা ভ্যারিয়েন্ট রং বানায়
function monoVariant(baseHex, dLight = 0, dSat = 0) {
  const { h, s, l } = hexToHsl(baseHex);
  const newS = Math.max(20, Math.min(95, s + dSat));
  const newL = Math.max(8, Math.min(92, l + dLight));
  return hslToHex(h, newS, newL);
}
function getDashTokens(T) {
  const dark = !!T.dark;
  const accent = T.accent || "#15803d";
  // hex → "r,g,b" কনভার্টার (rgba স্ট্রিং বানানোর জন্য)
  const hexToRgb = (hex) => {
    const h = (hex || "#15803d").replace("#", "");
    const v = h.length === 3 ? h.split("").map(c => c + c).join("") : h;
    const num = parseInt(v, 16);
    return `${(num >> 16) & 255},${(num >> 8) & 255},${num & 255}`;
  };
  const accentRgb = hexToRgb(accent);
  // ৬টা কার্ডের জন্য accent hue থেকে lightness/saturation শিফট করা মোনোক্রোমেটিক প্যালেট
  // index: 0=প্রধান(সবচেয়ে উজ্জ্বল) ... 5=সবচেয়ে নিভৃত/নিউট্রাল
  const monoPalette = dark
    ? [
        monoVariant(accent, 8, 5),    // 0 — উজ্জ্বলতম
        monoVariant(accent, -2, 0),   // 1
        monoVariant(accent, -10, -5), // 2
        monoVariant(accent, 14, 10),  // 3 — সবচেয়ে হালকা (positive/profit)
        monoVariant(accent, -16, -8), // 4 — গাঢ়
        "#94a3b8",                    // 5 — নিউট্রাল ধূসর (বাতিল/নিষ্ক্রিয় অবস্থা)
      ]
    : [
        monoVariant(accent, 0, 0),    // 0 — মূল accent
        monoVariant(accent, 8, -5),   // 1
        monoVariant(accent, -10, 5),  // 2
        monoVariant(accent, 14, -10), // 3
        monoVariant(accent, -6, 8),   // 4
        "#64748b",                    // 5 — নিউট্রাল ধূসর
      ];

  if (dark) {
    // ── Glassmorphism (dark থিম) ──
    return {
      dark: true,
      cardBg: "rgba(255,255,255,0.06)",
      cardBorder: "1px solid rgba(255,255,255,0.12)",
      cardBlur: "blur(20px)",
      cardShadow: "0 8px 28px -10px rgba(0,0,0,0.5), inset 0 1px 0 rgba(255,255,255,0.06)",
      heading: T.text || "#fff",
      sub: "rgba(255,255,255,0.5)",
      mono: monoPalette,
      tint: (idx, alpha1 = 0.22, alpha2 = 0.04) => {
        const hex = monoPalette[idx % monoPalette.length];
        const rgb = hexToRgb(hex);
        return {
          hex,
          bg: `linear-gradient(135deg, rgba(${rgb},${alpha1}), rgba(${rgb},${alpha2}))`,
          border: `1px solid rgba(${rgb},0.3)`,
          iconBg: `rgba(${rgb},0.18)`,
          iconBorder: `1px solid rgba(${rgb},0.35)`,
        };
      },
      accentColor: accent,
      accentRgb,
      btnBg: `linear-gradient(135deg, ${accent}, ${T.accentDark || accent})`,
      sectionBarBg: `rgba(${accentRgb},0.10)`,
      sectionBarBorder: `1px solid rgba(${accentRgb},0.22)`,
      sectionBarText: T.headingColor || accent,
    };
  }
  // ── POS Bold (light থিম) ──
  return {
    dark: false,
    cardBg: T.card || "#fff",
    cardBorder: `1px solid ${T.border || "#e2e8f0"}`,
    cardBlur: "none",
    cardShadow: "0 4px 14px rgba(0,0,0,0.06)",
    heading: T.text || "#1e293b",
    sub: T.sub || "#64748b",
    mono: monoPalette,
    tint: (idx) => {
      const hex = monoPalette[idx % monoPalette.length];
      return {
        hex,
        bg: `linear-gradient(135deg, ${hex}, ${shadeColor(hex, -16)})`,
        border: "none",
        solid: true,
      };
    },
    accentColor: accent,
    accentRgb,
    btnBg: `linear-gradient(120deg, ${accent}, ${T.accentDark || accent})`,
    sectionBarBg: `rgba(${accentRgb},0.08)`,
    sectionBarBorder: `1px solid rgba(${accentRgb},0.18)`,
    sectionBarText: accent,
  };
}
// hex রঙকে গাঢ়/হালকা করার ছোট হেল্পার (POS Bold গ্রেডিয়েন্টের জন্য)
function shadeColor(hex, percent) {
  const h = (hex || "#000000").replace("#", "");
  const num = parseInt(h.length === 3 ? h.split("").map(c=>c+c).join("") : h, 16);
  let r = (num >> 16) + Math.round(2.55 * percent);
  let g = ((num >> 8) & 0x00FF) + Math.round(2.55 * percent);
  let b = (num & 0x0000FF) + Math.round(2.55 * percent);
  r = Math.max(0, Math.min(255, r));
  g = Math.max(0, Math.min(255, g));
  b = Math.max(0, Math.min(255, b));
  return `#${(0x1000000 + r * 0x10000 + g * 0x100 + b).toString(16).slice(1)}`;
}

// 🔁 (৯ আগস্ট ২০২৬ — ব্যবহারকারীর অনুরোধে আপডেট) আগে এখানে accent রঙ থেকে
// মাল্টি-কালার গ্র্যাডিয়েন্ট বসানো হতো। এখন সেটা বাদ দিয়ে সলিড, বড়, বোল্ড
// প্রিমিয়াম কালার — ডার্ক থিমে অফ-হোয়াইট (#F8FAFC), লাইট থিমে রিচ চারকোল-ব্ল্যাক
// (#0B1220)। isDark বুলিয়ান দিয়ে কোনটা বসবে ঠিক হয়, size না দিলে ডিফল্ট 34px।
// 🔁 (৯ আগস্ট ২০২৬ — ব্যবহারকারীর ফিডব্যাকে ফিক্স) আগে Anton ফন্ট + WebkitTextStroke +
// ডুপ্লিকেট অফসেট textShadow দিয়ে "ফক্স-বোল্ড" তৈরি করা হতো। এই কম্বিনেশন ছোট সাইজে
// (২২px) গিয়ে অক্ষরগুলো একসাথে ঘেঁটে/স্মাজড দেখাচ্ছিল, আর ৳ চিহ্নে Anton ফন্ট না
// থাকায় Noto Sans Bengali-তে ফলব্যাক করে মিক্সড ফন্ট লুক তৈরি করছিল। এখন শুধু
// Noto Sans Bengali, ওয়েট ৯০০ — পরিষ্কার বোল্ড, কোনো স্ট্রোক/শ্যাডো ট্রিক নেই।
function neonNumStyle(isDark, size = 34) {
  const color = isDark ? "#F8FAFC" : "#0B1220";
  return {
    fontFamily: "'Noto Sans Bengali',sans-serif",
    fontWeight: 900,
    fontSize: size,
    letterSpacing: 0.2,
    lineHeight: 1,
    display: "block",
    width: "100%",
    color,
  };
}

// 🆕 (৯ আগস্ট ২০২৬ — ফিজিবিলিটি ফিক্স) নতুন থিমগুলোর কিছু অ্যাকসেন্ট রঙ (যেমন
// Duolingo সবুজ) monoPalette-এর lightness শিফটের পর যথেষ্ট হালকা হয়ে যায় যে তার
// উপর সাদা টেক্সট আর যথেষ্ট কনট্রাস্ট পায় না। এই হেল্পার প্রতিটা কার্ডের নিজের
// ব্যাকগ্রাউন্ড রঙ (hex) দেখে রানটাইমে সাদা বা গাঢ় টেক্সট বেছে নেয় — যেকোনো
// থিম/যেকোনো অ্যাকসেন্টেই (লাইট মোডের সলিড-কালার কার্ডে) সবসময় ভিজিবল থাকে।
function tintTextColors(hex) {
  const isDarkEnough = relativeLuminance(hex) <= 0.42;
  return isDarkEnough
    ? { value:"#F8FAFC", label:"rgba(248,250,252,0.92)", sub:"rgba(248,250,252,0.7)", icon:"#F8FAFC" }
    : { value:"#0B1220", label:"rgba(11,18,32,0.88)", sub:"rgba(11,18,32,0.62)", icon:"#0B1220" };
}

