// ── Expiry Year/Month Picker ────────────────────────────────────────────────
// মেয়াদ উত্তীর্ণের তারিখ: সাল (YYYY) + মাস (MM) টাইপ করে দিন
// value/onChange: YYYY-MM-DD ফরম্যাটে (date input-এর মতো)
function ExpiryYearMonthPicker({ value, onChange, style = {} }) {
  const BN_MONTHS = ["জানুয়ারি","ফেব্রুয়ারি","মার্চ","এপ্রিল","মে","জুন","জুলাই","আগস্ট","সেপ্টেম্বর","অক্টোবর","নভেম্বর","ডিসেম্বর"];
  const curYear = new Date().getFullYear();
  const years = Array.from({ length: 21 }, (_, i) => curYear - 5 + i); // অতীত সংশোধনের জন্য -৫ থেকে +১৫ বছর

  // 🐛 ফিক্স: আগে external `value` থেকে সরাসরি year/month re-parse করা হতো, যার ফলে
  // year বা month একটিমাত্র সিলেক্ট করলে (অন্যটি খালি থাকায়) onChange("") কল হয়ে আগের
  // আংশিক সিলেকশন মুছে যেত — ফলে দুটো একসাথে কখনো সিলেক্ট হতো না।
  // এখন local state-এ year/month আলাদাভাবে রাখা হচ্ছে যাতে একটি সিলেক্ট করার পর অন্যটি
  // সিলেক্ট করা পর্যন্ত আগের সিলেকশন টিকে থাকে।
  const parseVal = (v) => (v && /^\d{4}-\d{2}/.test(v) ? { year: v.slice(0,4), month: v.slice(5,7) } : { year: "", month: "" });
  const toShorthand = (p) => (p.year && p.month ? `${p.month}/${p.year.slice(2)}` : "");
  const [local, setLocal] = useState(() => parseVal(value));
  const [shorthand, setShorthand] = useState(() => toShorthand(parseVal(value)));
  const [shorthandError, setShorthandError] = useState("");

  // বাহির থেকে value পরিবর্তিত হলে (যেমন: edit মোডে প্রোডাক্ট লোড হলে, অথবা ফর্ম রিসেট হলে) sync করো
  useEffect(() => {
    const p = parseVal(value);
    setLocal(p);
    setShorthand(toShorthand(p));
    setShorthandError("");
  }, [value]);

  const update = (year, month, skipShorthandSync) => {
    setLocal({ year, month });
    if (!skipShorthandSync) { setShorthand(toShorthand({ year, month })); setShorthandError(""); }
    // 🔴 ফিক্স: শুধু সাল+মাস দিলে আগে মাসের ১ম দিন (-01) সংরক্ষণ হতো, ফলে
    // isBatchExpired() ২য় দিন থেকেই পণ্যটিকে মেয়াদোত্তীর্ণ ধরে নিত। এখন
    // মাসের শেষ দিন সংরক্ষণ করা হচ্ছে যাতে পুরো মাস জুড়েই বিক্রয়যোগ্য থাকে।
    if (year && month) onChange(expiryDateFromYearMonth(year, month));
    else onChange("");
  };

  // শর্টহ্যান্ড টাইপ: "126" → "1/26" (জানুয়ারি ২০২৬, লিডিং জিরো ছাড়াই) অথবা
  // "0327" → "03/27" — প্রথম অঙ্ক(গুলো) দেখে স্মার্টভাবে বুঝে নেয় মাস ১ অঙ্কের নাকি ২ অঙ্কের:
  //   • প্রথম অঙ্ক 2-9 → মাস সবসময় ১ অঙ্কের (কোনো মাস ২০-৯৯ দিয়ে শুরু হয় না)
  //   • প্রথম অঙ্ক 0    → মাস ২ অঙ্কের (01-09)
  //   • প্রথম অঙ্ক 1    → ৩য়/৪র্থ অঙ্ক না দেখে নিশ্চিত বলা যায় না (দেখুন নিচের ফিক্স নোট)
  //
  // 🐛 ফিক্স: আগে এই সিদ্ধান্তটা মাত্র ২টা অঙ্ক টাইপ হওয়ার পরই পাকা করে ফেলা হতো — ২য় অঙ্ক
  // 0/1/2 হলে ধরে নেওয়া হতো ২-অঙ্কের মাস (১০/১১/১২)। কিন্তু ২য় অঙ্কটা আসলে বছরের প্রথম অঙ্কও
  // হতে পারে — আর ২০০০-২০২৯ এর যেকোনো বছরের (তার মধ্যে বর্তমান দশক ২০২০-২০২৯ ধরেও) প্রথম অঙ্ক
  // 0/1/2! ফলে জানুয়ারি (মাস ১) + এসব বছর টাইপ করলে সিস্টেম ভুলভাবে ২-অঙ্কের মাস ধরে নিয়ে
  // বছরের আরেকটা অঙ্কের অপেক্ষায় চিরকাল "অসম্পূর্ণ" থেকে যেত (কোনো এরর ছাড়াই) — যার ফলে
  // ব্যাচ সেভই হতো না। এখন সিদ্ধান্তটা ৩য় অঙ্ক না আসা পর্যন্ত পিছিয়ে রাখা হচ্ছে: ৩ অঙ্কে
  // (d0='0' ছাড়া) সবসময় ১-অঙ্কের মাস ধরে নেওয়া হয় (এবং তখনই সম্পূর্ণ হয়ে যায়); ৪র্থ অঙ্ক
  // এলে দরকার হলে ২-অঙ্কের মাসে (১০/১১/১২) পুনর্বিবেচনা করা হয়।
  const handleShorthandChange = (raw) => {
    const digits = raw.replace(/[^\d]/g, "").slice(0, 4);
    let monthLen = null;
    const d0 = digits[0];
    if (digits.length >= 4) {
      // পুরো ইনপুট হাতে থাকলে নিশ্চিতভাবে বলা যায় মাস ১ না ২ অঙ্কের
      monthLen = (d0 === "0" || (d0 === "1" && ["0","1","2"].includes(digits[1]))) ? 2 : 1;
    } else if (digits.length === 3) {
      // d0==='0' হলে এখনো ২-অঙ্কের মাসের ৪র্থ অঙ্কের অপেক্ষা; নাহলে ১-অঙ্কের মাস ধরে সম্পূর্ণ ধরে নাও
      monthLen = (d0 === "0") ? 2 : 1;
    }
    // digits.length <= 2 হলে monthLen অনির্ধারিতই থাকবে (null) — এখনো দ্ব্যর্থতা কাটেনি
    const formatted = (monthLen && digits.length > monthLen)
      ? `${digits.slice(0, monthLen)}/${digits.slice(monthLen)}`
      : digits;
    setShorthand(formatted);
    if (monthLen === null) { setShorthandError(""); return; } // মাস এখনো নির্ধারণ হয়নি
    const yearDigits = digits.slice(monthLen);
    if (yearDigits.length < 2) { setShorthandError(""); return; } // বছর এখনো সম্পূর্ণ না
    const mm = digits.slice(0, monthLen).padStart(2, "0");
    const monthNum = parseInt(mm, 10);
    if (monthNum < 1 || monthNum > 12) { setShorthandError("মাস ০১-১২ এর মধ্যে হবে"); return; }
    setShorthandError("");
    update(String(2000 + parseInt(yearDigits.slice(0,2), 10)), mm, true);
  };

  const isPast = local.year && local.month && new Date(`${local.year}-${local.month}-01`) < new Date(curYear, new Date().getMonth(), 1);

  return (
    <div style={style}>
      <div>
        <label style={{ color:"#94a3b8", fontSize:10, fontWeight:700, display:"block", marginBottom:4 }}>⚡ মেয়াদ লিখুন (M/YY বা MM/YY)</label>
        <input
          value={shorthand}
          onChange={e => handleShorthandChange(e.target.value)}
          placeholder="যেমনঃ 126 বা 0327"
          inputMode="numeric"
          maxLength={5}
          autoComplete="off"
          style={{ width:"100%", padding:"9px 10px", borderRadius:10, border: shorthandError ? "1.5px solid #ef4444" : "1.5px solid #334155", background:"#0f172a", color:"#e2e8f0", fontSize:14, fontWeight:800, fontFamily:"inherit", outline:"none", letterSpacing:1 }} />
        {shorthandError && <div style={{ color:"#ef4444", fontSize:11, fontWeight:700, marginTop:3 }}>⚠️ {shorthandError}</div>}
        {!shorthandError && local.year && local.month && (
          <div style={{ color: isPast ? "#f59e0b" : "#22c55e", fontSize:11, fontWeight:700, marginTop:3 }}>
            {isPast ? `⚠️ ${BN_MONTHS[parseInt(local.month,10)-1]}, ${local.year} — এই তারিখ অতীতের, ঠিক আছে তো?` : `✓ ${BN_MONTHS[parseInt(local.month,10)-1]}, ${local.year}`}
          </div>
        )}
      </div>
    </div>
  );
}
const IcClock    = () => <Ic d="M12 22c5.523 0 10-4.477 10-10S17.523 2 12 2 2 6.477 2 12s4.477 10 10 10zM12 6v6l4 2" />;
const IcPrint    = () => <Ic d="M6 9V2h12v7M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2M6 14h12v8H6z" />;
const IcSms      = () => <Ic d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z" />;
const IcLock     = () => <Ic d="M19 11H5a2 2 0 0 0-2 2v7a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7a2 2 0 0 0-2-2zM7 11V7a5 5 0 0 1 10 0v4" />;
const IcUser     = () => <Ic d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2M12 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8z" />;
const IcLogout   = () => <Ic d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4M16 17l5-5-5-5M21 12H9" />;
