// ─── AI & Automation Page ────────────────────────────────────────────────────
// ════════════════════════════════════════════════════════════════════════════════
// 🤖 PREMIUM AI MODULE — SBM v3.0
// ব্যবসায়ীদের জন্য সত্যিকারের কাজের AI — সিদ্ধান্ত নিতে সাহায্য করে
//
// নতুন ট্যাব ও ফিচার:
//  1. 📊 ড্যাশবোর্ড    — লাইভ KPI + স্বাস্থ্য স্কোর + সতর্কতা
//  2. 🔮 ফোরকাস্ট      — পণ্যভিত্তিক ডিমান্ড + রিঅর্ডার পয়েন্ট
//  3. 💰 লাভ বিশ্লেষণ  — মার্জিন হিরো/ভিলেন + প্রাইসিং পরামর্শ
//  4. 🌐 কাস্টমার AI   — RFM সেগমেন্ট + ঝুঁকি স্কোর + কোল্ড কাস্টমার
//  5. ⚡ স্মার্ট অ্যাকশন — ডেট-ভিত্তিক অটো-সাজেশন (মৌসুম, উৎসব)
//  6. 🎤 AI চ্যাটবট   — Claude API দিয়ে বাংলায় যেকোনো প্রশ্নের উত্তর
//
// বাদ দেওয়া হয়েছে:
//  ✗ "বিশ্লেষণ করুন" বাটন (অকার্যকর, ক্লিক ছাড়াই দেখানো উচিত)
//  ✗ ডিসকাউন্ট ট্যাব (লাভ বিশ্লেষণে মার্জ করা হয়েছে)
//  ✗ ভয়েস বাটন (ডেকোরেটিভ ছিল, কাজ করত না)
// ════════════════════════════════════════════════════════════════════════════════

// ══════════════════════════════════════════════════════════════════════════
// 📊 KPI স্ট্যাটস হুক — AI ড্যাশবোর্ড ও "দৈনিক সারসংক্ষেপ" পেজ উভয় জায়গায় ব্যবহৃত।
// একই হিসাব একই জায়গা থেকে আসে বলে দুই পেজের সংখ্যা সবসময় একে অপরের সাথে মিলবে।
// ══════════════════════════════════════════════════════════════════════════
// 🆕 এন্ট্রি ৩৭ — todayExpense/monthExpense-এর শেয়ার্ড হুক, useKpiStats ও
// AIPage_ দুই জায়গাতেই ব্যবহৃত (আগে দুই জায়গায় হুবহু ডুপ্লিকেট JS ছিল — ঠিক
// এই ধরনের ডুপ্লিকেশনের কারণেই ৩০ জুলাই ২০২৬-এ cash-sale মিসম্যাচ বাগ হয়েছিল,
// যখন একটা ফিক্স একজায়গায় হয়েছিল কিন্তু অন্যজায়গায় কপি হয়নি)।
// isSqliteEnabled() বন্ধ থাকলে (ডিফল্ট) সবসময় আগের JS ফিল্টার/রিডিউস — আচরণ
// অপরিবর্তিত। dateKeyGte ব্যবহার হয়েছে (dateKeyPrefix না) — DataStore.js-এর
// getDateRangeAggregate()-এর JSDoc দ্রষ্টব্য, কারণ আসল JS ফিল্টার
// ">= monthStartKey", শুধু-এক-মাস prefix-ম্যাচ না।
function useExpenseTotals(expenses, businessType, todayKey, monthStartKey) {
  const sqliteOn = isSqliteEnabled();
  const [sql, setSql] = useState(null); // null=fetch-হয়নি/লোডিং/ব্যর্থ, object=সফল
  const seqRef = useRef(0);

  useEffect(() => {
    if (!sqliteOn || !businessType || !todayKey || !monthStartKey) { setSql(null); return undefined; }
    const seq = ++seqRef.current;
    let cancelled = false;
    (async () => {
      try {
        const [todayAgg, monthAgg] = await Promise.all([
          dsGetDateRangeAggregate(businessType, "expenses", { dateKeyExact: todayKey }),
          dsGetDateRangeAggregate(businessType, "expenses", { dateKeyGte: monthStartKey }),
        ]);
        if (cancelled || seqRef.current !== seq) return;
        setSql({ today: todayAgg.total, month: monthAgg.total });
      } catch (e) {
        if (cancelled || seqRef.current !== seq) return;
        console.warn("এক্সপেন্স SQL ফেচ ব্যর্থ, JS ফলব্যাক ব্যবহার হচ্ছে:", e);
        setSql(null);
      }
    })();
    return () => { cancelled = true; };
  }, [sqliteOn, businessType, todayKey, monthStartKey, expenses]);

  const jsToday = useMemo(() => (expenses || []).filter(e => (e.dateKey || e.date) === todayKey).reduce((s, e) => s + (e.amount || 0), 0), [expenses, todayKey]);
  const jsMonth = useMemo(() => (expenses || []).filter(e => (e.dateKey || e.date || "") >= monthStartKey).reduce((s, e) => s + (e.amount || 0), 0), [expenses, monthStartKey]);

  return sql ? { today: sql.today, month: sql.month } : { today: jsToday, month: jsMonth };
}

// 🆕 এন্ট্রি ৩৮ — cashLogs/purchaseOrders/txns/returns-এর শেয়ার্ড হুক, useExpenseTotals-এর
// ঠিক একই প্যাটার্নে (useKpiStats ও AIPage_ দুই জায়গাতেই ব্যবহৃত, যাতে এন্ট্রি ৩৭-এ
// ধরা পড়া "দুই জায়গায় ডুপ্লিকেট JS লজিক" ধরনের ফিউচার বাগ এখানে আর না ঘটে)।
// isSqliteEnabled() বন্ধ থাকলে (ডিফল্ট) সবসময় আগের JS ফিল্টার/রিডিউস — আচরণ অপরিবর্তিত।

function useCashLogTotals(cashLogs, businessType, todayKey) {
  const sqliteOn = isSqliteEnabled();
  const [sql, setSql] = useState(null);
  const seqRef = useRef(0);

  useEffect(() => {
    if (!sqliteOn || !businessType || !todayKey) { setSql(null); return undefined; }
    const seq = ++seqRef.current;
    let cancelled = false;
    (async () => {
      try {
        const [opening, withdrawal, returnReversal] = await Promise.all([
          dsGetCashLogTotal(businessType, { dateKey: todayKey, type: "opening" }),
          dsGetCashLogTotal(businessType, { dateKey: todayKey, type: "withdrawal" }),
          dsGetCashLogTotal(businessType, { dateKey: todayKey, type: "return_refund_reversal" }),
        ]);
        if (cancelled || seqRef.current !== seq) return;
        setSql({ opening, withdrawal, returnReversal });
      } catch (e) {
        if (cancelled || seqRef.current !== seq) return;
        console.warn("cashLogs SQL ফেচ ব্যর্থ, JS ফলব্যাক ব্যবহার হচ্ছে:", e);
        setSql(null);
      }
    })();
    return () => { cancelled = true; };
  }, [sqliteOn, businessType, todayKey, cashLogs]);

  const cashLogsAll = cashLogs || [];
  const jsOpening = useMemo(() => cashLogsAll.filter(c => c.type === "opening" && c.dateKey === todayKey).reduce((s, c) => s + (c.amount || 0), 0), [cashLogsAll, todayKey]);
  const jsWithdrawal = useMemo(() => cashLogsAll.filter(c => c.type === "withdrawal" && c.dateKey === todayKey).reduce((s, c) => s + (c.amount || 0), 0), [cashLogsAll, todayKey]);
  const jsReturnReversal = useMemo(() => cashLogsAll.filter(c => c.type === "return_refund_reversal" && c.dateKey === todayKey).reduce((s, c) => s + (c.amount || 0), 0), [cashLogsAll, todayKey]);

  return sql ? sql : { opening: jsOpening, withdrawal: jsWithdrawal, returnReversal: jsReturnReversal };
}

function usePurchaseOrderTotals(purchaseOrders, businessType, todayKey, monthStartKey) {
  const sqliteOn = isSqliteEnabled();
  const [sql, setSql] = useState(null);
  const seqRef = useRef(0);

  useEffect(() => {
    if (!sqliteOn || !businessType || !todayKey || !monthStartKey) { setSql(null); return undefined; }
    const seq = ++seqRef.current;
    let cancelled = false;
    (async () => {
      try {
        const res = await dsGetPurchaseOrderTotals(businessType, { todayKey, monthStartKey });
        if (cancelled || seqRef.current !== seq) return;
        setSql(res);
      } catch (e) {
        if (cancelled || seqRef.current !== seq) return;
        console.warn("purchaseOrders SQL ফেচ ব্যর্থ, JS ফলব্যাক ব্যবহার হচ্ছে:", e);
        setSql(null);
      }
    })();
    return () => { cancelled = true; };
  }, [sqliteOn, businessType, todayKey, monthStartKey, purchaseOrders]);

  const purchaseOrdersAll = useMemo(() => (purchaseOrders || []).filter(p => p._type === "pe"), [purchaseOrders]);
  const jsToday = useMemo(() => purchaseOrdersAll.filter(p => p.dateKey === todayKey || (p.createdAt && p.createdAt.startsWith(todayKey))), [purchaseOrdersAll, todayKey]);
  const jsTodayCost = useMemo(() => jsToday.reduce((s, p) => s + (p.totalCost || 0), 0), [jsToday]);
  const jsTodayCount = jsToday.length;
  const jsMonthCost = useMemo(() => purchaseOrdersAll.filter(p => (p.dateKey || "") >= monthStartKey).reduce((s, p) => s + (p.totalCost || 0), 0), [purchaseOrdersAll, monthStartKey]);

  return sql ? sql : { todayCost: jsTodayCost, todayCount: jsTodayCount, monthCost: jsMonthCost };
}

function useTxnTotals(txns, invoices, businessType, todayKey) {
  const sqliteOn = isSqliteEnabled();
  const [sql, setSql] = useState(null);
  const seqRef = useRef(0);

  useEffect(() => {
    if (!sqliteOn || !businessType || !todayKey) { setSql(null); return undefined; }
    const seq = ++seqRef.current;
    let cancelled = false;
    (async () => {
      try {
        const res = await dsGetTxnTotals(businessType, todayKey);
        if (cancelled || seqRef.current !== seq) return;
        setSql(res);
      } catch (e) {
        if (cancelled || seqRef.current !== seq) return;
        console.warn("txns SQL ফেচ ব্যর্থ, JS ফলব্যাক ব্যবহার হচ্ছে:", e);
        setSql(null);
      }
    })();
    return () => { cancelled = true; };
  }, [sqliteOn, businessType, todayKey, txns, invoices]);

  const txnAll = txns || [];
  const _voidedIds = useMemo(() => new Set((invoices || []).filter(i => i.status === "voided").map(i => i.id)), [invoices]);
  const jsBaki = useMemo(() => txnAll.filter(t => t.dateKey === todayKey && t.type === "baki" && t.invoiceId && !_voidedIds.has(t.invoiceId)).reduce((s, t) => s + (t.amount || 0), 0), [txnAll, todayKey, _voidedIds]);
  const jsJoma = useMemo(() => txnAll.filter(t => t.dateKey === todayKey && t.type === "joma" && t.source !== "partial-sale" && t.source !== "void-reversal" && t.source !== "cash-sale" && t.source !== "return-adjust").reduce((s, t) => s + (t.amount || 0), 0), [txnAll, todayKey]);

  return sql ? sql : { todayBakiIncurred: jsBaki, todayJoma: jsJoma };
}

function useReturnsTotals(returns, invoices, businessType, todayKey, monthStartKey) {
  const sqliteOn = isSqliteEnabled();
  const [sql, setSql] = useState(null);
  const seqRef = useRef(0);

  useEffect(() => {
    if (!sqliteOn || !businessType || !todayKey || !monthStartKey) { setSql(null); return undefined; }
    const seq = ++seqRef.current;
    let cancelled = false;
    (async () => {
      try {
        const res = await dsGetReturnsTotals(businessType, { todayKey, monthStartKey });
        if (cancelled || seqRef.current !== seq) return;
        setSql(res);
      } catch (e) {
        if (cancelled || seqRef.current !== seq) return;
        console.warn("returns SQL ফেচ ব্যর্থ, JS ফলব্যাক ব্যবহার হচ্ছে:", e);
        setSql(null);
      }
    })();
    return () => { cancelled = true; };
  }, [sqliteOn, businessType, todayKey, monthStartKey, returns, invoices]);

  const voidedInvIds = useMemo(() => getVoidedInvoiceIds(invoices), [invoices]);
  const returnsActive = useMemo(() => filterReturnsExcludingVoided(returns || [], voidedInvIds), [returns, voidedInvIds]);
  const jsTodayReturns = useMemo(() => returnsActive.filter(r => r.dateKey === todayKey), [returnsActive, todayKey]);
  const jsMonthReturns = useMemo(() => returnsActive.filter(r => (r.dateKey || "") >= monthStartKey), [returnsActive, monthStartKey]);
  const jsTodayRefund = useMemo(() => jsTodayReturns.reduce((s, r) => s + (r.refundAmount || 0), 0), [jsTodayReturns]);
  const jsMonthRefund = useMemo(() => jsMonthReturns.reduce((s, r) => s + (r.refundAmount || 0), 0), [jsMonthReturns]);
  const jsTodayProfitImpact = useMemo(() => jsTodayReturns.reduce((s, r) => s + ((r.refundAmount || 0) - (r.costPrice || 0) * (r.qty || 0)), 0), [jsTodayReturns]);
  const jsMonthProfitImpact = useMemo(() => jsMonthReturns.reduce((s, r) => s + ((r.refundAmount || 0) - (r.costPrice || 0) * (r.qty || 0)), 0), [jsMonthReturns]);
  const jsTodayCashRefund = useMemo(() => jsTodayReturns.filter(r => r.refundMode === "cash").reduce((s, r) => s + (r.refundAmount || 0), 0), [jsTodayReturns]);

  return sql ? sql : {
    todayRefund: jsTodayRefund, monthRefund: jsMonthRefund,
    todayProfitImpact: jsTodayProfitImpact, monthProfitImpact: jsMonthProfitImpact,
    todayCashRefund: jsTodayCashRefund,
  };
}

// 🆕 এন্ট্রি ৪২-৪৩ (ধাপ ৭.২, PRODUCTS_ONDEMAND_MIGRATION_PLAN.md) — lazy/async
// id-ভিত্তিক product লুকআপ hook (`useProductsByIds`)।
//
// **কেন**: ধাপ ৭-এর অডিটে (এন্ট্রি ৪২) ধরা পড়েছে — POS পিকার/Products main
// list-এ SQL (`browse_rank`) শুধু id-অর্ডার ঠিক করে, কিন্তু প্রতিটা কার্ড
// রেন্ডারের পূর্ণ product object এখনো সবসময় সিঙ্ক্রোনাস `productsById`
// (পুরো `products` অ্যারে থেকে রিবিল্ড হওয়া global Map) থেকে আসে — এটাই
// `products`-কে সবসময় পূর্ণ মেমরিতে রাখতে বাধ্য করছে। এই হুক সেই সিঙ্ক
// নির্ভরতা ভাঙার প্রথম বিল্ডিং-ব্লক: একটা নির্দিষ্ট id-তালিকার জন্য
// (যেমন — বর্তমান পেজের ৫০টা id) `getByIds()` দিয়ে ব্যাচ-ফেচ করে, ইতিমধ্যে
// লোড হওয়া id রিফেচ না করে (ইনক্রিমেন্টাল ক্যাশ)।
//
// **ডিজাইন — মাইগ্রেশনের established fallback প্যাটার্ন অনুসরণ করে**:
//   - `isSqliteEnabled()` false হলে বা `products` (in-memory) থেকেই id
//     পাওয়া গেলে — SQL ফেচ করারই দরকার নেই, সরাসরি `productsById.get(id)`
//     রিটার্ন হয় (zero SQL কল, বিদ্যমান আচরণ ১০০% অপরিবর্তিত)।
//   - শুধু তখনই SQL ফেচ ট্রিগার হয় যখন `products` (in-memory) খালি/লেজি
//     এবং সেই id এখনো ক্যাশে নেই — অর্থাৎ ভবিষ্যতে (ধাপ ৭.৩) বুট lazy হলেই
//     এই পাথ সক্রিয় হবে, আপাতত `products` সবসময় পূর্ণ থাকায় (৭.৩ এখনো হয়নি)
//     এই effect বাস্তবে কখনো ফায়ারই করবে না।
//   - রিটার্ন `{ get(id), loadingIds: Set, missingIds: Set }` — কলার
//     সিঙ্ক্রোনাসভাবে `get()` কল করে; না-পাওয়া গেলে `null` পায় (loading
//     অবস্থায় স্কেলিটন/প্লেসহোল্ডার দেখানোর সুযোগ দেয়, ক্র্যাশ না)।
//
// ⚠️ **এই হুক এখনো App.jsx-এর কোনো রেন্ডার-পাথে wire করা হয়নি** — শুধু
// সংজ্ঞায়িত+টেস্টেড (নিচে দেখুন)। wire করা (POS card/Products list card
// রেন্ডারে ব্যবহার) হলো ধাপ ৭.৩-এর অংশ, কিন্তু ৭.৩ (বুট সিকোয়েন্স পরিবর্তন)
// এখনো ইচ্ছাকৃতভাবে অস্পৃষ্ট (এন্ট্রি ৪২ দ্রষ্টব্য — কারণ ব্যাখ্যা করা আছে)।
function useProductsByIds(ids, businessType, productsByIdMap) {
  const [cache, setCache] = useState(() => new Map());
  const cacheRef = useRef(cache);
  cacheRef.current = cache;
  const inFlightRef = useRef(new Set());
  const sqliteOn = isSqliteEnabled();

  const idsKey = (ids || []).join(",");

  useEffect(() => {
    if (!sqliteOn || !businessType) return undefined;
    const wanted = (ids || []).map(String);
    // যেগুলো ইতিমধ্যে in-memory productsByIdMap-এ আছে (products এখনো পূর্ণ
    // থাকা অবস্থায়, বর্তমান বাস্তবতা), সেগুলোর জন্য SQL ফেচ করার দরকার নেই।
    const missing = wanted.filter(
      (id) => !productsByIdMap?.has(id) && !cacheRef.current.has(id) && !inFlightRef.current.has(id)
    );
    if (missing.length === 0) return undefined;

    let cancelled = false;
    missing.forEach((id) => inFlightRef.current.add(id));
    (async () => {
      try {
        const rows = await dsGetByIds(businessType, "products", missing);
        if (cancelled) return;
        setCache((prev) => {
          const next = new Map(prev);
          for (const row of rows) next.set(String(row.id), row);
          return next;
        });
      } catch (e) {
        console.warn("useProductsByIds() SQL ব্যাচ-ফেচ ব্যর্থ:", e);
      } finally {
        missing.forEach((id) => inFlightRef.current.delete(id));
      }
    })();
    return () => { cancelled = true; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [idsKey, sqliteOn, businessType, productsByIdMap]);

  const get = useCallback(
    (id) => productsByIdMap?.get(String(id)) || cacheRef.current.get(String(id)) || null,
    [productsByIdMap, cache] // eslint-disable-line react-hooks/exhaustive-deps
  );

  return { get, cache };
}

// 🆕 এন্ট্রি ৩৯ — useKpiStats-এর products-নির্ভর অবশিষ্ট অংশ: stockValue/lowStockCount
// (getInventoryCounts()-এর stock_value/critical কলাম — এন্ট্রি ৩৬-এ InventorySection-এর
// জন্য বানানো একই ফাংশন, useKpiStats-এও পুনর্ব্যবহার করা হচ্ছে, নতুন করে লেখার দরকার
// হয়নি) + monthExpiredValue/monthExpiredCount (stockMovements টেবিল, উপরে দেখুন)।

function useProductStockTotals(products, businessType) {
  const sqliteOn = isSqliteEnabled();
  const [sql, setSql] = useState(null);
  const seqRef = useRef(0);

  useEffect(() => {
    if (!sqliteOn || !businessType) { setSql(null); return undefined; }
    const seq = ++seqRef.current;
    let cancelled = false;
    (async () => {
      try {
        const res = await dsGetInventoryCounts(businessType);
        if (cancelled || seqRef.current !== seq) return;
        setSql({ stockValue: res.stockValue, lowStockCount: res.critical });
      } catch (e) {
        if (cancelled || seqRef.current !== seq) return;
        console.warn("products stock SQL ফেচ ব্যর্থ, JS ফলব্যাক ব্যবহার হচ্ছে:", e);
        setSql(null);
      }
    })();
    return () => { cancelled = true; };
  }, [sqliteOn, businessType, products]);

  const prodAll = products || [];
  const jsStockValue = useMemo(() => prodAll.reduce((s, p) => s + (p.costPrice || p.price || 0) * (p.stock || 0), 0), [prodAll]);
  const jsLowStockCount = useMemo(() => prodAll.filter(p => (p.stock || 0) > 0 && (p.stock || 0) <= (p.minStockAlert || 5)).length, [prodAll]);

  return sql ? sql : { stockValue: jsStockValue, lowStockCount: jsLowStockCount };
}

// 🆕 এন্ট্রি ৪৫ — AIPage_-এর lowStockItems (এন্ট্রি ৪৪-এ চিহ্নিত ৪টা সাব-প্যাটার্নের
// প্রথমটা, "সবচেয়ে সহজ অংশ")। useProductStockTotals()-এর মতো নয় — ওটা শুধু
// lowStockCount (সংখ্যা) দেয়, কিন্তু AIPage_-এর ৮+ জায়গায় আসল আইটেম-লিস্ট লাগে
// (নাম/স্টক দেখানোর জন্য, .slice().map(p=>p.name) ইত্যাদি) — তাই dsGetInventoryList()
// (এন্ট্রি ৩৬-এ InventorySection-এর জন্য বানানো, একই "critical" kind) পুনর্ব্যবহার
// করে পূর্ণ product অবজেক্ট-অ্যারে ফেরত দেওয়া হচ্ছে, শুধু কাউন্ট না। JS ফলব্যাক
// prodAll.filter()-এর সাথে ঠিক একই শর্ত (stock>0 AND stock<=minStockAlert||5)
// বজায় রাখা হয়েছে যাতে SQL অন/অফ দুই অবস্থাতেই ফলাফল অভিন্ন থাকে।
function useLowStockItems(products, businessType) {
  const sqliteOn = isSqliteEnabled();
  const [sql, setSql] = useState(null);
  const seqRef = useRef(0);

  useEffect(() => {
    if (!sqliteOn || !businessType) { setSql(null); return undefined; }
    const seq = ++seqRef.current;
    let cancelled = false;
    (async () => {
      try {
        const rows = await dsGetInventoryList(businessType, "critical");
        if (cancelled || seqRef.current !== seq) return;
        setSql(rows);
      } catch (e) {
        if (cancelled || seqRef.current !== seq) return;
        console.warn("lowStockItems SQL ফেচ ব্যর্থ, JS ফলব্যাক ব্যবহার হচ্ছে:", e);
        setSql(null);
      }
    })();
    return () => { cancelled = true; };
  }, [sqliteOn, businessType, products]);

  const prodAll = products || [];
  const jsLowStockItems = useMemo(
    () => prodAll.filter(p => (p.stock || 0) > 0 && (p.stock || 0) <= (p.minStockAlert || 5)),
    [prodAll]
  );

  return sql ? sql : jsLowStockItems;
}

// 🆕 এন্ট্রি ৪৬ — AIPage_-এর outOfStock/prodAll.length (এন্ট্রি ৪৪-৪৫-এ চিহ্নিত
// ৪টা সাব-প্যাটার্নের ২য়টা)। শুধু সংখ্যা লাগে (আইটেম-লিস্ট না), তাই
// getInventoryCounts()-ই যথেষ্ট (এন্ট্রি ৩৬/৩৯-এ বানানো, নতুন total_count কলাম
// এন্ট্রি ৪৬-এ যোগ হলো) — নতুন কোনো ডেডিকেটেড getOutOfStockCount() ফাংশন
// লাগেনি। useProductStockTotals()-এর সাথে duplicate SQL কল এড়াতে চাইলে ভবিষ্যতে
// দুটো হুক এক getInventoryCounts() রেসপন্স শেয়ার করতে পারে, কিন্তু আপাতত
// প্যাটার্ন সামঞ্জস্যের জন্য আলাদা হুক (প্রতিটা ছোট, independent, ব্যবহার-সাইট
// অনুযায়ী trace করা সহজ — বিদ্যমান useProductStockTotals/useLowStockItems-এর
// মতোই স্বতন্ত্র)।
function useOutOfStockCount(products, businessType) {
  const sqliteOn = isSqliteEnabled();
  const [sql, setSql] = useState(null);
  const seqRef = useRef(0);

  useEffect(() => {
    if (!sqliteOn || !businessType) { setSql(null); return undefined; }
    const seq = ++seqRef.current;
    let cancelled = false;
    (async () => {
      try {
        const res = await dsGetInventoryCounts(businessType);
        if (cancelled || seqRef.current !== seq) return;
        setSql({ outOfStock: res.stockOut, totalProducts: res.totalCount });
      } catch (e) {
        if (cancelled || seqRef.current !== seq) return;
        console.warn("outOfStock SQL ফেচ ব্যর্থ, JS ফলব্যাক ব্যবহার হচ্ছে:", e);
        setSql(null);
      }
    })();
    return () => { cancelled = true; };
  }, [sqliteOn, businessType, products]);

  const prodAll = products || [];
  const jsOutOfStock = useMemo(() => prodAll.filter(p => (p.stock || 0) === 0).length, [prodAll]);

  return sql ? sql : { outOfStock: jsOutOfStock, totalProducts: prodAll.length };
}

// 🆕 এন্ট্রি ৪৬ — ruleBasedAnswer()-এর "কম স্টক" চ্যাট-উত্তরে স্টকশূন্য পণ্যের
// পূর্ণ তালিকা লাগে (নাম দেখানোর জন্য .slice(0,5).map(p=>p.name)) — শুধু কাউন্ট
// (useOutOfStockCount) দিয়ে হয় না, lowStockItems-এর মতোই একই সমস্যা (এন্ট্রি ৪৫
// দ্রষ্টব্য)। বিদ্যমান dsGetInventoryList(businessType, "out") (এন্ট্রি ৩৬-এ
// InventorySection-এর জন্য বানানো "kind" প্যারামিটারে ইতিমধ্যেই সমর্থিত, নতুন
// SQL লাগেনি) পুনর্ব্যবহার করা হলো।
function useOutOfStockItems(products, businessType) {
  const sqliteOn = isSqliteEnabled();
  const [sql, setSql] = useState(null);
  const seqRef = useRef(0);

  useEffect(() => {
    if (!sqliteOn || !businessType) { setSql(null); return undefined; }
    const seq = ++seqRef.current;
    let cancelled = false;
    (async () => {
      try {
        const rows = await dsGetInventoryList(businessType, "out");
        if (cancelled || seqRef.current !== seq) return;
        setSql(rows);
      } catch (e) {
        if (cancelled || seqRef.current !== seq) return;
        console.warn("outOfStockItems SQL ফেচ ব্যর্থ, JS ফলব্যাক ব্যবহার হচ্ছে:", e);
        setSql(null);
      }
    })();
    return () => { cancelled = true; };
  }, [sqliteOn, businessType, products]);

  const prodAll = products || [];
  const jsOutOfStockItems = useMemo(() => prodAll.filter(p => (p.stock || 0) === 0), [prodAll]);

  return sql ? sql : jsOutOfStockItems;
}

// 🆕 এন্ট্রি ৪৭ — AIPage_-এর expired/near-expiry স্ক্যান (৪টা সাব-প্যাটার্নের ৩য়টা)।
// InventorySection-এ (এন্ট্রি ৩৬) ইতিমধ্যেই এই একই "candidate-narrowing" প্যাটার্ন
// আছে (dsGetExpiryCandidates() দিয়ে nearest_expiry_date<=3মাস ইনডেক্স-সিক করে
// candidate সেট ছোট করা, তারপর সেই ছোট সেটের উপর read-time new Date() তুলনা দিয়ে
// আসল expired/near বিভাজন — staleness ঝুঁকি নেই কারণ তুলনাটা সবসময় লাইভ) — এখানে
// একই ফাংশন পুনর্ব্যবহার করে হুক আকারে জেনারালাইজ করা হলো, নতুন SQL লাগেনি।
// JS ফলব্যাক পুরো prodAll (candidate-narrowing না থাকলে পুরো array-ই স্ক্যান হবে,
// AIPage_-এর আগের আচরণের সাথে হুবহু মিল)।
function useExpiryCandidates(products, businessType) {
  const sqliteOn = isSqliteEnabled();
  const [sql, setSql] = useState(null);
  const seqRef = useRef(0);

  useEffect(() => {
    if (!sqliteOn || !businessType) { setSql(null); return undefined; }
    const seq = ++seqRef.current;
    let cancelled = false;
    (async () => {
      try {
        const rows = await dsGetExpiryCandidates(businessType);
        if (cancelled || seqRef.current !== seq) return;
        setSql(rows);
      } catch (e) {
        if (cancelled || seqRef.current !== seq) return;
        console.warn("expiryCandidates SQL ফেচ ব্যর্থ, JS ফলব্যাক ব্যবহার হচ্ছে:", e);
        setSql(null);
      }
    })();
    return () => { cancelled = true; };
  }, [sqliteOn, businessType, products]);

  return sql ? sql : (products || []);
}

function useExpiredRemovalTotals(stockMovements, businessType, monthKey) {
  const sqliteOn = isSqliteEnabled();
  const [sql, setSql] = useState(null);
  const seqRef = useRef(0);

  useEffect(() => {
    if (!sqliteOn || !businessType || !monthKey) { setSql(null); return undefined; }
    const seq = ++seqRef.current;
    let cancelled = false;
    (async () => {
      try {
        const res = await dsGetExpiredRemovalTotals(businessType, monthKey);
        if (cancelled || seqRef.current !== seq) return;
        setSql(res);
      } catch (e) {
        if (cancelled || seqRef.current !== seq) return;
        console.warn("stockMovements SQL ফেচ ব্যর্থ, JS ফলব্যাক ব্যবহার হচ্ছে:", e);
        setSql(null);
      }
    })();
    return () => { cancelled = true; };
  }, [sqliteOn, businessType, monthKey, stockMovements]);

  const jsRemovals = useMemo(() => (stockMovements || []).filter(mv =>
    mv.source === "expired_removal" && (mv.monthKey || (mv.dateKey ? mv.dateKey.slice(0, 7) : "")) === monthKey
  ), [stockMovements, monthKey]);
  const jsValue = useMemo(() => jsRemovals.reduce((s, r) => s + (r.value || 0), 0), [jsRemovals]);
  const jsCount = jsRemovals.length;

  return sql ? { value: sql.value, count: sql.count } : { value: jsValue, count: jsCount };
}

// 🆕 এন্ট্রি ৪১ (ধাপ ৬, computeSupplierDueMap) — Dashboard ও SupplierPaymentModule
// দুই জায়গাতেই একই সোর্স (entry ৩৭/৩৮-এর "duplicate-JS-logic বাগ এড়াতে দুই
// জায়গায় একই শেয়ার্ড হুক" নীতি অনুসরণ করে)। SQL চালু থাকলে getSupplierDueRows()
// (schema.sql-এর "supplier due-map" কমেন্ট-ব্লক দ্রষ্টব্য) সরাসরি ডিডুপ্লিকেটেড
// রো-অ্যারে দেয়; JS ফলব্যাকে computeSupplierDueMap()+uniqueSupplierRows() (আসল,
// অপরিবর্তিত logic.js ফাংশন)। দুই ক্ষেত্রেই রিটার্ন হয় { map, rows } —
// map = raw/canonical নাম দিয়ে লুকআপের জন্য (supplierDueMap[name] প্যাটার্ন),
// rows = sorted list রেন্ডারের জন্য (uniqueSupplierRows-এর সমতুল্য, আগে থেকেই
// ডিডুপ্লিকেটেড)।
function useSupplierDueRows(products, purchaseOrders, supplierPayments, businessType) {
  const sqliteOn = isSqliteEnabled();
  const [sql, setSql] = useState(null);
  const seqRef = useRef(0);

  useEffect(() => {
    if (!sqliteOn || !businessType) { setSql(null); return undefined; }
    const seq = ++seqRef.current;
    let cancelled = false;
    (async () => {
      try {
        const rows = await dsGetSupplierDueRows(businessType);
        if (cancelled || seqRef.current !== seq) return;
        setSql(rows);
      } catch (e) {
        if (cancelled || seqRef.current !== seq) return;
        console.warn("supplier due-map SQL ফেচ ব্যর্থ, JS ফলব্যাক ব্যবহার হচ্ছে:", e);
        setSql(null);
      }
    })();
    return () => { cancelled = true; };
  }, [sqliteOn, businessType, products, purchaseOrders, supplierPayments]);

  const jsMap = useMemo(() => computeSupplierDueMap(products, purchaseOrders, supplierPayments), [products, purchaseOrders, supplierPayments]);
  const jsRows = useMemo(() => uniqueSupplierRows(jsMap), [jsMap]);

  return useMemo(() => {
    if (sql) {
      // raw-name backward-compat: প্রতিটা raw ভ্যারিয়েন্টও merged রো পয়েন্ট করে
      // (computeSupplierDueMap()-এর finalMap[raw]=... আচরণের সমতুল্য — এই লুকআপ
      // SupplierPaymentModule-এর paymentSummary-তে সরাসরি ব্যবহৃত হয়, যেখানে
      // key হিসেবে raw supplierName আসে, canonical নাম না)।
      const map = {};
      const rows = sql.map(({ rawVariants, ...row }) => {
        map[row.name] = row;
        (rawVariants || []).forEach(raw => { if (raw) map[raw] = row; });
        return row;
      });
      return { map, rows };
    }
    return { map: jsMap, rows: jsRows };
  }, [sql, jsMap, jsRows]);
}

// 🆕 এন্ট্রি ৪৮ (AIPage_-এর ৪র্থ ও শেষ সাব-প্যাটার্ন — forecastData/productSales
// জয়েন, বেস্টসেলার র‍্যাংকিং)। schema.sql-এর invoiceItems কমেন্ট + DataStore.js-এর
// getProductSalesRows() দ্রষ্টব্য — write-time প্রিকম্পিউটেড লাইন-আইটেম রো থেকে
// GROUP BY/SUM SQL অ্যাগ্রিগেট। JS ফলব্যাক = logic.js-এর computeProductSales()
// (আগে App.jsx-এই ইনলাইন ছিল, এখানে তোলা হলো একই ফাংশন টেস্টেও রিইউজ করতে —
// entry ৪১-এর "duplicate-logic এড়ানো" নীতি)। cutoffs = { d30, d60, d90 } —
// কলার (নিচে) থেকে আসে, উপরে সংজ্ঞায়িত ms()-ভিত্তিক ভ্যারিয়েবল।
function useProductSalesRows(invAll, prodMap, businessType, cutoffs) {
  const { d30, d60, d90 } = cutoffs;
  const sqliteOn = isSqliteEnabled();
  const [sql, setSql] = useState(null);
  const seqRef = useRef(0);

  useEffect(() => {
    if (!sqliteOn || !businessType) { setSql(null); return undefined; }
    const seq = ++seqRef.current;
    let cancelled = false;
    (async () => {
      try {
        const rows = await dsGetProductSalesRows(businessType, { d30, d60, d90 });
        if (cancelled || seqRef.current !== seq) return;
        setSql(rows);
      } catch (e) {
        if (cancelled || seqRef.current !== seq) return;
        console.warn("productSales SQL ফেচ ব্যর্থ, JS ফলব্যাক ব্যবহার হচ্ছে:", e);
        setSql(null);
      }
    })();
    return () => { cancelled = true; };
  }, [sqliteOn, businessType, invAll, d30, d60, d90]);

  const jsProductSales = React.useMemo(
    () => computeProductSales(invAll, prodMap, { d30, d60, d90 }),
    [invAll, prodMap, d30, d60, d90]
  );

  return sql ? sql : jsProductSales;
}

// 🆕 এন্ট্রি ৪৪ (PRODUCTS_ONDEMAND_MIGRATION_PLAN.md ৭.৩-এর ব্লকার, ক্যাটাগরি ③ FULL-SCAN)
// ৪টা আইটেমের মধ্যে ৩টা এখানে — একই sql-state/seqRef/fallback প্যাটার্ন
// (useProductStockTotals/useSupplierDueRows-এর মতো)। dup-name check নিচে
// আলাদা (per-keystroke debounce লাগে, list না, একক-রেকর্ড lookup)।

/** SmartInvoiceBuilder-এর ক্যাটাগরি-ফিল্টার চিপ লিস্ট। */
function useKnownCategories(products, businessType) {
  const sqliteOn = isSqliteEnabled();
  const [sql, setSql] = useState(null);
  const seqRef = useRef(0);

  useEffect(() => {
    if (!sqliteOn || !businessType) { setSql(null); return undefined; }
    const seq = ++seqRef.current;
    let cancelled = false;
    (async () => {
      try {
        const cats = await dsGetDistinctCategories(businessType);
        if (cancelled || seqRef.current !== seq) return;
        setSql(cats);
      } catch (e) {
        if (cancelled || seqRef.current !== seq) return;
        console.warn("ক্যাটাগরি-লিস্ট SQL ফেচ ব্যর্থ, JS ফলব্যাক ব্যবহার হচ্ছে:", e);
        setSql(null);
      }
    })();
    return () => { cancelled = true; };
  }, [sqliteOn, businessType, products]);

  const jsCats = useMemo(() => {
    const cats = ["সব", "সার্ভিস", ...new Set(products.filter(p => p.productType !== "service").map(p => p.category || "অন্যান্য"))];
    return cats;
  }, [products]);

  return useMemo(() => {
    if (sql) return ["সব", "সার্ভিস", ...sql.map(c => c || "অন্যান্য")];
    return jsCats;
  }, [sql, jsCats]);
}

/** getKnownSuppliers()-এর SQL-ভিত্তিক প্রতিস্থাপন — SupplierPicker অটো-সাজেশন। */
