  const setStockMovements   = useCallback((v) => _set("stockMovements",   v), [_set]);
  const setCashLogs         = useCallback((v) => _set("cashLogs",         v), [_set]);

  // ── 🔐 Recovery (Phone + PIN) — central backup/restore state ─────────────
  const [recoveryPhone, setRecoveryPhoneState] = useState("");
  const [recoveryPinHash, setRecoveryPinHashState] = useState(null);


  // ── Permission helper ────────────────────────────────────────────────────
  // স্টাফের tempPermissions চেক: { key, expiresAt } — সময় পেরিয়ে গেলে false
  const hasPerm = useCallback((user, key) => {
    if (!user || user.role === "admin" || user.role === "owner") return true;
    const tempOk = (user.tempPermissions || []).some(
      p => p.key === key && new Date(p.expiresAt) > new Date()
    );
    if (tempOk) return true;
    // ⏰ অটো-শিডিউল: এডমিনের সেট করা দৈনিক সময়সীমার মধ্যে থাকলে অটোমেটিক অনুমতি
    const sched = (user.autoSchedules || []).find(s => s.key === key);
    return isAutoScheduleActive(sched);
  }, []);

  const tab = useAppStore((s) => s.tab);
  // ── tab setter — route guard সহ ───────────────────────────────────────────
  // 🆕 পারফরম্যান্স ফিক্স (২৫ জুলাই ২০২৬): setTab-কে useCallback দিয়ে স্থিতিশীল
  // রেফারেন্স করা হয়েছে, কিন্তু ⚠️ সংজ্ঞাটা এখানে না রেখে showToast-এর
  // declaration-এর ঠিক পরে বসানো হয়েছে (নিচে দেখুন) — কারণ showToast এই
  // ফাইলে অনেক পরে declare হয়, আর dependency array-তে সেটা এখানে রাখলে
  // "Cannot access 'showToast' before initialization" TDZ ক্র্যাশ হতো (এই
  // ফাইলে আগেও একবার এই ক্লাসের বাগ ফিক্স করা হয়েছিল)।

  const currentPreset = THEME_PRESETS.find(p => p.id === activeTheme) || THEME_PRESETS[0];
  // 🆕 পারফরম্যান্স ফিক্স (২৫ জুলাই ২০২৬ — শপকিপার ল্যাগ তদন্ত): T আগে প্রতি রেন্ডারে
  // নতুন অবজেক্ট রেফারেন্স তৈরি করত (Firestore listener আপডেটে ~২০+ বার/মিনিট),
  // যা সব চাইল্ড কম্পোনেন্টকে ভুল "props বদলেছে" সিগনাল পাঠাত। এখন useMemo দিয়ে
  // activeTheme/enabledBusinessTypes/businessType না বদলালে একই রেফারেন্স থাকে।
  const T = useMemo(() => (currentPreset.dark ? {
    ...DARK,
    accent: currentPreset.accent, accentDark: currentPreset.accentDark || currentPreset.accent, accentGlow: currentPreset.accent + "33", accentPill: currentPreset.accent + "22",
    nav: currentPreset.nav, navActive: currentPreset.navActive, navPill: currentPreset.navActive + "18",
    headingColor: getContrastText(currentPreset.statusBar || currentPreset.bg), statusBar: currentPreset.statusBar || currentPreset.bg,
    border: currentPreset.border || (currentPreset.dark ? "#1e3a27" : "#d4eddb"),
    header: currentPreset.header,
    stepActive: currentPreset.accent, stepDone: currentPreset.accent,
    bg: currentPreset.bg, card: currentPreset.card,
    text: currentPreset.text, sub: currentPreset.sub,
  } : {
    ...LIGHT,
    accent: currentPreset.accent, accentDark: currentPreset.accentDark || currentPreset.accent, accentGlow: currentPreset.accent + "22", accentPill: currentPreset.accent + "18",
    nav: currentPreset.nav, navActive: currentPreset.navActive, navPill: currentPreset.navActive + "18",
    headingColor: getContrastText(currentPreset.statusBar || currentPreset.bg), statusBar: currentPreset.statusBar || currentPreset.bg,
    border: currentPreset.border || (currentPreset.dark ? "#d4eddb" : "#1e3a27"),
    header: currentPreset.header,
    stepActive: currentPreset.accent, stepDone: currentPreset.accent,
    bg: currentPreset.bg, card: currentPreset.card,
    text: currentPreset.text, sub: currentPreset.sub,
  }), [activeTheme, currentPreset]);
  const isDark = currentPreset.dark;

  // 🆕 রিডিজাইন (২০ জুলাই ২০২৬ — "থিম রাখার লাভ কী?" ফিডব্যাক): আগে multi-business
  // শপে সক্রিয় বিজনেসের registry-রং পুরো অ্যাপের accent/navActive ওভাররাইট করে
  // দিত — ফলে ইউজার যেকোনো থিম বেছে নিলেও (green/orange/purple বিজনেসে) সেই থিমের
  // accent আসলে কখনো দেখা যেত না, পুরো থিম-সিস্টেমটাই কার্যত অকেজো হয়ে পড়ত।
  // এখন থিম সবসময় সম্পূর্ণরূপে (accent সহ) প্রযোজ্য থাকে — businessAccentColor
  // শুধু "সক্রিয় বিজনেস" badge/সুইচার বাটন ও শপ-নামের ব্র্যাকেটে (নিচে) ব্যবহার হয়,
  // যেটা ইচ্ছাকৃতভাবে থিম-নিরপেক্ষ সেফটি-সিগন্যাল হিসেবে থেকে যায়।
  const isMultiBusinessActive = Array.isArray(enabledBusinessTypes) && enabledBusinessTypes.length > 1;
  const businessAccentColor = isMultiBusinessActive ? (BUSINESS_TYPE_REGISTRY[businessType]?.color || null) : null;

  // ── CSS Variables — 1,712 inline style → var(--t-*) ──────────────────────
  // T object-এর সব token একবারে :root-এ inject করা হয়।
  // component re-render না করেই theme switch হয়।
  useEffect(() => {
    const root = document.documentElement;
    root.style.setProperty("--t-bg",           T.bg);
    root.style.setProperty("--t-card",         T.card);
    root.style.setProperty("--t-card-alt",     T.cardAlt || T.card);
    root.style.setProperty("--t-border",       T.border);
    root.style.setProperty("--t-border-light", T.borderLight || T.border);
    root.style.setProperty("--t-text",         T.text);
    root.style.setProperty("--t-text-soft",    T.textSoft || T.text);
    root.style.setProperty("--t-sub",          T.sub);
    root.style.setProperty("--t-accent",       T.accent);
    root.style.setProperty("--t-accent-dark",  T.accentDark);
    root.style.setProperty("--t-accent-glow",  T.accentGlow);
    root.style.setProperty("--t-accent-pill",  T.accentPill);
    root.style.setProperty("--t-input",        T.input || T.card);
    root.style.setProperty("--t-input-border", T.inputBorder || T.border);
    root.style.setProperty("--t-input-focus",  T.inputFocus  || T.accentGlow);
    root.style.setProperty("--t-nav",          T.nav);
    root.style.setProperty("--t-nav-border",   T.navBorder   || T.border);
    root.style.setProperty("--t-nav-active",   T.navActive);
    root.style.setProperty("--t-nav-pill",     T.navPill);
    root.style.setProperty("--t-header",       T.header);
    root.style.setProperty("--t-heading",      T.headingColor || "#fff");
    root.style.setProperty("--t-danger",       T.danger);
    root.style.setProperty("--t-danger-bg",    T.dangerBg);
    root.style.setProperty("--t-warning",      T.warning);
    root.style.setProperty("--t-warning-bg",   T.warningBg);
    root.style.setProperty("--t-info",         T.info);
    root.style.setProperty("--t-info-bg",      T.infoBg);
    root.style.setProperty("--t-success",      T.success || T.accent);
    root.style.setProperty("--t-success-bg",   T.successBg || T.accentGlow);
    root.style.setProperty("--t-shadow",       T.shadow);
    root.style.setProperty("--t-shadow-sm",    T.shadowSm);
    root.style.setProperty("--t-shadow-glow",  T.shadowGlow);
    root.style.setProperty("--t-stripe",       T.stripe || T.bg);
    root.style.setProperty("--t-toast-bg",     T.toastBg || T.card);
    root.style.setProperty("--t-fs-base",      fontSize + "px");
  }, [activeTheme, darkMode, fontSize, businessType, enabledBusinessTypes]); // eslint-disable-line react-hooks/exhaustive-deps

  // ── Web Worker Setup — ভারী calculation main thread-এ নয় ─────────────────
  const workerRef = useRef(null);
  const [dashStats, setDashStats] = useState(null);
  const [reorderAlerts, setReorderAlerts] = useState([]);

  useEffect(() => {
    try {
      workerRef.current = new Worker(
        new URL("./worker.js", import.meta.url),
        { type: "module" }
      );
      workerRef.current.onmessage = ({ data }) => {
        if (data.type === "DASHBOARD_RESULT") setDashStats(data.payload);
        if (data.type === "REORDER_ALERTS")   setReorderAlerts(data.payload);
        if (data.type === "CASH_FLOW_RESULT")  setCashFlow(data.payload);
      };
      workerRef.current.onerror = (e) => console.warn("Worker error:", e);
    } catch(e) {
      console.warn("Worker not supported:", e);
    }
    return () => workerRef.current?.terminate();
  }, []);

  // products/invoices/customers বদলালে Worker-এ পাঠান
  useEffect(() => {
    if (!workerRef.current || !invoices.length || !products.length) return;
    const today = _dateKeyOf(new Date());
    workerRef.current.postMessage({
      type: "CALC_DASHBOARD",
      payload: { invoices, products, customers, txns, today }
    });
  }, [invoices, products, customers, txns]);

  // Stock reorder prediction
  useEffect(() => {
    if (!workerRef.current || !products.length || !invoices.length) return;
    workerRef.current.postMessage({
      type: "PREDICT_REORDER",
      payload: { products, invoices }
    });
  }, [products, invoices]);

  // Cash Flow Forecast — Worker
  useEffect(() => {
    if (!workerRef.current || !invoices.length) return;
    workerRef.current.postMessage({
      type: "CASH_FLOW_FORECAST",
      payload: { invoices, customers, txns, expenses, purchaseOrders }
    });
  }, [invoices, customers, txns, expenses, purchaseOrders]);

  const [cashFlow,   setCashFlow]   = React.useState(null); // Cash Flow Forecast

  // Global prodMap — একবার তৈরি, সব জায়গায় ব্যবহার
  const globalProdMap = useMemo(
    () => new Map(products.map(p => [p.id, p])),
    [products]
  );

  useEffect(() => {
    (async () => {
      await DeviceID.init(); // 🔥 ফিক্স: localStorage হারিয়ে গেলেও same device id বজায় রাখতে

      // ── Phase 1.1 + পারফরম্যান্স ফিক্স: batched IndexedDB read + দুই-wave লোড ──
      // আগে ৩৪টা key-ই Promise.all([load(k1), load(k2), ...]) দিয়ে একসাথে
      // "শুরু" হতো কিন্তু IndexedDB ব্যাকএন্ডে প্রতিটা load() নিজের আলাদা
      // transaction খুলত (৩৪টা transaction)। এখন loadMany() দিয়ে ক্রিটিক্যাল
      // key-গুলো একটাই transaction-এ পড়া হয়। এছাড়া প্রথম পেইন্টের জন্য যা
      // লাগবে না (auditLogs, cashLogs, stockMovements, ইত্যাদি বড়/সেটিংস-
      // নির্ভর কালেকশন) সেগুলো আলাদা "wave 2"-তে সরানো হলো — ইনভয়েস
      // ব্যাকফিলের মতোই একই প্যাটার্নে (setTimeout 0, প্রথম রেন্ডারের পর)।
      // 🔴 ফিক্স (রুট কজ — মাল্টি-বিজনেস ক্রস-কনটামিনেশন, ১৯ জুলাই ২০২৬): আগে
      // SK.businessType/SK.businessTypeLocked/SK.enabledBusinessTypes DEFERRED_KEYS
      // (wave 2, setTimeout 0-এ প্রথম পেইন্টের পর লোড) এ ছিল, অথচ SK.products/
      // SK.customers/SK.firebaseConfig/SK.firebaseEnabled CRITICAL_KEYS-এ (wave 1,
      // সিঙ্ক্রোনাসভাবে প্রথম রেন্ডারেই)। ফলে boot হওয়ার সময় একটা রেস কন্ডিশন
      // তৈরি হতো: fssReady (FSS.init() wave 1-এর firebaseConfig/firebaseEnabled
      // দিয়ে) সত্যি হয়ে যেত, আর useFSSCollection("products"/"customers",...)
      // Firestore-এ সাবস্ক্রাইব করা শুরু করত — কিন্তু তখনো FSS._businessPrefix
      // ছিল default/null (কারণ businessType/enabledBusinessTypes এখনো লোড হয়নি,
      // isMultiBusiness তখনো false ধরা হতো), মানে ভুল (unprefixed বা আগের সেশনের)
      // Firestore কালেকশনে সাবস্ক্রাইব হয়ে যেত। একইসাথে products/customers এর
      // লোকাল স্টেট বসত একটামাত্র শেয়ার্ড, বিজনেস-নন-স্কোপড localStorage key
      // (sbm-products/sbm-customers) থেকে — যেটাতে ডিভাইসে সবশেষ যে বিজনেস
      // অ্যাক্টিভ ছিল তারই ডেটা থাকতে পারে। এই দুটোর কম্বিনেশনে
      // useFSSCollection-এর "local-only push" রিকভারি লজিক (আসল অফলাইন-এন্ট্রি
      // রিকভারির জন্য বসানো হয়েছিল) ভুল করে অন্য বিজনেসের স্টেল লোকাল ডেটাকে
      // "এখনো push হয়নি এমন নতুন রেকর্ড" ধরে ভুল কালেকশনে push করে দিত —
      // এটাই "অন্য বিজনেসের পণ্য আসছে" বাগের root cause, একই ডিভাইসে
      // বিজনেস-সুইচ করার সময়ও হতো, আর push হয়ে যাওয়ার পর real-time sync-এর
      // মাধ্যমে অন্য ডিভাইসেও ছড়িয়ে পড়ত। ফিক্স: businessType/
      // businessTypeLocked/enabledBusinessTypes এখন CRITICAL_KEYS-এ (wave 1) —
      // products/customers-এর মতো একই ব্যাচ/একই রেন্ডারে state-এ বসে, তাই
      // useFSSCollection ও prefix-resolve effect দুটোই প্রথমবারই সঠিক প্রিফিক্স
      // দিয়ে চলে, রেস কন্ডিশনের সুযোগই থাকে না।
      // 🔴 ফিক্স (মাল্টি-বিজনেস লোকাল-cache কন্টামিনেশন, ১৯ জুলাই ২০২৬ — চেইন-ফিক্স):
      // businessType/enabledBusinessTypes (সবসময় unprefixed, শপ-লেভেল) সবার আগে
      // আলাদাভাবে পড়ে নেওয়া হয়, যাতে products/customers ইত্যাদি বিজনেস-স্কোপড
      // key (LK()) লোড করার আগেই সঠিক prefix জানা থাকে — নাহলে chicken-and-egg
      // সমস্যা হতো (prefix জানতে businessType লাগে, businessType লোড করতে key
      // ঠিক করতে prefix লাগে)।
      const PREFIX_KEYS = [SK.businessType, SK.businessTypeLocked, SK.enabledBusinessTypes];
      const bootPrefix = await loadMany(PREFIX_KEYS);
      const businessTypeVal        = bootPrefix[SK.businessType]         || "pharmacy";
      const businessTypeLockedVal  = bootPrefix[SK.businessTypeLocked]   || false;
      const enabledBusinessTypesVal = (Array.isArray(bootPrefix[SK.enabledBusinessTypes]) && bootPrefix[SK.enabledBusinessTypes].length)
        ? bootPrefix[SK.enabledBusinessTypes]
        : [businessTypeVal];
      const _bootIsMultiBiz = enabledBusinessTypesVal.length > 1;
      const _bootBizPrefix = _bootIsMultiBiz ? (BUSINESS_TYPE_REGISTRY[businessTypeVal]?.collectionPrefix || null) : null;
      // প্রথম রেন্ডারের আগেই local prefix সেট — নিচের LK() কলগুলো ও পরের
      // FSS.setBusinessPrefix effect দুটোই এখন সঠিক/সামঞ্জস্যপূর্ণ prefix পাবে।
      setLocalBusinessPrefix(_bootBizPrefix);
      FSS.setBusinessPrefix(_bootBizPrefix);

      const CRITICAL_KEYS = [
        LK(SK.customers), LK(SK.products), LK(SK.invoices), LK(SK.txns), SK.users,
        SK.shopName, LK(SK.darkMode), LK(SK.activeTheme), LK(SK.fontSize),
        LK(SK.paymentInvoices), SK.firebaseConfig, SK.firebaseEnabled,
        SK.authSession, SK.devContact, SK.masterResetHash,
        SK.recoveryPhone, SK.recoveryPinHash,
      ];
      const DEFERRED_KEYS = [
        LK(SK.smsLog), LK(SK.deletedCustomers), LK(SK.deletedProducts), SK.smsGateway,
        SK.lastAutoBackup, SK.anthropicKey, SK.smsTemplates, SK.autoBackupEnabled,
        SK.lastDriveBackup, SK.lastSnapshotBackup,
        SK.lastMasterSync, SK.autoMasterSyncEnabled, LK(SK.suppliers), LK(SK.purchaseOrders),
        LK(SK.stockMovements), LK(SK.cashLogs), LK(SK.expenses), LK(SK.returns), LK(SK.auditLogs),
        LK(SK.quotations), LK(SK.supplierPayments), LK(SK.staffLedger), LK(SK.serialQueue),
      ];
      const boot1 = await loadMany(CRITICAL_KEYS);
      const rawCustomers    = boot1[LK(SK.customers)];
      const rawProds        = boot1[LK(SK.products)];
      const rawInvoices     = boot1[LK(SK.invoices)];
      const rawTxns         = boot1[LK(SK.txns)];
      const rawUsers        = boot1[SK.users];
      const shopNameVal     = boot1[SK.shopName];
      const darkModeVal     = boot1[LK(SK.darkMode)];
      const activeThemeVal  = boot1[LK(SK.activeTheme)];
      const fontSizeVal     = boot1[LK(SK.fontSize)];
      const rawPayInv       = boot1[LK(SK.paymentInvoices)];
      const fbCfg           = boot1[SK.firebaseConfig];
      const fbOn            = boot1[SK.firebaseEnabled];
      const savedUser       = boot1[SK.authSession];
      const devContactVal   = boot1[SK.devContact];
      const masterHashVal   = boot1[SK.masterResetHash];
      const recoveryPhoneVal   = boot1[SK.recoveryPhone];
      const recoveryPinHashVal = boot1[SK.recoveryPinHash];

      // ── #৭ স্কিমা মাইগ্রেশন — কেন্দ্রীয় SCHEMA_MIGRATIONS রেজিস্ট্রি থেকে ─────
      // আগে এখানে শুধু products-এর batches[] মাইগ্রেশন হার্ডকোড ছিল (Batch-1
      // Migration)। এখন সেটা SchemaMigration মডিউলে সাধারণীকরণ করা হয়েছে —
      // ভবিষ্যতে অন্য যেকোনো collection-এ নতুন migration লাগলে এই কোড বদলাতে
      // হবে না, শুধু SCHEMA_MIGRATIONS রেজিস্ট্রিতে এন্ট্রি যোগ করলেই চলবে।
      const { data: migratedData, stats: schemaStats } = SchemaMigration.runAll({
        products: rawProds || SEED_PRODUCTS,
      });
      const migratedProds = migratedData.products;

      // ── Firebase init (data load করার আগে দরকার নেই, কিন্তু fssReady-র জন্য) ─
      const firebaseCfg = fbCfg || null;
      const firebaseOn  = fbOn ?? false;
      if (firebaseCfg && firebaseOn) { FB.init(firebaseCfg); FSS.init(firebaseCfg); }

      // ── #৭ বুট-টাইম পারফরম্যান্স — ইনভয়েস উইন্ডোড লোড (আর কখনো পূর্ণ ব্যাকফিল না) ──
      // 🔴 রিডিজাইন (SQLITE_MIGRATION_LOG.md ব্লকার #১ ফিক্স, [এন্ট্রি ২৩+]): আগে এখানে
      // প্রথমে ৯০ দিনের windowed state সেট হতো (দ্রুত প্রথম রেন্ডার), কিন্তু তার ঠিক পরেই
      // (setTimeout 0) নিচের একটা `_patch({ invoices: allInvoicesForBoot })` কল পুরো
      // persisted invoice history আবার state-এ ঢুকিয়ে দিত। ১ কোটি ইনভয়েস স্কেলে এই
      // "পুরো ইতিহাস মেমোরিতে" মুহূর্তটাই ~৫-১০GB RAM লাগাতে পারত — বাজেট Android
      // ফোনে ক্র্যাশ/হ্যাং-এর সবচেয়ে বড় ঝুঁকি ছিল এটাই। সেই পূর্ণ-ব্যাকফিল সম্পূর্ণ
      // সরিয়ে ফেলা হলো — state.invoices এখন থেকে বুটের পর সবসময় windowed-ই থাকে,
      // কখনো পুরো অ্যারে লাইভ মেমরিতে আসে না।
      //
      // Window ৯০ দিনের বদলে ৬ মাস (১৮০ দিন) করা হলো — কারণ ঠিক নিচেই
      // archiveOldInvoices() effect (দেখুন লাইন ~১২০০৫) ৬ মাসের বেশি পুরনো ইনভয়েস
      // স্বয়ংক্রিয়ভাবে state থেকে সরিয়ে InvoiceArchive (IndexedDB)-এ রাখে। দুটো
      // কাটঅফ একই (৬ মাস) রাখা মানে বুটের ঠিক পরের state আর archiveOldInvoices()
      // চালানোর পরের "স্টেডি-স্টেট" state — এই দুটো এক এবং অভিন্ন, কোনো
      // মধ্যবর্তী গ্যাপ (যেমন আগের ৯০দিন-বনাম-৬মাস পার্থক্য) থাকে না।
      //
      // ৬ মাসের চেয়ে পুরনো কোনো ইনভয়েস দরকার হলে (কাস্টমার হিস্ট্রি, রিটার্ন
      // সার্চ, রিপোর্ট) — সেই on-demand লুকআপ ইতিমধ্যেই আছে: InvoiceArchive.getById()/
      // .findByQuery()/.queryPage() (IndexedDB-ভিত্তিক আর্কাইভ, দেখুন কল-সাইট
      // ReturnModule.searchInvoice, Dashboard কাস্টমার-হিস্ট্রি, void history ইত্যাদি)।
      // এই মেকানিজম নতুন কিছু না — আগে থেকেই এই কল-সাইটগুলো InvoiceArchive ব্যবহার
      // করত (কারণ ৬ মাসের বেশি পুরনো ডেটা এমনিতেও কিছুক্ষণ পরই state থেকে সরে
      // যেত); শুধু এখন বুটের ঠিক পরের মুহূর্তেও (আগের মতো সাময়িকভাবে "সব মেমোরিতে"
      // না গিয়ে) একই নিয়ম মেনে চলছে, তাই আচরণে নতুন কোনো গ্যাপ তৈরি হয়নি।
      //
      // ⚠️ সততার সাথে নোট (ভবিষ্যৎ সেশনের জন্য): এই সেশনে App.jsx-এর প্রতিটা
      // কল-সাইট যাচাই করে নিশ্চিত হওয়া হয়নি যে "live invoices state"-এর উপর
      // নির্ভরশীল প্রতিটা জায়গা (POS/dashboard-এর বাইরেও) InvoiceArchive
      // fallback-এ ঠিকমতো পড়ে। বড় স্কেলে (১ কোটি ইনভয়েস) real-device টেস্টের
      // সময় বিশেষভাবে "৬ মাসের বেশি পুরনো ইনভয়েস খোঁজা/দেখা" প্রতিটা স্ক্রিনে
      // (ইনভয়েস হিস্ট্রি, কাস্টমার ডিটেইল, রিটার্ন, ভয়েড হিস্ট্রি) যাচাই করা উচিত।
      const allInvoicesForBoot = rawInvoices || [];
      const invoiceCutoff90 = new Date();
      invoiceCutoff90.setMonth(invoiceCutoff90.getMonth() - 6); // archiveOldInvoices()-এর সাথে সিঙ্কড কাটঅফ
      const invoiceCutoff90Key = _dateKeyOf(invoiceCutoff90);
      const recentInvoicesForBoot = allInvoicesForBoot.length > 500
        ? allInvoicesForBoot.filter(i => !i.dateKey || i.dateKey >= invoiceCutoff90Key)
        : allInvoicesForBoot; // ছোট দোকানে (৫০০-এর কম ইনভয়েস) windowing-এর দরকারই নেই

      // ── সব state একসাথে batch update — একটাই React re-render (ক্রিটিক্যাল অংশ) ──
      _patch({
        customers:             rawCustomers        || SEED_CUSTOMERS,
        products:              migratedProds,
        invoices:              recentInvoicesForBoot,
        txns:                  rawTxns             || [],
        users:                 rawUsers            || SEED_USERS,
        shopName:              shopNameVal         || "SBM",
        darkMode:              darkModeVal         ?? true,
        // 🆕 (৬ আগস্ট ২০২৬, সেলুন প্রিমিয়াম রিডিজাইন) — salon বিজনেসে কোনো থিম আগে থেকে
        // সেভ করা না থাকলে (নতুন শপ/প্রথম বুট) ডিফল্ট "Vanity Chrome"-এ যাবে, নাহলে অন্য
        // সব বিজনেসের মতোই "Linear Void"। ইউজার একবার ম্যানুয়ালি থিম বদলালে সেটাই সেভ/persist
        // থাকবে (activeThemeVal সেট হয়ে যাবে), এই ডিফল্ট লজিক আর প্রযোজ্য হবে না।
        activeTheme:           (activeThemeVal && activeThemeVal !== "dark")
          ? activeThemeVal
          : (businessTypeVal === "salon" ? "threadsink" : "linearvoid"),
        fontSize:              fontSizeVal         ?? 15,
        paymentInvoices:       rawPayInv           || [],
        firebaseConfig:        firebaseCfg,
        firebaseEnabled:       firebaseOn,
        currentUser:           savedUser?.id ? savedUser : null,
        devContact:            devContactVal       || DEV_CONTACT,
        masterResetHash:       masterHashVal       || DEV_MASTER_HASH,
        businessType:          businessTypeVal,
        businessTypeLocked:    businessTypeLockedVal,
        enabledBusinessTypes:  enabledBusinessTypesVal,
        authChecked:           true,
        loaded:                true,
        schemaMigrationStats:  schemaStats.totalMigrated > 0 ? schemaStats : null, // #৭ — কিছু মাইগ্রেট হলেই শুধু দেখায়
      });

      // ── recovery state (local useState — store-এর বাইরে) ───────────────────
      setRecoveryPhoneState  (recoveryPhoneVal   || "");
      setRecoveryPinHashState(recoveryPinHashVal || null);

      // ── Device ID generate করুন (একবারই) ───────────────────────────────────
      if (!localStorage.getItem("hg_device_id")) {
        localStorage.setItem("hg_device_id", "dev_" + Math.random().toString(36).slice(2, 10) + "_" + Date.now().toString(36));
      }

      // 🔴 আগে এখানে একটা setTimeout(() => { _patch({ invoices: allInvoicesForBoot }); }, 0)
      // ছিল — প্রথম পেইন্টের পরপরই পুরো ইনভয়েস ইতিহাস আবার state-এ ঢুকিয়ে দিত
      // (windowing সাময়িক, শুধু "প্রথম রেন্ডার দ্রুত করা"র জন্য ছিল, চূড়ান্ত অবস্থা
      // ছিল "সব মেমোরিতে")। এটা ইচ্ছাকৃতভাবে সরানো হলো — এখন recentInvoicesForBoot-ই
      // (৬ মাসের window) চূড়ান্ত অবস্থা, কখনো পুরো অ্যারে state-এ আসে না। বিস্তারিত
      // ব্যাখ্যা ঠিক উপরে (allInvoicesForBoot/recentInvoicesForBoot ডিফাইন করা
      // জায়গায়)। allInvoicesForBoot ভ্যারিয়েবলটা নিচে কোথাও আর ব্যবহার হচ্ছে না —
      // ইচ্ছাকৃতভাবে রাখা হয়েছে শুধু উপরের cutoff-ফিল্টার হিসাব করতে।

      // ── Wave 2 — প্রথম পেইন্টের জন্য জরুরি নয় এমন কালেকশন, পেইন্টের পরে ──────
      // (auditLogs/cashLogs/stockMovements/expenses/returns/quotations/
      // supplierPayments/suppliers/purchaseOrders — এগুলো বড় হতে পারে এবং
      // Dashboard-এর প্রথম রেন্ডারে সরাসরি লাগে না। smsLog/deletedCustomers/
      // deletedProducts/smsGateway/Settings-সংক্রান্ত টগলও একই wave-এ।)
      // ইনভয়েস ব্যাকফিলের মতোই একই প্যাটার্ন — setTimeout(0), boot ব্লক করে না।
      setTimeout(async () => {
        const boot2 = await loadMany(DEFERRED_KEYS);
        _patch({
          smsLog:                boot2[LK(SK.smsLog)]              || [],
          deletedCustomers:      boot2[LK(SK.deletedCustomers)]     || [],
          deletedProducts:       boot2[LK(SK.deletedProducts)]      || [],
          smsGateway:            boot2[SK.smsGateway]           || null,
          lastAutoBackup:        boot2[SK.lastAutoBackup]       || null,
          lastDriveBackup:       boot2[SK.lastDriveBackup]      || null,
          lastSnapshotBackup:    boot2[SK.lastSnapshotBackup]   || null,
          anthropicKey:          boot2[SK.anthropicKey]         || "",
          smsTemplates:          boot2[SK.smsTemplates]         || null,
          autoBackupEnabled:     boot2[SK.autoBackupEnabled]    ?? false,
          lastMasterSync:        boot2[SK.lastMasterSync]       || null,
          autoMasterSyncEnabled: boot2[SK.autoMasterSyncEnabled]?? false,
          suppliers:             boot2[LK(SK.suppliers)]            || [],
          purchaseOrders:        boot2[LK(SK.purchaseOrders)]       || [],
          stockMovements:        boot2[LK(SK.stockMovements)]       || [],
          cashLogs:              boot2[LK(SK.cashLogs)]             || [],
          expenses:              boot2[LK(SK.expenses)]             || [],
          returns:               boot2[LK(SK.returns)]              || [],
          auditLogs:             boot2[LK(SK.auditLogs)]            || [],
          quotations:            boot2[LK(SK.quotations)]           || [],
          supplierPayments:      boot2[LK(SK.supplierPayments)]     || [],
          staffLedger:           boot2[LK(SK.staffLedger)]          || [],
          serialQueue:           boot2[LK(SK.serialQueue)]          || [],
          // businessType/businessTypeLocked/enabledBusinessTypes এখন wave 1-এই
          // সেট হয়ে গেছে (দেখুন উপরের CRITICAL_KEYS কমেন্ট) — এখানে আর বসানো হয়
          // না, নাহলে wave 2 আবার সেগুলোকে (এই মুহূর্তে ঠিকমতোই থাকা) ওভাররাইট
          // করে ফেলতে পারত যদি কোথাও ইতিমধ্যে বদলে গিয়ে থাকে (যেমন remote
          // businessConfig sync দ্রুত এসে গেলে)।
          settingsLoaded:        true, // 🔴 এখন থেকেই autoBackupEnabled/autoMasterSyncEnabled-এর real value store-এ বসলো — persistence effect চালু করা নিরাপদ
        });
      }, 0);

      // ── Notification permission ও FCM setup — deferred (UI block না করতে) ──
      setTimeout(async () => {
        try {
          await Notif.requestPermission();
          const sn = shopNameVal || "SBM";
          await Notif.setupPushNotifications(sn);
        } catch(e) { /* silent */ }
      }, 3000);
    })();
  }, []);

  // 📱 Multi-device REAL-TIME sync: Firestore onSnapshot (record-level, no polling)
  // যেকোনো ফোনে (admin/staff) কোনো একটা রেকর্ড বদলালেই বাকি সব ফোনে
  // millisecond-এ পৌঁছায় — সম্পূর্ণ array ওভাররাইট হয় না, তাই conflict/mismatch
  // হয় না, আর Firestore-এর built-in offline cache থাকায় নেট না থাকলেও কাজ করে।
  const [fssReady, setFssReady] = useState(false);
  // 🔴 ফিক্স: centralRecoveryPush ব্যর্থ হলে এখন silent না — এই ফ্ল্যাগ true হলে
  // Settings/Sync Diagnostics কার্ডে owner-কে দেখানো হবে যে recovery backup আপডেট হয়নি।
  const [recoveryPushFailed, setRecoveryPushFailed] = useState(false);

  // 🔴 ফিক্স (TDZ ক্র্যাশ): showToast আগে useCallback-এর dependency array-তে
  // ব্যবহার হতো কিন্তু const হিসেবে declare হতো অনেক পরে (~লাইন 12587-এ) —
  // ফলে প্রতিবার অ্যাপ ওপেন হওয়ার সাথে সাথেই
  // "Cannot access 'showToast' before initialization" ক্র্যাশ হতো। এখন এই
  // declaration-টা autoBalanceDriftCheck-এর আগে আনা হলো (dependencies
  // setToast/safeTimeout দুটোই এর আগেই declare করা আছে, তাই এখানে তোলা নিরাপদ)।
  const showToast = useCallback((msg, color = "#22c55e") => {
    // 🔴 ফিক্স: warning/error (যেমন Master Reset-এর Firestore detail) বেশি লম্বা
    // হয় আর গুরুত্বপূর্ণ — সবুজ "সেভ হয়েছে ✓"-এর মতো ৩.২s-এ পড়া যায় না।
    const dur = (color === "#f59e0b" || color === "#ef4444") ? 8000 : 3200;
    setToast({ msg, color }); safeTimeout(() => setToast(null), dur);
  }, [safeTimeout]);

  // 🆕 setTab (পারফরম্যান্স ফিক্স ২৫ জুলাই ২০২৬): এখানে বসানো হয়েছে কারণ এটা
  // showToast-এর উপর নির্ভর করে (dependency array-তে) — showToast-এর আগে
  // রাখলে TDZ ক্র্যাশ হতো।
  const setTab = useCallback((newTab) => {
    const STAFF_RESTRICTED = ["sms", "ai", "returns", "supplier"];
    if (currentUser?.role === "staff" && STAFF_RESTRICTED.includes(newTab)) {
      showToast?.("স্টাফ অ্যাকাউন্টে এই পেজ অ্যাক্সেস নেই", "error");
      return;
    }
    // "এক্সপেন্স ট্রেকার" শুধু Admin রোল অ্যাক্সেস করতে পারবে
    if (newTab === "expense" && currentUser?.role !== "admin" && currentUser?.role !== "owner") {
      showToast?.("এই পেজ শুধু Admin অ্যাক্সেস করতে পারবে", "error");
      return;
    }
    if (tab === "invoice" && newTab !== "invoice") {
      _set("invoiceKey", (k) => k + 1);
      _set("preselectedCust",  null);
      _set("preselectedType",  null);
    }
    _set("tab", newTab);
  }, [currentUser, showToast, tab, _set]);

  // 🆕 কম্পোজিট কলব্যাক (পারফরম্যান্স ফিক্স ২৫ জুলাই ২০২৬): আগে JSX-এ ইনলাইন
  // arrow function হিসেবে পাস হতো (প্রতি রেন্ডারে নতুন রেফারেন্স তৈরি হতো,
  // যেটা React.memo-কে অকেজো করে দিত)। এখন useCallback দিয়ে স্থিতিশীল রেফারেন্স।
  const openCustomerDetail = useCallback((id) => {
    setDetailCId(id);
  }, [setDetailCId]);

  const goToInvoiceFromCustomers = useCallback((c, type) => {
    setPreselectedCust(c); setPreselectedType(type || null); setTab("invoice");
  }, [setPreselectedCust, setPreselectedType, setTab]);

  const goToInvoiceFromDetail = useCallback((c, type) => {
    setPreselectedCust(c); setPreselectedType(type || null); setTab("invoice"); setDetailCId(null);
  }, [setPreselectedCust, setPreselectedType, setTab, setDetailCId]);

  const clearPreselected = useCallback(() => {
    setPreselectedCust(null); setPreselectedType(null);
  }, [setPreselectedCust, setPreselectedType]);

  // 🆕 (সেলুন ধাপ ৩, টোকেন/সিরিয়াল কিউ) — একটা অপেক্ষমান টোকেন থেকে সরাসরি
  // ইনভয়েস ট্যাবে গিয়ে ওয়াক-ইন কার্ট প্রি-ফিল করা (নাম/ফোন/স্টাফ/সেবা-নোট)।
  // টোকেনটা "in_progress"-এ মার্ক হয় (যদি আগে থেকে না থাকে), যাতে বিলিং শুরু
  // হয়েছে বোঝা যায় — actual "billed" মার্ক হবে ইনভয়েস সেভ হলে (দেখুন
  // onQueueTokenBilled)।
  // 🔴 (৭ আগস্ট ২০২৬, সেলুন — সরাসরি টোকেন কার্ডে বিল ফাইনাল) — আগে এটা
  // setTab("invoice") দিয়ে পুরো ইনভয়েস ট্যাবে নিয়ে যেত। এখন ট্যাব বদলায় না —
  // queueBillPrefill সেট হওয়া মাত্র নিচে একটা ফুল-স্ক্রিন ওভারলে
  // (MemoSmartInvoiceBuilder, অবিকৃত/একই createInvoice লজিক) খুলে যায়, ঠিক
  // টোকেন কার্ডের উপরেই — ইউজার কখনো আলাদা ইনভয়েস ট্যাবে যান না।
  const goToInvoiceFromQueue = useCallback((token) => {
    if (!token) return;
    setQueueBillPrefill({
      tokenId:  token.id,
      name:     token.customerName || "",
      phone:    token.phone || "",
      staffId:  token.staffId || null,
      note:     token.service || token.note || "",
    });
    if (token.status === "waiting") {
      setSerialQueue(prev => (prev || []).map(t =>
        t.id === token.id ? { ...t, status: "in_progress", startedAt: Date.now() } : t
      ));
    }
  }, [setQueueBillPrefill, setSerialQueue]);

  // ইনভয়েস সেভ হওয়ার পর কল হয় (queueBillPrefill.tokenId থাকলে) — টোকেনটা
  // "billed" মার্ক করে দেয় এবং prefill স্টেট ক্লিয়ার করে দেয়।
  const onQueueTokenBilled = useCallback((tokenId) => {
    if (!tokenId) return;
    setSerialQueue(prev => (prev || []).map(t =>
      t.id === tokenId ? { ...t, status: "billed", billedAt: Date.now() } : t
    ));
    setQueueBillPrefill(null);
  }, [setSerialQueue, setQueueBillPrefill]);

  // 🔴 ফিক্স (রুট কজ ৩ — রিকনেক্ট-পরবর্তী ড্রিফট-অ্যালার্ট): অফলাইন রেসের সব
  // কোণা কখনোই ১০০% প্রুফ করা যাবে না (উপরের void/return/createInvoice
  // ফিক্সগুলো prevention, কিন্তু ভবিষ্যতে নতুন race condition এলেও যেন ধরা
  // পড়ে তার জন্য এটা একটা safety net)। reconnect-এর কিছুক্ষণ পর (queue
  // flush-গুলো শেষ হওয়ার সময় দিয়ে) প্রতিটা কাস্টমারের বর্তমান balance তার
  // সবচেয়ে সাম্প্রতিক txn-এর balanceAfter-এর সাথে মিলিয়ে দেখা হয় — এই দুটো
  // ভিন্ন হলে মানে কোথাও sync miss হয়েছে। ইচ্ছাকৃতভাবে এটা কিছু auto-repair
  // করে না (ভুল "auto-fix" নিজেই নতুন ডেটা-লস বাগ হতে পারত) — শুধু owner/
  // admin-কে (স্টাফকে না) toast + SyncLog দিয়ে জানায়।
  const autoBalanceDriftCheck = useCallback(() => {
    try {
      const role = useAppStore.getState().currentUser?.role;
      if (role !== "owner" && role !== "admin") return;
      const allCustomers = useAppStore.getState().customers || [];
      const allTxns = useAppStore.getState().txns || [];
      const latestTxnByCustomer = new Map();
      for (const t of allTxns) {
        if (!t.customerId) continue;
        const prev = latestTxnByCustomer.get(t.customerId);
        if (!prev || new Date(t.date || 0) > new Date(prev.date || 0)) latestTxnByCustomer.set(t.customerId, t);
      }
      const driftedCustomers = [];
      for (const c of allCustomers) {
        const lastTxn = latestTxnByCustomer.get(c.id);
        if (!lastTxn || lastTxn.balanceAfter === undefined || lastTxn.balanceAfter === null) continue;
        if (Math.round(lastTxn.balanceAfter) !== Math.round(c.balance || 0)) {
          driftedCustomers.push({ id: c.id, name: c.name, expected: lastTxn.balanceAfter, actual: c.balance || 0 });
        }
      }
      if (driftedCustomers.length) {
        const msg = `রিকনেক্ট-পরবর্তী ব্যালেন্স ড্রিফট শনাক্ত: ${driftedCustomers.length} জন কাস্টমারের হিসাব মিলছে না`;
        showToast(msg, "#ef4444");
        SyncLog.add("error", `${msg} — উদাহরণ: ${driftedCustomers.slice(0, 3).map(d => `${d.name || d.id} (প্রত্যাশিত ৳${d.expected}, বর্তমান ৳${d.actual})`).join(", ")}`);
      }
    } catch (e) {
      logErrorToCentral?.("autoBalanceDriftCheck", e, {});
    }
  }, [showToast]);

  useEffect(() => {
    if (!loaded || !firebaseEnabled || !firebaseConfig) {
      FSS.teardown();
      setFssReady(false);
      return;
    }
    const ok = FSS.init(firebaseConfig);
    setFssReady(ok);
    if (!ok) return;

    SyncLog.add("info", "Firestore রিয়েলটাইম সিঙ্ক চালু হয়েছে (instant, record-level)");
    // 🔴 ফিক্স: আগে ব্যর্থ হওয়া updateStats() delta গুলো কখনো রিট্রাই হতো না —
    // এখন প্রতিবার Firestore রেডি হওয়ার সময় pending queue ফ্লাশ করার চেষ্টা হয়
    FSS.flushPendingStats();
    // 🔴 ফিক্স: অফলাইনে জমে থাকা ইনভয়েসের স্টক/বাকি রিকনসিলিয়েশন (createInvoice()-এর
    // Optimistic UI ব্যাকগ্রাউন্ড ব্লক দেখুন) একইভাবে এখানেও রিট্রাই করা হয়
    FSS.flushPendingSalesTxns({ setProducts, setCustomers, setInvoices });
    // 🔴 ফিক্স: অফলাইনে ভয়েড/রিটার্ন করা হলে জমে থাকা স্টক-রিস্টোর/ব্যালেন্স-
    // রিভার্সাল কিউ — দেখুন FSS.queuePendingVoidRestore()-এর কমেন্ট
    FSS.flushPendingVoidRestores({ setProducts, setCustomers });
    // 🔴 ফিক্স (রুট কজ — ক্রয় এন্ট্রিতে রিট্রাই-কিউ না থাকা): দেখুন
    // FSS.queuePendingPurchaseStock()-এর কমেন্ট
    FSS.flushPendingPurchaseStock({ setProducts, setPurchaseOrders });
    FSS.flushPendingExpiredRemoval({ setProducts });
    // 🔴 ফিক্স (রুট কজ ৩): flush-গুলো শেষ হওয়ার সময় দিয়ে ১৫ সেকেন্ড পর ব্যালেন্স
    // ড্রিফট চেক — দেখুন autoBalanceDriftCheck()-এর কমেন্ট
    setTimeout(() => autoBalanceDriftCheck(), 15000);

    // Device presence (RTDB) — Settings স্ক্রিনে active devices লিস্টের জন্য
    FB.init(firebaseConfig);
    FB.registerDevice({
      platform: typeof window !== "undefined" && window.Capacitor?.isNativePlatform?.() ? "android" : "web",
      ua: navigator?.userAgent?.slice(0, 80) || "unknown",
    });
    const devTimer = setInterval(async () => {
      const devs = await FB.getActiveDevices();
      setActiveDevices(devs);
    }, 5 * 60 * 1000);
    FB.getActiveDevices().then(devs => setActiveDevices(devs));

    const onOnline = () => {
      const r = FSS.init(firebaseConfig);
      setFssReady(r);
      if (r) {
        FSS.flushPendingStats();
        FSS.flushPendingSalesTxns({ setProducts, setCustomers, setInvoices });
        FSS.flushPendingVoidRestores({ setProducts, setCustomers });
        FSS.flushPendingPurchaseStock({ setProducts, setPurchaseOrders });
        FSS.flushPendingExpiredRemoval({ setProducts });
        // 🔴 ফিক্স (রুট কজ ৩): দেখুন autoBalanceDriftCheck()-এর কমেন্ট
        setTimeout(() => autoBalanceDriftCheck(), 15000);
      }
    };
    window.addEventListener("online", onOnline);

    return () => {
      clearInterval(devTimer);
      window.removeEventListener("online", onOnline);
      FSS.teardown();
      setFssReady(false);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [loaded, firebaseEnabled, firebaseConfig]);

  // 🆕 নোটিফিকেশন মডিউল থেকে "এখনই সিঙ্ক করুন" — বিদ্যমান ৪টা flush ফাংশনই আবার
  // কল করা হয় (এমনিতেই reconnect/heartbeat-এ যেগুলো চলে), শুধু ম্যানুয়ালি এখনই।
  // এতে কোনো নতুন Firestore read নেই — শুধু localStorage-কিউতে জমে থাকা এন্ট্রি
  // write করার চেষ্টা, যেটা এমনিতেই হতো।
  const retryPendingSyncNow = useCallback(async () => {
    if (!FSS.isReady()) { showToast("Firestore সংযোগ নেই — নেট চেক করুন", "#ef4444"); return; }
    await FSS.flushPendingStats();
    await FSS.flushPendingSalesTxns({ setProducts, setCustomers, setInvoices });
    await FSS.flushPendingVoidRestores({ setProducts, setCustomers });
    await FSS.flushPendingPurchaseStock({ setProducts, setPurchaseOrders });
    await FSS.flushPendingExpiredRemoval({ setProducts });
    showToast("✅ সিঙ্ক রিট্রাই করা হয়েছে");
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // 🆕 নোটিফিকেশন মডিউল থেকেও কনফ্লিক্ট রিজলভ করা যাবে — SettingsModule-এর
  // resolveConflict-এর সাথে যুক্তি হুবহু একই (single source of truth রাখতে এখানে
  // App-লেভেলে তোলা হলো, দুই জায়গা থেকেই কল করা যায়)। "remote" পছন্দে কোনো
  // write নেই (শুধু dismiss); "local" পছন্দে conflict.local-এ যা captured আছে
  // সেটাই সরাসরি write হয় — নতুন কোনো read লাগে না।
  const conflictCollectionMapTop = {
    customers, products, invoices, txns, purchaseOrders, cashLogs,
    suppliers, expenses, returns, quotations, supplierPayments, paymentInvoices,
  };
  const resolveConflictTop = useCallback((conflict, choice) => {
    if (choice === "remote") {
      ConflictQueue.dismiss(conflict.collection, conflict.recordId);
      showToast("✅ কনফ্লিক্ট সমাধান হয়েছে (সার্ভার ভার্সন বহাল)");
      return;
    }
    const arr = conflictCollectionMapTop[conflict.collection] || [];
    const current = arr.find(r => String(r.id) === conflict.recordId);
    if (!current) {
      showToast("রেকর্ড খুঁজে পাওয়া যায়নি — হয়তো মুছে ফেলা হয়েছে", "#ef4444");
      ConflictQueue.dismiss(conflict.collection, conflict.recordId);
      return;
    }
    const merged = { ...current };
    conflict.fields.forEach(f => { merged[f.field] = conflict.local[f.field]; });
    const finalRec = withTs(merged);
    if (FSS.isReady()) FSS.setRecord(conflict.collection, conflict.recordId, finalRec);
    ConflictQueue.dismiss(conflict.collection, conflict.recordId);
    showToast("✅ এই ডিভাইসের ভার্সন প্রয়োগ হয়েছে");
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [customers, products, invoices, txns, purchaseOrders, cashLogs, suppliers, expenses, returns, quotations, supplierPayments, paymentInvoices, showToast]);


  // localStorage-এ persist করা হয় যাতে ট্যাব বদলালে/অ্যাপ রিস্টার্ট হলেও
  // সময়টা হারিয়ে না যায়। কোনো Firestore read/write নেই, সম্পূর্ণ লোকাল।
  const [fssDisconnectedSince, setFssDisconnectedSince] = useState(() => {
    try { return Number(localStorage.getItem("sbm_fss_disconnected_since")) || null; } catch { return null; }
  });
  useEffect(() => {
    if (firebaseEnabled && !fssReady) {
      setFssDisconnectedSince(prev => {
        if (prev) return prev;
        const now = Date.now();
        try { localStorage.setItem("sbm_fss_disconnected_since", String(now)); } catch {}
        return now;
      });
    } else if (fssDisconnectedSince) {
      setFssDisconnectedSince(null);
      try { localStorage.removeItem("sbm_fss_disconnected_since"); } catch {}
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [fssReady, firebaseEnabled]);

  // 🔴 ফিক্স (হার্টবিট/resync কভারেজ গ্যাপ): useFSSCollection-এর ভেতরের ২০-সেকেন্ড
  // heartbeat + resume/online resync (useResyncTick) শুধু সেই হুক ব্যবহার করা
  // কালেকশনগুলোতেই (customers/products/ইত্যাদি) কাজ করত। কিন্তু resetMarker,
  // invoices, txns, stockMovements, cashLogs — এই ৫টার নিজস্ব কাস্টম onSnapshot
  // effect আগে শুধু [fssReady]-এর ওপর নির্ভর করত, resyncTick ছিল না — মানে
  // Android background-এ এই listener-গুলোর কানেকশন নীরবে মরে গেলে ২০ সেকেন্ডে
  // নিজে থেকে সারত না (exit+login লাগত), ঠিক আগের products/customers বাগটার
  // মতোই। এখন App()-লেভেলে একই resyncTick নিচের সবগুলো effect-এর dependency-তে
  // যোগ করা হচ্ছে, যাতে এরাও heartbeat/resume/online-এ পুরোপুরি re-subscribe হয়।
  const appResyncTick = useResyncTick();

  // 🔴 ফিক্স (durability গ্যাপ, পার্ট ২): pushDurable() দিয়ে SyncOutbox-এ persist
  // হওয়া invoices/txns/stockMovements/cashLogs/returns/auditLogs এন্ট্রি এই effect
  // ছাড়া কখনো retry হতো না (useFSSCollection-এর ভেতরের flush logic শুধু সেই
  // হুক-ব্যবহারকারী কালেকশনগুলোর জন্যই)। boot/resume/online/heartbeat-এ (fssReady
  // বা appResyncTick বদলালে) এই ৬টা windowed কালেকশনের বাকি-থাকা outbox এন্ট্রি
  // আবার Firestore-এ পাঠানোর চেষ্টা করা হয়। (🔴 ফিক্স — Phase 8: returns/auditLogs
  // এখন windowed হওয়ায় এই তালিকায় যোগ করা হলো, নাহলে অফলাইনে তৈরি হওয়া রিটার্ন/
  // অডিট এন্ট্রি reconnect-এর পরও কখনো ফ্লাশ হতো না।)
  useEffect(() => {
    if (!fssReady) return;
    let cancelled = false;
    (async () => {
      if (GLOBAL_RESET_MARKER_AT && (Date.now() - GLOBAL_RESET_MARKER_AT < 120000)) return;
      for (const coll of ["invoices", "txns", "stockMovements", "cashLogs", "returns", "auditLogs"]) {
        const items = await SyncOutbox.getAll(coll);
        if (cancelled || !items.length) continue;
        const currentPrefix = FSS._businessPrefix || null;
        items.forEach(it => {
          // 🔴 ফিক্স (মাল্টি-বিজনেস কন্টামিনেশন): দেখুন useFSSCollection-এর একই
          // ফিক্সের কমেন্ট — এই ৪টা windowed কালেকশনের outbox flush-ও এখন
          // prefix-filtered।
          const itemPrefix = Object.prototype.hasOwnProperty.call(it, "prefix") ? it.prefix : null;
          if (itemPrefix !== currentPrefix) return;
          FSS.setRecord(coll, it.recordId, it.rec).then(res => {
            if (res && res.ok === false) {
              logErrorToCentral?.(`windowed-outbox-flush:${coll}`, new Error(res.msg || "flush failed"), { id: it.recordId });
              // ব্যর্থ হলে outbox-এ থেকেই যায় — পরের flush সাইকেলে আবার চেষ্টা হবে
            } else {
              SyncOutbox.remove(coll, it.recordId);
            }
          });
        });
      }
      // 🔴 ফিক্স (স্টক/ব্যালেন্স রিকনসিলিয়েশন — periodic retry গ্যাপ): আগে
      // flushPendingSalesTxns/VoidRestores/PurchaseStock/Stats শুধু boot,
      // 'online' ইভেন্ট আর business-switch-এ রিট্রাই হতো — অ্যাপ খোলা থাকা
      // অবস্থায় (অনলাইন কিন্তু ফ্লাকি নেটে) একবার ব্যর্থ হলে সেই এন্ট্রি পরের
      // app-restart/online-toggle পর্যন্ত localStorage-এই আটকে থাকত, যদিও এই
      // একই effect-এর heartbeat (appResyncTick, ~২০ সেকেন্ড) অন্য ৬টা
      // windowed কালেকশনের outbox ঠিকই বারবার রিট্রাই করত। এখন একই heartbeat-এ
      // এগুলোও যোগ করা হলো। প্রতিটা ফাংশনই কিউ খালি থাকলে সাথে সাথেই রিটার্ন
      // করে (কোনো Firestore read/write হয় না) — তাই খালি কিউতে এটা প্রতি
      // ২০ সেকেন্ডে ডাকলেও Firestore read কোটায় কোনো বাড়তি খরচ নেই।
      if (!cancelled) {
        FSS.flushPendingStats();
        FSS.flushPendingSalesTxns({ setProducts, setCustomers, setInvoices });
        FSS.flushPendingVoidRestores({ setProducts, setCustomers });
        FSS.flushPendingPurchaseStock({ setProducts, setPurchaseOrders });
        FSS.flushPendingExpiredRemoval({ setProducts });
      }
    })();
    return () => { cancelled = true; };
  }, [fssReady, appResyncTick]);

  // 🔴 ফিক্স (multi-device data-resurrection bug): অন্য কোনো ডিভাইস থেকে চালানো
  // Master Reset-ও যেন এই ডিভাইসের useFSSCollection-গুলোর seed-on-empty চেকে
  // ধরা পড়ে (আগে শুধু নিজের localStorage-এর "sbm_just_reset" চেক হতো, যেটা
  // অন্য ডিভাইসে বসানো রিসেট বুঝতে পারত না — ফলে স্টাফ ফোন খোলা থাকলে reset-এর
  // পরও পুরনো local ডেটা আবার Firestore-এ push হয়ে "রিসেট উল্টে যাওয়া" বাগ হতো)।
  useEffect(() => {
    if (!fssReady || !FSS._db) return;
    const unsub = FSS.subscribeResetMarker((at) => { GLOBAL_RESET_MARKER_AT = at || 0; });
    return () => unsub();
  }, [fssReady, appResyncTick]);

  // 🆕 businessType/businessTypeLocked — Firestore meta/businessConfig রিয়েল-টাইম সিংক
  // (owner যেই মোড সেট করবে, admin/owner-এর অন্য ফোনেও অ্যাপ রিস্টার্ট ছাড়াই সাথে সাথে সেই মোড আসবে)
  // 🆕 ধাপ ৫ (Staff Permission System, ১৮ জুলাই ২০২৬): আগে এই sync স্টাফের ফোনেও
  // প্রযোজ্য ছিল — মানে owner Business Switcher দিয়ে বদলালে স্টাফের ফোনও সাথে সাথে
  // ফলো করত। এটা ধাপ ৫-এর মূল দাবির সাথে সংঘর্ষ করছিল: স্টাফ তার
  // admin-assigned business-এ সবসময় লক থাকবে, owner অন্য business-এ সুইচ করলেও
  // স্টাফের ডেটা/UI বদলাবে না। তাই এখন থেকে businessType-এর remote-follow শুধু
  // admin/owner ডিভাইসেই প্রযোজ্য — স্টাফের জন্য আলাদা লক effect (নিচে, useStaffAssignedBusinessLock) দায়িত্ব নেয়।
  useEffect(() => {
    if (!fssReady || !FSS._db || !settingsLoaded) return;
    const isStaffDevice = currentUser?.role === "staff";
    const unsub = FSS.subscribeBusinessConfig((data) => {
      if (data) {
        // remote-এ ডেটা আছে — এটাই সত্য উৎস, লোকাল স্টেট এর সাথে মিলিয়ে নাও
        // (শুধু admin/owner ডিভাইসে — স্টাফ তার নিজের assignedBusinessType-এ লক থাকে)
        if (!isStaffDevice) {
          if (typeof data.businessType === "string" && data.businessType !== businessType) setBusinessType(data.businessType);
        }
        if (typeof data.businessTypeLocked === "boolean" && data.businessTypeLocked !== businessTypeLocked) setBusinessTypeLocked(data.businessTypeLocked);
        // 🆕 ধাপ ২: enabledBusinessTypes — পুরনো ডকুমেন্টে (এই ফিল্ড লেখার আগে
        // তৈরি) এটা না থাকতে পারে, তখন businessType-কেই একমাত্র enabled ধরা হয়
        // (single-business আচরণ অপরিবর্তিত)।
        const remoteEnabled = Array.isArray(data.enabledBusinessTypes) && data.enabledBusinessTypes.length
          ? data.enabledBusinessTypes
          : [data.businessType || businessType];
        if (JSON.stringify(remoteEnabled) !== JSON.stringify(enabledBusinessTypes)) setEnabledBusinessTypes(remoteEnabled);
      } else if (businessTypeLocked && !isStaffDevice) {
        // 🔴 এই দোকানের জন্য এখনো কোনো meta/businessConfig ডকুমেন্ট নেই (আপডেটের পর
        // প্রথমবার) — এই ডিভাইসের বর্তমান লক করা মোডটাই "seed" হিসেবে Firestore-এ
        // লিখে দাও, যাতে ডেটা হারানোর কোনো ঝুঁকি না থাকে।
        // 🆕 ধাপ ৫: শুধু admin/owner ডিভাইস থেকেই seed করা হয় — স্টাফের ফোন থেকে
        // shop-wide businessConfig কখনো লেখা উচিত না।
        FSS.setBusinessConfig(businessType, businessTypeLocked, enabledBusinessTypes);
      }
    });
    return () => unsub();
  }, [fssReady, settingsLoaded, businessType, businessTypeLocked, enabledBusinessTypes, currentUser?.role]);

  // 🆕 Multi-Business bridge ফিক্স (১৯ জুলাই ২০২৬): admin.html কেন্দ্রীয়
  // subscriptions/{phone} ডকুমেন্টে enabledBusinessTypes/activeBusinessType
  // লেখে, কিন্তু উপরের effect শুধু দোকানের নিজস্ব প্রজেক্টের meta/businessConfig
  // থেকে পড়ে — এই দুটোর মাঝে আগে কোনো সংযোগ ছিল না। checkSubscription()
  // CentralBizConfig-এ কেন্দ্রীয় মান রেখে দেয় (দেখুন উপরে); এখানে সেটা দোকানের
  // নিজস্ব প্রজেক্টে বসানো হয় (FSS.setBusinessConfig), যা উপরের
  // subscribeBusinessConfig লিসেনারকে ট্রিগার করে এবং local state-ও আপডেট হয়ে
  // যায়। শুধু admin/owner ডিভাইসে (স্টাফ নয়) এবং শুধু কেন্দ্রীয় লিস্ট local
  // থেকে আলাদা হলেই লেখে — অহেতুক বারবার write এড়াতে।
  useEffect(() => {
    if (!fssReady || !FSS._db || !settingsLoaded) return;
    if (currentUser?.role === "staff") return;
    const central = CentralBizConfig.enabledBusinessTypes;
    if (!central || !central.length) return;
    const sameList = Array.isArray(enabledBusinessTypes) &&
      enabledBusinessTypes.length === central.length &&
      enabledBusinessTypes.every(bt => central.includes(bt));
    if (sameList) return;
    // activeBusinessType: কেন্দ্রীয় active টাইপ নতুন লিস্টে থাকলে সেটাই ধরা হয়,
    // নাহলে দোকানের বর্তমান businessType (এখনো enabled থাকলে) বা নতুন লিস্টের
    // প্রথমটা — owner ইচ্ছাকৃতভাবে যেটায় আছে সেখান থেকে অহেতুক সরানো হবে না।
    const nextActive = central.includes(CentralBizConfig.activeBusinessType)
      ? CentralBizConfig.activeBusinessType
      : (central.includes(businessType) ? businessType : central[0]);
    setEnabledBusinessTypes(central);
    if (nextActive !== businessType) setBusinessType(nextActive);
    FSS.setBusinessConfig(nextActive, businessTypeLocked, central);
  }, [fssReady, settingsLoaded, businessType, businessTypeLocked, enabledBusinessTypes, currentUser?.role, appResyncTick]);

  // 🆕 ধাপ ৫ (Staff Permission System, ১৮ জুলাই ২০২৬): স্টাফের businessType সবসময়
  // owner-assigned মান (currentUser.assignedBusinessType) দিয়ে লক থাকবে — উপরের
  // effect-এ owner-এর shop-wide সুইচ স্টাফের জন্য স্কিপ করা হয়েছে, এই effect-ই এখন
  // স্টাফের ফোনে businessType-এর একমাত্র উৎস। enabledBusinessTypes.length <= 1
  // (বর্তমান ৫০০ শপের সবগুলোতেই) হলে assignedBusinessType থাকলেও সেটা একমাত্র
  // enabled টাইপের সমান হবে — অর্থাৎ no-op, existing আচরণ অক্ষুণ্ণ।
  // assignedBusinessType না থাকলে (পুরনো স্টাফ রেকর্ড, বা owner এখনো assign করেননি)
  // কিছুই করে না — আগের মতোই বর্তমান businessType-এ থেকে যায়, ভাঙে না।
  useEffect(() => {
    if (currentUser?.role !== "staff") return;
    const assigned = currentUser.assignedBusinessType;
    if (!assigned) return;
    if (!Array.isArray(enabledBusinessTypes) || !enabledBusinessTypes.includes(assigned)) return;
    if (assigned !== businessType) setBusinessType(assigned);
  }, [currentUser, enabledBusinessTypes, businessType, setBusinessType]);

  // 🆕 ধাপ ২: enabledBusinessTypes.length > 1 (সত্যিকারের multi-business শপ)
  // হলেই কেবল FSS.col()/doc() collection-prefix লাগায় — single-business শপে
  // (বর্তমানে সবাই) prefix সবসময় null থাকে, ফলে Firestore-এ কোনো ডেটা migrate
  // করার দরকারই পড়ে না (দেখুন Multi-Business-System-Plan.md-এ আলোচিত conflict)।
  const _lastAppliedBizPrefixRef = useRef(undefined); // undefined = এখনো একবারও সেট হয়নি
  useEffect(() => {
    if (!fssReady) return;
    const isMultiBusiness = Array.isArray(enabledBusinessTypes) && enabledBusinessTypes.length > 1;
    const prefix = isMultiBusiness ? (BUSINESS_TYPE_REGISTRY[businessType]?.collectionPrefix || null) : null;
    FSS.setBusinessPrefix(prefix);
    // 🔴 ফিক্স (মাল্টি-বিজনেস কন্টামিনেশন — local cache namespacing): Firestore
    // prefix-এর সাথে সাথেই local storage/IndexedDB prefix (LK) আপডেট হয় — নাহলে
    // নিচের persistence effect-গুলো ভুল (আগের বিজনেসের) local key-তে সেভ করে ফেলত।
    setLocalBusinessPrefix(prefix);
    // 🔴 ফিক্স (ডিফেন্স-ইন-ডেপথ — মাল্টি-বিজনেস ক্রস-কনটামিনেশন): boot-race
    // ফিক্স (দেখুন CRITICAL_KEYS-এর কমেন্ট) মূল কারণটা বন্ধ করে দিলেও, businessType/
    // enabledBusinessTypes ভবিষ্যতে অন্য কোনো পথে (যেমন remote businessConfig
    // sync, বা admin.html bridge) বদলে গেলে এই effect আবার চলবে ও prefix বদলে
    // যাবে — কিন্তু আগে এখানে শুধু FSS.setBusinessPrefix() কল হতো, কোনো
    // resubscribe ট্রিগার হতো না। useFSSCollection("products"/"customers"...)
    // তখন পরবর্তী heartbeat/resume (সর্বোচ্চ ~২০s) পর্যন্ত পুরনো prefix-এর
    // কালেকশনেই সাবস্ক্রাইব থেকে যেত — এই উইন্ডোতেই local-only push ভুল
    // কালেকশনে ডেটা লিখে দিতে পারত। এখন prefix সত্যিই বদলালে (প্রথমবার সেট
    // হওয়া বাদে) সাথে সাথে _bumpBusinessSwitch()+_bumpGlobalResync() কল করে
    // তৎক্ষণাৎ সঠিক prefix দিয়ে resubscribe বাধ্য করা হচ্ছে — handleSwitchBusiness()
    // যেভাবে করে ঠিক সেভাবেই।
    if (_lastAppliedBizPrefixRef.current !== undefined && _lastAppliedBizPrefixRef.current !== prefix) {
      _bumpBusinessSwitch();
      _bumpGlobalResync();
      // 🆕 ফিক্স (২০ জুলাই ২০২৬ — বিজনেসওয়াইজ আলাদা থিম): থিম/ডার্কমোড/ফন্টসাইজ
      // Firestore-এ সিঙ্ক হয় না (ডিভাইস-লোকাল প্রেফারেন্স), তাই businessType
      // বদলালে useFSSCollection resubscribe এগুলো এমনিতে রিফ্রেশ করবে না —
      // নতুন prefix (উপরে সেট হয়ে গেছে) দিয়ে এই বিজনেসের নিজস্ব সেভ করা থিম
      // এখানে সরাসরি লোকাল storage থেকে পড়ে state আপডেট করা হচ্ছে। প্রথমবার
      // এই বিজনেসে থিম সেট না থাকলে অ্যাপ-ডিফল্টে ফিরে যায় (boot-এর সাথে সঙ্গতিপূর্ণ)।
      (async () => {
        const [dm, at, fs] = await Promise.all([
          load(LK(SK.darkMode)), load(LK(SK.activeTheme)), load(LK(SK.fontSize)),
        ]);
        setDarkMode(dm ?? true);
        setActiveTheme((at && at !== "dark") ? at : "linearvoid");
        setFontSize(fs ?? 15);
      })();
    }
    _lastAppliedBizPrefixRef.current = prefix;
  }, [fssReady, businessType, enabledBusinessTypes]);

  // ─── কিল-সুইচ লিসেনার — সরানো হয়েছে (২৯ জুলাই ২০২৬, Session A) ──────────────
  // admin.html-এর কেন্দ্রীয় Firebase কানেকশন সম্পূর্ণ সরানোর সাথে সাথে এই
  // দূর-নিয়ন্ত্রিত কিল-সুইচ ফিচারও (admin_config/appVersion → haltSync)
  // অর্থহীন হয়ে যায় — কেন্দ্রীয় সার্ভার আর নেই, তাই সরিয়ে ফেলা হলো।


  // ─── ফেজ D/D1 (ENTERPRISE_MONITORING_PLAN.md) — পিরিওডিক ইনভ্যারিয়েন্ট-চেক ──
  // প্রতি ২০ মিনিটে একবার (ready হওয়ার পর প্রথমবার সাথে সাথেও) নেগেটিভ স্টক ও
  // ক্যাশ-ড্রয়ার mismatch চেক করে — কোনো violation পেলে app_errors-এ লগ হয়
  // (context: "invariant_check:<type>"), admin.html-এর এরর প্যানেলে (ERROR_KB-সহ)
  // সেটা স্বয়ংক্রিয়ভাবে দেখা যায়। runInvariantChecks() নিজে pure/side-effect-free
  // (দেখুন src/logic.js ও tests/logic-tests.mjs) — এখানে শুধু state জোগাড় করে
  // কল করা হচ্ছে এবং ফলাফল লগ করা হচ্ছে।
  useEffect(() => {
    if (!fssReady) return;
    const runCheck = () => {
      try {
        const summary = buildDailySummaryData({ invoices, txns, customers, products, cashLogs, purchaseOrders, returns });
        const violations = runInvariantChecks({
          products,
          opening: summary?.openingCash,
          cashSale: summary?.cashSale,
          joma: summary?.jomaToday,
          withdrawal: summary?.cashOutToday,
        });
        for (const v of violations) {
          logErrorToCentral?.(`invariant_check:${v.type}`, new Error(v.message), {}).catch?.(() => {});
        }
      } catch (err) {
        logErrorToCentral?.("invariant_check:runner", err, {}).catch?.(() => {});
      }
    };
    runCheck(); // ready হওয়ার পর প্রথমবার সাথে সাথেই
    const intervalId = setInterval(runCheck, 20 * 60 * 1000); // প্রতি ২০ মিনিটে
    return () => clearInterval(intervalId);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [fssReady, invoices, txns, customers, products, cashLogs, purchaseOrders]);

  // ── প্রতিটা collection — local array ↔ Firestore (record-level, real-time) ──
  // 🔴 ফিক্স: customers-এও products-এর মতো একই bug ছিল — diff-ভিত্তিক অটো-ডিলিট
  // sync layer আর এখানে বন্ধ, শুধু Customers পেজের ইচ্ছাকৃত Delete বাটন থেকে
  // সরাসরি FSS.deleteRecord("customers", id) কল হয়।
  useFSSCollection("customers", customers, setCustomers, fssReady, { onSync: setSyncToast, syncDeletes: false });
  useFSSCollection("products", products, setProducts, fssReady, {
    onSync: setSyncToast,
    filterIncoming: (arr) => {
      const deletedIds = new Set((deletedProducts || []).map(p => p.id));
      return arr.filter(p => !deletedIds.has(p.id));
    },
    // 🔴 ফিক্স: products-এ diff-ভিত্তিক অটো-ডিলিট বন্ধ — লোকাল তালিকা সাময়িকভাবে
    // অসম্পূর্ণ/স্টেল হলেও (Firestore ক্যাশ রেসের কারণে) পণ্য আর ভুলবশত Firestore
    // থেকে মুছে যাবে না। প্রকৃত ডিলিট এখন Products পেজের "🗑️ Delete" বাটন থেকে
    // সরাসরি FSS.deleteRecord("products", id) কল করে হয়।
    syncDeletes: false,
  });

  // ── Phase 1.2: Invoice Windowed Sync — শুধু শেষ ৬ মাসের ইনভয়েস real-time ──
  // আগে: useFSSCollection("invoices"...) → পুরো collection (১০ লাখেও সব pull)
  // এখন: শুধু ৬ মাসের window — ১০ লাখ invoice-এও app চলে, Firestore cost ৯৯%+ কম।
  // ৬ মাসের বেশি পুরনো ইনভয়েস লাইভ state-এ না রেখে নিচের archiveOldInvoices()
  // দিয়ে লোকাল IndexedDB আর্কাইভে (InvoiceArchive) সরানো হয় — Firestore-এ
  // সেগুলো অপরিবর্তিতই থাকে (শুধু এই ডিভাইসের লাইভ মেমরি/UI-তে রাখা হয় না)।
  // পুরনো invoice দেখতে হলে → Invoice History page, এখন লোকাল আর্কাইভ থেকে
  // (দেখুন ReturnModule-এর searchInvoice/loadInvHistPage/loadVoidHist), তাই
  // ইন্টারনেট ছাড়াই কাজ করে। Firestore index লাগবে: invoices → date (ASC)।
  useEffect(() => {
    if (!fssReady || !FSS._db) return;
    // 🔴 উপরের গার্ড সবসময় true — নিচের Firestore windowed-listener লজিক মৃত
    // কোড ছিল, Firebase সরানোর সাথে (২৯ জুলাই ২০২৬, Session A) বাদ দেওয়া হলো।
    // ইনভয়েস ডেটা এখন সম্পূর্ণভাবে লোকাল state/IndexedDB থেকেই আসে।
  }, [fssReady, appResyncTick]); // eslint-disable-line react-hooks/exhaustive-deps

  // ══════════════════════════════════════════════════════════════════════════
  // 🆕 archiveOldInvoices() — ৬ মাসের বেশি পুরনো ইনভয়েস লাইভ invoices state থেকে
  // সরিয়ে InvoiceArchive (IndexedDB)-তে রাখে। বুট-টাইমে (প্রথম পেইন্টের পরে,
  // setTimeout 0-এ) একবার চলে, আর অ্যাপ দীর্ঘক্ষণ খোলা থাকলে (রেয়ার কেস) প্রতি
  // ৬ ঘণ্টায় একবার নিঃশব্দে রিচেক করার জন্য একটা ইন্টারভ্যাল — stale-closure
  // এড়াতে invoicesRef ব্যবহার করা হয়েছে।
  // 🔴 ফিক্স (রুট কজ — ফুল-অফলাইন দোকানে ফিচারটাই কখনো চলত না): এই অ্যাপ
  // Firebase ছাড়াই সম্পূর্ণ চলার জন্য ডিজাইন করা — ইনভয়েস তৈরির সময়ই
  // pushDurable()+LK(SK.invoices) দিয়ে লোকালি durable হয়ে যায় (Firestore
  // _serverTs-এর উপর নির্ভর করে না, দেখুন createInvoice())। তাই এখানে
  // (ক) স্টেল-ফিল্টারে "inv._serverTs" শর্ত রাখা ভুল ছিল — Firebase কখনো চালু
  // না থাকা দোকানে _serverTs কোনোদিনই বসত না, ফলে আর্কাইভিং কখনো ঘটতই না;
  // (খ) নিচের বুট-effect আগে fssReady-এর উপর গেট করা ছিল, যা একই কারণে ভুল —
  // firebaseEnabled/config না থাকলে fssReady চিরকাল false থেকে যায়। এখন শুধু
  // "loaded" (লোকাল বুট শেষ) চেক করা হয় — Firebase চালু/বন্ধ যেকোনো অবস্থায়
  // আর্কাইভিং চলবে। সেফটি এখনো বজায় আছে: লোকাল IndexedDB আর্কাইভ-write সফল
  // হলে তবেই লাইভ state থেকে সরানো হয়, নাহলে কিছুই মোছা হয় না।
  // ══════════════════════════════════════════════════════════════════════════
  const invoicesRef = React.useRef(invoices);
  React.useEffect(() => { invoicesRef.current = invoices; }, [invoices]);

  const archiveOldInvoices = React.useCallback(async () => {
    const cur = invoicesRef.current || [];
    const cutoffDate = new Date();
    cutoffDate.setMonth(cutoffDate.getMonth() - 6);
    const cutoff = _dateKeyOf(cutoffDate);
    const stale = cur.filter(inv => (inv.dateKey || "") < cutoff);
    if (!stale.length) return;
    const ok = await InvoiceArchive.putMany(stale);
    if (!ok) return; // আর্কাইভ-write ব্যর্থ → লাইভ state অপরিবর্তিত থাকে, ডেটা হারানোর ঝুঁকি নেই
    const staleIds = new Set(stale.map(i => i.id));
    // 🔴 ফিক্স (এন্ট্রি ২৮ — dualWriteSqlite() লুকানো bug): archiving শুধু লাইভ
    // React state/UI থেকে সরানোর কথা, SQLite থেকে না — কিন্তু dualWriteSqlite()
    // এর diffById() জেনেরিক diff-মেকানিজম prevMapRef-এ id "হারিয়ে গেলে" সেটাকে
    // ডিলিট ধরে নেয়, তাই নিচের setInvoices()-এর ঠিক আগে _dsInvoicesRef থেকেও
    // archived id-গুলো সরিয়ে দিতে হবে — যাতে পরের diff-এ সেগুলো "removed" হিসেবে
    // না ধরা পড়ে এবং SQLite-এর invoices টেবিলে ডেটা থেকেই যায় (true lifetime
    // history/RFM-এর জন্য প্রয়োজনীয়)।
    staleIds.forEach((id) => { _dsInvoicesRef.current.delete(id); });
    // 🆕 এন্ট্রি ৪৮ — এখানে ইচ্ছাকৃতভাবে _dsInvoiceItemsRef-এ একই "delete before
    // remove" ট্রিক প্রয়োগ করা হয়নি: invoiceItems শুধু productSales-এর ৯০-দিনের
    // window-এর জন্য (lifetime history দরকার নেই, invoices টেবিলের মতো না), আর
    // এই আর্কাইভ-কাটঅফই ৬ মাস — তাই আর্কাইভ হওয়া ইনভয়েসের লাইন-আইটেম রো এমনিতেও
    // কখনো productSales কোয়েরিতে ব্যবহৃত হতো না। dualWriteInvoiceItems() পরের
    // রেন্ডারে এই id-গুলোকে স্বাভাবিকভাবেই "removed" ধরে invoiceItems থেকে মুছে
    // দেবে (schema.sql-এর invoiceItems কমেন্টে বিস্তারিত)।
    setInvoices(prev => prev.filter(i => !staleIds.has(i.id)));
  }, []);

  React.useEffect(() => {
    if (!loaded) return; // শুধু লোকাল বুট শেষ হওয়ার অপেক্ষা — Firebase/fssReady-নির্ভর নয়
    const t = setTimeout(() => { archiveOldInvoices(); }, 0);
    const intervalId = setInterval(() => { archiveOldInvoices(); }, 6 * 60 * 60 * 1000); // প্রতি ৬ ঘণ্টায় নিঃশব্দে রিচেক
    return () => { clearTimeout(t); clearInterval(intervalId); };
  }, [loaded, archiveOldInvoices]);

  // ── txns Windowed Sync — শুধু শেষ ৩০ দিনের লেনদেন real-time ("আজকের বাকি/জমা"
  // ড্যাশবোর্ড হিসাবের জন্য এতটুকুই যথেষ্ট)। আগে: পুরো collection pull, ১০ লাখ
  // ইনভয়েসে txns-ও একই স্কেলে বাড়ত। নতুন txn তৈরি হলে addTxn()-এর ভেতরেই
  // সরাসরি Firestore-এ push হয়। Firestore index লাগবে: txns → dateKey (ASC)।
  useEffect(() => {
    if (!fssReady || !FSS._db) return;
    // 🔴 মৃত কোড ছিল (Firebase সরানো হয়েছে, ২৯ জুলাই ২০২৬, Session A)।
  }, [fssReady, appResyncTick]); // eslint-disable-line react-hooks/exhaustive-deps

  // ── কাস্টমার ডিটেইল পেজে পূর্ণ লেনদেন-ইতিহাস — windowed txns (৩০ দিন) যথেষ্ট না,
  // তাই কাস্টমার ডিটেইল খোলার সময় সেই নির্দিষ্ট কাস্টমারের জন্য আলাদা Firestore
  // query চালিয়ে সম্পূর্ণ ইতিহাস (কতদিন আগের হোক না কেন) আনা হয়। অফলাইনে বা
  // fetch ব্যর্থ হলে windowed local txns-এই fallback করে (নিচে দেখুন)।
  const [customerTxnsFull, setCustomerTxnsFull] = useState({ customerId: null, rows: null });
  useEffect(() => {
    if (!detailCId || !fssReady || !FSS._db) { setCustomerTxnsFull({ customerId: null, rows: null }); return; }
    // 🔴 উপরের গার্ড সবসময় true — নিচের Firestore-নির্ভর ফুল-হিস্ট্রি ফেচ মৃত
    // কোড ছিল (Firebase সরানো হয়েছে, ২৯ জুলাই ২০২৬, Session A)। windowed
    // লোকাল txns-ই এখন একমাত্র উৎস।
  }, [detailCId, fssReady]);
  // 🆕 পারফরম্যান্স ফিক্স (২৫ জুলাই ২০২৬ — কাস্টমার ডিটেইল পেজ ল্যাগ): আগে এই
  // filter()-গুলো সরাসরি JSX-এ ইনলাইন হতো, ফলে প্রতি re-render-এ নতুন array
  // রেফারেন্স তৈরি হতো এবং CustomerDetail-এর React.memo সম্পূর্ণ অকেজো হয়ে
  // যেত (props সবসময় "বদলেছে" মনে হতো)। এখন useMemo দিয়ে স্থিতিশীল রেফারেন্স।
  const detailTxns = useMemo(
    () => (customerTxnsFull.customerId === detailCId && customerTxnsFull.rows)
      ? customerTxnsFull.rows
      : txns.filter(t => t.customerId === detailCId),
    [customerTxnsFull, detailCId, txns]
  );
  const detailPaymentInvoices = useMemo(
    () => paymentInvoices.filter(p => p.customerId === detailCId),
    [paymentInvoices, detailCId]
  );
  // 🔴 ফিক্স (products/customers-এর মতোই সুরক্ষা): smsLog-এ প্রতিটা নতুন SMS
  // পাঠানোর সময় ৯০ দিনের বেশি পুরনো এন্ট্রি লোকালি ছাঁটাই হয় (sendSMS দেখুন) —
  // এটা নিছক লোকাল স্টোরেজ ম্যানেজমেন্ট, ইউজারের ইচ্ছাকৃত ডিলিট না। syncDeletes
  // আগে default true থাকায় এই ছাঁটাই সরাসরি Firestore delete-এ পরিণত হতো —
  // SMS হিস্ট্রি সব ডিভাইস থেকেই স্থায়ীভাবে মুছে যেত। এখন merge-only (bookkeeping
  // শুধু লোকাল), কোনো auto-delete Firestore-এ যাবে না।
  useFSSCollection("smsLog", smsLog, setSmsLog, fssReady, { onSync: setSyncToast, syncDeletes: false });
  // 🔴 ফিক্স (প্রিভেন্টিভ — এখনো কোনো UI-delete নেই এই কালেকশনে, কিন্তু
  // ভবিষ্যতে যোগ হলে products-এর প্যাটার্নেই সরাসরি FSS.deleteRecord("suppliers", id)
  // কল করতে হবে; ততক্ষণে stale-cache mass-delete থেকে সুরক্ষিত থাকল)।
  useFSSCollection("suppliers", suppliers, setSuppliers, fssReady, { onSync: setSyncToast, syncDeletes: false });
  // 🔴 ফিক্স (products-এর মতোই সুরক্ষা — stale-cache mass-delete ঝুঁকি): এখন
  // ইচ্ছাকৃত ডিলিট সরাসরি FSS.deleteRecord("purchaseOrders", id) কল করে হয়
  // (দেখুন deletePOGroup)।
  useFSSCollection("purchaseOrders", purchaseOrders, setPurchaseOrders, fssReady, { onSync: setSyncToast, syncDeletes: false });
  // ── stockMovements Windowed Sync — শুধু শেষ ৩০ দিনের মুভমেন্ট real-time ──
  // আগে: useFSSCollection("stockMovements"...) → পুরো collection pull (১০ লাখ
  // ইনভয়েসে stockMovements-ও লাখ ছাড়িয়ে যেত)। এখন: শুধু ৩০ দিনের window —
  // কোনো live UI পুরনো stockMovements read করে না (শুধু backup/export-এ যায়),
  // তাই windowing-এ কোনো ফিচার ভাঙে না। নতুন movement তৈরির সময়
  // pushStockMovement() দিয়ে সরাসরি Firestore-এ লেখা হয় (৭টা creation site)।
  // Firestore index লাগবে: stockMovements → dateKey (ASC)।
  useEffect(() => {
    if (!fssReady || !FSS._db) return;
    // 🔴 মৃত কোড ছিল (Firebase সরানো হয়েছে, ২৯ জুলাই ২০২৬, Session A)।
  }, [fssReady, appResyncTick]); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => {
    if (!fssReady || !FSS._db) return;
    // 🔴 মৃত কোড ছিল (Firebase সরানো হয়েছে, ২৯ জুলাই ২০২৬, Session A)।
  }, [fssReady, appResyncTick]); // eslint-disable-line react-hooks/exhaustive-deps
  // 🔴 ফিক্স: expenses-এও একই প্যাটার্ন — auto-delete বন্ধ, ইচ্ছাকৃত ডিলিট এখন
  // সরাসরি FSS.deleteRecord("expenses", id) কল করে (দেখুন Expenses পেজ)।
  useFSSCollection("expenses", expenses, setExpenses, fssReady, { onSync: setSyncToast, syncDeletes: false });
  useFSSCollection("staffLedger", staffLedger, setStaffLedger, fssReady, { onSync: setSyncToast, syncDeletes: false });
  useFSSCollection("serialQueue", serialQueue, setSerialQueue, fssReady, { onSync: setSyncToast, syncDeletes: false });
  useEffect(() => {
    if (!fssReady || !FSS._db) return;
    // 🔴 মৃত কোড ছিল (Firebase সরানো হয়েছে, ২৯ জুলাই ২০২৬, Session A)।
  }, [fssReady, appResyncTick]); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => {
    if (!fssReady || !FSS._db) return;
    // 🔴 মৃত কোড ছিল (Firebase সরানো হয়েছে, ২৯ জুলাই ২০২৬, Session A)।
  }, [fssReady, appResyncTick]); // eslint-disable-line react-hooks/exhaustive-deps
  // 🔴 ফিক্স (প্রিভেন্টিভ — একই কারণে, দেখুন suppliers-এর কমেন্ট)
  useFSSCollection("quotations", quotations, setQuotations, fssReady, { onSync: setSyncToast, syncDeletes: false });
  // 🔴 ফিক্স: supplierPayments-এও একই প্যাটার্ন — auto-delete বন্ধ, ইচ্ছাকৃত ডিলিট
  // এখন সরাসরি FSS.deleteRecord("supplierPayments", id) কল করে (দেখুন SupplierPayments পেজ)।
  useFSSCollection("supplierPayments", supplierPayments, setSupplierPayments, fssReady, { onSync: setSyncToast, syncDeletes: false });
  // 🔴 ফিক্স (প্রিভেন্টিভ — একই কারণে, দেখুন suppliers-এর কমেন্ট)
  useFSSCollection("paymentInvoices", paymentInvoices, setPaymentInvoices, fssReady, { onSync: setSyncToast, syncDeletes: false });
  // 🗑️ Recycle Bin — এখন সব ডিভাইসে সিঙ্ক হয় (আগে শুধু লোকাল ছিল)
  useFSSCollection("deletedProducts", deletedProducts, setDeletedProducts, fssReady, { onSync: setSyncToast });
  useFSSCollection("deletedCustomers", deletedCustomers, setDeletedCustomers, fssReady, { onSync: setSyncToast });
  // 🔑 users (permissions) — instant push/apply, debounce ছাড়া। এই কালেকশনের
  // write ব্যর্থ হলে (যেমন Firestore Rules ব্লক করলে) আগে সম্পূর্ণ নীরবে ব্যর্থ
  // হতো — অ্যাডমিন বুঝতেই পারতেন না কেন স্টাফের পারমিশন সিঙ্ক হচ্ছে না।
  // এখন ব্যর্থ হলে সরাসরি একটা লাল টোস্ট দেখানো হয়।
  // 🔴 ফিক্স: users-এও একই প্যাটার্ন — auto-delete বন্ধ (স্টাফ অ্যাকাউন্ট ভুলবশত
  // ক্যাশ-রেসে মুছে গেলে লগইনই ভেঙে যেত), ইচ্ছাকৃত ডিলিট এখন সরাসরি
  // FSS.deleteRecord("users", id) কল করে (দেখুন Users পেজ)।
  useFSSCollection("users", users, setUsers, fssReady, {
    instant: true,
    onSync: (v) => { setSyncToast?.(v); if (v === "error") showToast?.("⚠️ স্টাফ/পারমিশন সিঙ্ক ব্যর্থ হয়েছে — Firestore Rules চেক করুন", "#ef4444"); },
    syncDeletes: false,
  });
  useFSSSettings(fssReady, shopName, setShopName, smsTemplates, setSmsTemplates, smsGateway, setSmsGateway, googleDriveToken, setGoogleDriveToken, appResyncTick);

  // ── Phase 1.3: Stats doc real-time subscribe — Dashboard আজকের totals ───────
  // todayInvs.reduce() এর বদলে একটা ছোট Firestore doc থেকে instant read।
  // Invoice save/void-এ FSS.updateStats() call করলে এখানে auto-update আসবে।
  useEffect(() => {
    if (!fssReady || !FSS._db) return;
    const todayKey = _dateKeyOf(new Date()); // "YYYY-MM-DD"
    const unsub = FSS.subscribeStats(todayKey, (data) => {
      // stats data পেলে Zustand store-এ রাখা যায় অথবা Dashboard-এ prop হিসেবে পাঠানো যায়।
      // আপাতত: পরবর্তী phase-এ Dashboard-কে stats doc থেকে পড়তে হবে।
      // এখন শুধু subscribe করে রাখছি — যাতে connection warm থাকে।
      if (data) setSyncToast?.({ msg: null, ok: true }); // silent — no UI noise
    });
    return () => unsub();
  }, [fssReady, appResyncTick]); // eslint-disable-line react-hooks/exhaustive-deps

  // 🔑 admin কোনো স্টাফের permission বদলালে/মুছলে — Firestore থেকে users
  // আপডেট হওয়ার সাথে সাথেই (millisecond-এ) এই ডিভাইসের currentUser-এ প্রতিফলিত
  // হয় (reload/re-login লাগে না); স্টাফ মুছে দিলে সাথে সাথে লগআউট হয়ে যায়।
  useEffect(() => {
    if (!loaded) return;
    setCurrentUser(prev => {
      if (!prev || prev.role !== "staff") return prev;
      const updated = (users || []).find(u => u.id === prev.id);
      if (!updated) {
        showToast?.("আপনার অ্যাকাউন্ট মুছে ফেলা হয়েছে — লগআউট হচ্ছে", "#ef4444");
        return null;
      }
      if (
        JSON.stringify(updated.tempPermissions || []) === JSON.stringify(prev.tempPermissions || []) &&
        JSON.stringify(updated.autoSchedules || []) === JSON.stringify(prev.autoSchedules || []) &&
        !!updated.canAddProduct === !!prev.canAddProduct &&
        (updated.assignedBusinessType || null) === (prev.assignedBusinessType || null)
      ) return prev;
      return { ...prev, tempPermissions: updated.tempPermissions || [], autoSchedules: updated.autoSchedules || [], canAddProduct: !!updated.canAddProduct, assignedBusinessType: updated.assignedBusinessType || null };
    });
  }, [users, loaded]);

  // 🛡️ স্টাফ পারমিশন সিঙ্ক গার্ড — সম্পূর্ণ স্বয়ংসম্পূর্ণ (isolated) hook, নিচে
  // module-level এ সংজ্ঞায়িত (useFSSCollection-এর পাশে)। ভবিষ্যতে App()-এর
  // অন্য কোনো অংশে কোড পরিবর্তন হলেও এই একটি লাইনের বাইরে এটা স্পর্শ হওয়ার
  // কোনো কারণ নেই — critical safety logic ইচ্ছাকৃতভাবে আলাদা রাখা হয়েছে।
  useStaffPermissionGuard(fssReady, loaded, setCurrentUser, setUsers);

  // 🆕 SQLite dual-write (Phase 1) — প্রতিটা businessType/স্টোরের জন্য প্রেভিয়াস
  // id→object স্ন্যাপশট, dualWriteSqlite()-এর diffById()-এর জন্য (দেখুন উপরের
  // module-level কমেন্ট)। businessType বদলালে (Business Switcher) স্বাভাবিকভাবেই
  // customers/products/invoices state-ও নতুন করে লোড হয় (আলাদা LK() key), তাই
  // এই ref রিসেট করারও দরকার নেই — diffById() নতুন অ্যারের সব আইটেমকেই "changed"
  // হিসেবে ধরবে (প্রেভিয়াস ম্যাপে না থাকায়), যা সঠিক আচরণ (নতুন business-এর
  // সব রেকর্ডই সেই business-এর SQLite DB ফাইলে upsert হওয়া উচিত)।
  const _dsCustomersRef = useRef(new Map());
  const _dsProductsRef  = useRef(new Map());
  const _dsInvoicesRef  = useRef(new Map());
  const _dsInvoiceItemsRef = useRef(new Map()); // 🆕 এন্ট্রি ৪৮ — invoiceItems টেবিলের জন্য স্বাধীন diff-স্ন্যাপশট
  // 🆕 এন্ট্রি ৩৭ — useKpiStats-এর ৫টা ডেটা-সোর্সের প্রথম SQL cutover (schema.sql/
  // DataStore.js-এর কমেন্ট দ্রষ্টব্য)
  const _dsExpensesRef  = useRef(new Map());
  // 🆕 এন্ট্রি ৩৮ — বাকি ৪টা
  const _dsCashLogsRef       = useRef(new Map());
  const _dsPurchaseOrdersRef = useRef(new Map());
  const _dsTxnsRef           = useRef(new Map());
  const _dsReturnsRef        = useRef(new Map());
  // 🆕 এন্ট্রি ৩৯
  const _dsStockMovementsRef = useRef(new Map());
  // 🆕 এন্ট্রি ৪১
  const _dsSupplierPaymentsRef = useRef(new Map());

  useEffect(() => { if (loaded) { debouncedSave(LK(SK.customers), customers, 1500); setBackupNeeded(true); dualWriteSqlite(businessType, "customers", _dsCustomersRef, customers); } }, [customers, loaded]);
  useEffect(() => { if (loaded) { debouncedSave(LK(SK.products),  products,  1500); setBackupNeeded(true); dualWriteSqlite(businessType, "products",  _dsProductsRef,  products);  } }, [products, loaded]);
  useEffect(() => { if (loaded) { debouncedSave(LK(SK.invoices),  invoices,  1500); setBackupNeeded(true); dualWriteSqlite(businessType, "invoices",  _dsInvoicesRef,  invoices);  } }, [invoices, loaded]);
  // 🆕 এন্ট্রি ৪৮ — invoiceItems টেবিল dual-write (invoices dual-write-এর ঠিক পাশে, স্বাধীন diff)
  useEffect(() => { if (loaded) { dualWriteInvoiceItems(businessType, _dsInvoiceItemsRef, invoices, globalProdMap); } }, [invoices, loaded]);
  useEffect(() => { if (loaded) { debouncedSave(LK(SK.txns),      txns,      2000); setBackupNeeded(true); dualWriteSqlite(businessType, "txns", _dsTxnsRef, txns); } }, [txns, loaded]);
  useEffect(() => { if (loaded) debouncedSave(LK(SK.smsLog), smsLog, 2000); }, [smsLog, loaded]);
  useEffect(() => { if (loaded) save(SK.users,     users);     }, [users, loaded]);
  useEffect(() => { if (loaded) save(SK.shopName,  shopName);  }, [shopName, loaded]);
  useEffect(() => { if (loaded) save(LK(SK.darkMode),  darkMode);  }, [darkMode, loaded]);
  useEffect(() => { if (loaded) save(LK(SK.activeTheme), activeTheme); }, [activeTheme, loaded]);
  // ── Status Bar color sync ──────────────────────────────────────────────────────
  useEffect(() => {
    if (!currentPreset) return;
    const statusColor = currentPreset.statusBar || currentPreset.bg || "#080f0a";
    // 🔴 ফিক্স: আগে এখানে currentPreset.dark (থিমের স্ট্যাটিক ফ্ল্যাগ) দিয়ে আইকনের
    // রঙ ঠিক হতো — কিন্তু এখন লাইট থিমেও statusColor ভাইব্রেন্ট accent (গাঢ়/মাঝারি
    // luminance) হতে পারে, তখন "dark:false" ধরে "LIGHT" স্টাইল (গাঢ় আইকন) পাঠালে
    // গাঢ় ব্যাকগ্রাউন্ডে গাঢ় আইকন — অদৃশ্যপ্রায় হয়ে যেত। এখন আসল রঙের luminance
    // মেপে ঠিক করা হচ্ছে, থিমের নাম/ফ্ল্যাগ নয়।
    const bgIsLight = relativeLuminance(statusColor) > 0.42;
    const statusBarStyle = bgIsLight ? "LIGHT" : "DARK"; // LIGHT style => গাঢ় আইকন (হালকা bg-তে), DARK style => হালকা আইকন (গাঢ় bg-তে)

    // 1. theme-color meta (Chrome Android WebView, PWA)
    let meta = document.querySelector("meta[name='theme-color']");
    if (!meta) { meta = document.createElement("meta"); meta.name = "theme-color"; document.head.appendChild(meta); }
    meta.setAttribute("content", statusColor);

    // 2. Apple status bar style — bg অনুযায়ী black-translucent/default ঠিক করা
    let appleMeta = document.querySelector("meta[name='apple-mobile-web-app-status-bar-style']");
    if (!appleMeta) { appleMeta = document.createElement("meta"); appleMeta.name = "apple-mobile-web-app-status-bar-style"; document.head.appendChild(appleMeta); }
    appleMeta.setAttribute("content", bgIsLight ? "default" : "black-translucent");

    // 3. Capacitor StatusBar — window.Capacitor.Plugins only (no static import needed)
    // 🔴 ফিক্স: আগে এই কল একবারই fire হতো আর error silently .catch(()=>{}) দিয়ে
    // গিলে ফেলা হতো — থিম পাল্টানোর ঠিক মুহূর্তে (থিম পিকার বন্ধ হওয়া/মডাল
    // transition/animation চলাকালীন) native bridge ব্যস্ত থাকলে কলটা silently
    // miss হয়ে যেত, ফলে বিশেষত ডার্ক থিমে সুইচ করার সময় স্ট্যাটাস বার আগের
    // থিমের রঙেই আটকে থাকত (screenshot-এ ধরা পড়েছে)। এখন কলটা একবার সাথে সাথে,
    // আর নিরাপত্তার জন্য আরও দুইবার (150ms ও 600ms পর) retry করা হয় — একই রঙ
    // বারবার সেট করা সম্পূর্ণ নিরাপদ (idempotent), কিন্তু কোনো একটা কল miss
    // হয়ে গেলেও পরেরটা ঠিক করে দেয়।
    // 4. Android system Navigation Bar (নিচের গেসচার/বাটন বার) — header এখন সলিড
    // কালার (উপরের গ্রেডিয়েন্ট-বাদ ফিক্স দ্রষ্টব্য), তাই সেই একই statusColor
    // ব্যবহার করলে নিচের অ্যাপ-নেভবার (T.header ব্যবহার করে) আর OS-এর সিস্টেম
    // নেভিগেশন বার — দুটোই হুবহু এক রঙ, কোনো সিম/অমিল থাকবে না।
    let cancelled = false;
    const applyNativeStatusBar = () => {
      if (cancelled) return;
      try {
        const SB = window.Capacitor?.Plugins?.StatusBar;
        if (SB && window.Capacitor?.isNativePlatform?.()) {
          SB.setOverlaysWebView({ overlay: false }).catch((e) => console.warn("StatusBar overlay set failed:", e));
          SB.setBackgroundColor({ color: statusColor }).catch((e) => console.warn("StatusBar bg set failed:", e));
          SB.setStyle({ style: statusBarStyle }).catch((e) => console.warn("StatusBar style set failed:", e));
        }
        const NB = window.Capacitor?.Plugins?.NavigationBar;
        if (NB && window.Capacitor?.isNativePlatform?.()) {
          NB.setColor({ color: statusColor, darkButtons: bgIsLight }).catch((e) => console.warn("NavigationBar color set failed:", e));
        }
      } catch (e) { console.warn("StatusBar/NavigationBar sync error:", e); }
    };
    applyNativeStatusBar();
    const retry1 = setTimeout(applyNativeStatusBar, 150);
    const retry2 = setTimeout(applyNativeStatusBar, 600);
    return () => { cancelled = true; clearTimeout(retry1); clearTimeout(retry2); };
  }, [activeTheme, currentPreset]);
  useEffect(() => { if (loaded) save(LK(SK.fontSize), fontSize); }, [fontSize, loaded]);
  useEffect(() => { if (loaded) save(LK(SK.deletedCustomers), deletedCustomers); }, [deletedCustomers, loaded]);
  useEffect(() => { if (loaded) save(LK(SK.deletedProducts),  deletedProducts);  }, [deletedProducts,  loaded]);
  // 🗑️ Recycle Bin auto-cleanup — ৩০ দিনের বেশি পুরনো এন্ট্রি স্থায়ীভাবে সরিয়ে দেয়
  // (_deletedAt না থাকা পুরনো এন্ট্রি স্পর্শ করে না — শুধু নতুন টাইমস্ট্যাম্প-যুক্ত এন্ট্রি চেক করে)
  useEffect(() => {
    if (!loaded) return;
    const THIRTY_DAYS = 30 * 24 * 60 * 60 * 1000;
    const cutoff = Date.now() - THIRTY_DAYS;
    setDeletedProducts(prev => {
      const kept = prev.filter(p => !p._deletedAt || p._deletedAt > cutoff);
      return kept.length === prev.length ? prev : kept;
    });
    setDeletedCustomers(prev => {
      const kept = prev.filter(c => !c._deletedAt || c._deletedAt > cutoff);
      return kept.length === prev.length ? prev : kept;
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [loaded]);
  useEffect(() => { if (loaded) debouncedSave(LK(SK.paymentInvoices), paymentInvoices, 1500); }, [paymentInvoices, loaded]);
  useEffect(() => { if (loaded) save(SK.smsGateway, smsGateway); }, [smsGateway, loaded]);
  useEffect(() => { if (loaded) save(SK.anthropicKey, anthropicKey); }, [anthropicKey, loaded]);
  useEffect(() => { if (loaded) save(SK.smsTemplates, smsTemplates); }, [smsTemplates, loaded]);
  // 🔴 ফিক্স: এই দুইটা `loaded`-এর বদলে `settingsLoaded` দিয়ে গার্ড করা হলো —
  // কারণ এদের real value wave-2 তে (দেরিতে) লোড হয়, `loaded` তার আগেই true
  // হয়ে যায়। আগে `loaded` দেখে save করলে boot-এর প্রথম মুহূর্তে এখনো-default
  // (false) value দিয়ে disk-এর real saved (true) value ওভাররাইট হয়ে যেতে
  // পারত — এটাই ছিল "Auto Sync/Auto Backup টগল নিজে নিজে অফ হয়ে যাওয়া"র কারণ।
  useEffect(() => { if (settingsLoaded) save(SK.autoBackupEnabled, autoBackupEnabled); }, [autoBackupEnabled, settingsLoaded]);
  useEffect(() => { if (settingsLoaded) save(SK.businessType, businessType); }, [businessType, settingsLoaded]);
  useEffect(() => { if (settingsLoaded) save(SK.businessTypeLocked, businessTypeLocked); }, [businessTypeLocked, settingsLoaded]);
  useEffect(() => { if (settingsLoaded) save(SK.enabledBusinessTypes, enabledBusinessTypes); }, [enabledBusinessTypes, settingsLoaded]);
